const originalLaunchApp = useSystemStore.getState().launchApp;

function renderOffline(status: Parameters<typeof buildOfflineFallback>[1]) {
  render(
    <BrowserFallbackPanel
      fallback={buildOfflineFallback(URL, status)}
      canOpenExternally
      onOpenInNewTab={vi.fn()}
      onRetryWithProxy={vi.fn()}
    />
  );
}

beforeEach(() => {
  useDeviceStore.getState().resetDevice();
});

afterEach(() => {
  cleanup();
  useSystemStore.setState({ launchApp: originalLaunchApp });
  useDeviceStore.getState().resetDevice();
});

describe("BrowserFallbackPanel offline page", () => {
  it("says there is no internet and why", () => {
    renderOffline("airplane");

    expect(screen.getByRole("heading", { name: "No internet" })).toBeTruthy();
    expect(screen.getByText("Airplane mode is on")).toBeTruthy();
    expect(screen.getByText(URL)).toBeTruthy();
  });

  it("turns airplane mode off from the page", () => {
    useDeviceStore.getState().setAirplaneMode(true);
    renderOffline("airplane");

    fireEvent.click(screen.getByRole("button", { name: "Turn off airplane mode" }));
    expect(useDeviceStore.getState().airplaneMode).toBe(false);
    expect(useDeviceStore.getState().wifiEnabled).toBe(true);
  });

  it("turns Wi-Fi back on from the page", () => {
    useDeviceStore.getState().setWifiEnabled(false);
    renderOffline("wifi-off");

    fireEvent.click(screen.getByRole("button", { name: "Turn Wi-Fi on" }));
    expect(useDeviceStore.getState().wifiEnabled).toBe(true);
  });

  it("offers only the network settings in a real outage", () => {
    renderOffline("no-internet");

    expect(screen.queryByRole("button", { name: "Turn Wi-Fi on" })).toBeNull();
    expect(screen.queryByRole("button", { name: "Turn off airplane mode" })).toBeNull();
    expect(screen.getByRole("button", { name: "Network settings" })).toBeTruthy();
  });

  it("opens the Network settings page", () => {
    const launchApp = vi.fn();
    useSystemStore.setState({ launchApp });
    renderOffline("wifi-off");

    fireEvent.click(screen.getByRole("button", { name: "Network settings" }));
    expect(launchApp).toHaveBeenCalledWith({ appId: "settings", payload: { section: "network" } });
  });

  it("does not offer to open the site elsewhere while offline", () => {
    renderOffline("airplane");
    expect(screen.queryByRole("button", { name: "Open in your browser" })).toBeNull();
  });

  it("keeps the usual page for a site that refuses to embed", () => {
    render(
      <BrowserFallbackPanel
        fallback={{ title: "Blocked", url: "https://example.com", message: "Refused" }}
        canOpenExternally
        onOpenInNewTab={vi.fn()}
        onRetryWithProxy={vi.fn()}
      />
    );

    expect(screen.getByRole("button", { name: "Open in your browser" })).toBeTruthy();
    expect(screen.queryByRole("button", { name: "Network settings" })).toBeNull();
  });
});

import { ExternalLink, Network, Plane, Settings, Wifi, WifiOff } from "lucide-react";
import { displayHost } from "@/components/apps/browser/site-badge";
import { proxyModeLabels } from "@/lib/browser/proxy";
import type { BrowserFallbackState, OfflineNetworkStatus } from "@/lib/browser/types";
import { useDeviceStore } from "@/stores/device-store";
import { useSystemStore } from "@/stores/system-store";

interface BrowserFallbackPanelProps {
  fallback: BrowserFallbackState;
  canOpenExternally: boolean;
  onOpenInNewTab: () => void;
  onRetryWithProxy: () => void;
}

/** What the visitor can do from the page itself: flip the switch that cut the network. */
const OFFLINE_FIXES: Record<OfflineNetworkStatus, { label: string; icon: typeof Wifi; apply: () => void } | null> = {
  airplane: {
    label: "Turn off airplane mode",
    icon: Plane,
    apply: () => useDeviceStore.getState().setAirplaneMode(false),
  },
  "wifi-off": {
    label: "Turn Wi-Fi on",
    icon: Wifi,
    apply: () => useDeviceStore.getState().setWifiEnabled(true),
  },
  // A real outage has no switch to flip; the page loads again once the connection returns.
  "no-internet": null,
};

/** Shown while the device is offline: airplane mode, Wi-Fi off, or a real outage. */
function BrowserOfflinePanel({ fallback, status }: { fallback: BrowserFallbackState; status: OfflineNetworkStatus }) {
  const launchApp = useSystemStore((state) => state.launchApp);
  const fix = OFFLINE_FIXES[status];

  return (
    <div className="w11-browser__error" role="alert">
      {status === "airplane" ? (
        <Plane className="w11-browser__error-art" size={72} strokeWidth={1.4} color="#8a8a8a" aria-hidden="true" />
      ) : (
        <WifiOff className="w11-browser__error-art" size={72} strokeWidth={1.4} color="#8a8a8a" aria-hidden="true" />
      )}
      <h2>{fallback.title}</h2>
      <p>{fallback.message}</p>
      {fallback.details ? <p className="w11-browser__error-details">{fallback.details}</p> : null}
      <code>{fallback.url}</code>
      <div className="w11-browser__error-actions">
        {fix ? (
          <button type="button" className="w11-button w11-button--accent" onClick={fix.apply}>
            <fix.icon size={14} aria-hidden="true" />
            {fix.label}
          </button>
        ) : null}
        <button
          type="button"
          className={fix ? "w11-button" : "w11-button w11-button--accent"}
          onClick={() => launchApp({ appId: "settings", payload: { section: "network" } })}
        >
          <Settings size={14} aria-hidden="true" />
          Network settings
        </button>
      </div>
    </div>
  );
}

/** Shown when a site refuses to be embedded, worded like a browser's own error page. */
export function BrowserFallbackPanel({ fallback, canOpenExternally, onOpenInNewTab, onRetryWithProxy }: BrowserFallbackPanelProps) {
  if (fallback.offlineStatus) {
    return <BrowserOfflinePanel fallback={fallback} status={fallback.offlineStatus} />;
  }

  const host = displayHost(fallback.url);

  return (
    <div className="w11-browser__error" role="alert">
      <svg className="w11-browser__error-art" width="72" height="72" viewBox="0 0 48 48" aria-hidden="true">
        <rect x="6" y="10" width="36" height="28" rx="4" fill="#3a3a3a" />
        <rect x="6" y="10" width="36" height="7" rx="3" fill="#4a4a4a" />
        <circle cx="11" cy="13.5" r="1.4" fill="#8a8a8a" />
        <circle cx="15.5" cy="13.5" r="1.4" fill="#8a8a8a" />
        <path d="M18 24l12 10M30 24L18 34" stroke="#8a8a8a" strokeWidth="2.6" strokeLinecap="round" />
      </svg>
      <h2>{canOpenExternally ? `${host} refused to connect inside this window` : fallback.title}</h2>
      <p>{fallback.message}</p>
      {fallback.details ? <p className="w11-browser__error-details">{fallback.details}</p> : null}
      <code>{fallback.url}</code>
      <div className="w11-browser__error-actions">
        <button type="button" className="w11-button w11-button--accent" onClick={onOpenInNewTab} disabled={!canOpenExternally}>
          <ExternalLink size={14} aria-hidden="true" />
          Open in your browser
        </button>
        <button type="button" className="w11-button" onClick={onRetryWithProxy} disabled={!fallback.retryProxyMode}>
          <Network size={14} aria-hidden="true" />
          {fallback.retryProxyMode ? `Try ${proxyModeLabels[fallback.retryProxyMode]}` : "Try a proxy"}
        </button>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState, type KeyboardEvent, type MouseEvent } from "react";
import { Check, Copy, ExternalLink, History, Plus } from "lucide-react";
import { HistoryPage, NewTabPage } from "@/components/apps/browser/internal-pages";
import { SiteBadge } from "@/components/apps/browser/site-badge";
import { BrowserToolbar, type SiteSecurity } from "@/components/apps/browser/browser-toolbar";
import { BrowserViewport } from "@/components/apps/browser/browser-viewport";
import { useBrowserState } from "@/components/apps/browser/useBrowserState";
import type { ProxyMode } from "@/lib/browser/proxy";
import { getBrowserTitleFromUrl, HISTORY_URL, NEW_TAB_URL } from "@/lib/browser/urlUtils";
import { cn } from "@/lib/utils";
import { useBrowserStore } from "@/stores/browser-store";
import { useShellStore } from "@/stores/shell-store";
import type { ContextMenuAction, FileSystemRecord } from "@/types/system";

export interface BrowserTabMeta {
  title: string;
  url: string;
  loading: boolean;
}

interface BrowserTabProps {
  tabId: string;
  active: boolean;
  initialAddress: string;
  nodes: FileSystemRecord;
  onMeta: (tabId: string, meta: BrowserTabMeta) => void;
  onNewTab: (address?: string) => void;
}

const PROXY_OPTIONS: Array<{ mode: ProxyMode; label: string }> = [
  { mode: "direct", label: "Load directly" },
  { mode: "allorigins", label: "Load through the AllOrigins proxy" },
  { mode: "wayback", label: "Load from the Web Archive" },
];

/** One browser tab: its own history, toolbar and page. Hidden tabs stay mounted so their pages keep running. */
export function BrowserTab({ tabId, active, initialAddress, nodes, onMeta, onNewTab }: BrowserTabProps) {
  const {
    address,
    setAddress,
    currentUrl,
    proxyMode,
    setProxyMode,
    viewMode,
    loadState,
    fallback,
    resolvedDocument,
    isInternal,
    refreshToken,
    canGoBack,
    canGoForward,
    visit,
    goBack,
    goForward,
    reload,
    retryWithProxy,
    handleFrameLoad,
    handleFrameError,
  } = useBrowserState({ initialAddress, nodes });

  const favorites = useBrowserStore((state) => state.favorites);
  const toggleFavorite = useBrowserStore((state) => state.toggleFavorite);
  const recordVisit = useBrowserStore((state) => state.recordVisit);
  const setContextMenu = useShellStore((state) => state.setContextMenu);
  const [focusAddressNonce, setFocusAddressNonce] = useState(0);

  const remoteUrl = resolvedDocument?.kind === "remote" ? resolvedDocument.displayUrl : null;
  const title = isInternal ? getBrowserTitleFromUrl(currentUrl) : resolvedDocument?.title ?? getBrowserTitleFromUrl(currentUrl);
  const isFavorite = Boolean(remoteUrl && favorites.some((favorite) => favorite.url === remoteUrl));
  const security: SiteSecurity = isInternal
    ? "internal"
    : resolvedDocument?.kind === "local"
      ? "local"
      : remoteUrl?.startsWith("https:")
        ? "secure"
        : "insecure";

  useEffect(() => {
    onMeta(tabId, { title, url: currentUrl, loading: loadState === "loading" });
  }, [currentUrl, loadState, onMeta, tabId, title]);

  // Each web page lands in History once per navigation.
  useEffect(() => {
    if (remoteUrl) recordVisit(remoteUrl, title);
  }, [recordVisit, remoteUrl, title]);

  const openExternally = useCallback(() => {
    // Only ever a normalized http(s) URL, opened without a referrer or a handle back to this page.
    if (remoteUrl) globalThis.open(remoteUrl, "_blank", "noopener,noreferrer");
  }, [remoteUrl]);

  const toggleCurrentFavorite = () => {
    if (remoteUrl) toggleFavorite({ url: remoteUrl, label: title });
  };

  const openMenu = (event: MouseEvent<HTMLButtonElement>) => {
    // The desktop closes menus on click; keep this click from reaching it.
    event.stopPropagation();
    const rect = event.currentTarget.getBoundingClientRect();
    const actions: ContextMenuAction[] = [
      { id: "new-tab", label: "New tab", icon: Plus, onSelect: () => onNewTab() },
      { id: "history", label: "History", icon: History, shortcut: "Ctrl+H", onSelect: () => visit(HISTORY_URL) },
      { id: "sep-1", label: "", separator: true, onSelect: () => {} },
      { id: "external", label: "Open in your browser", icon: ExternalLink, disabled: !remoteUrl, onSelect: openExternally },
      {
        id: "copy-link",
        label: "Copy link",
        icon: Copy,
        disabled: !remoteUrl,
        onSelect: () => {
          if (remoteUrl) void navigator.clipboard?.writeText(remoteUrl).catch(() => undefined);
        },
      },
      { id: "sep-2", label: "", separator: true, onSelect: () => {} },
      ...PROXY_OPTIONS.map<ContextMenuAction>((option) => ({
        id: `proxy-${option.mode}`,
        label: option.label,
        icon: proxyMode === option.mode ? Check : undefined,
        disabled: !remoteUrl,
        onSelect: () => setProxyMode(option.mode),
      })),
    ];
    setContextMenu({ x: rect.right - 260, y: rect.bottom + 4, title: "Settings and more", actions });
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const key = event.key.toLowerCase();
    const ctrl = event.ctrlKey || event.metaKey;

    if (ctrl && key === "l") {
      event.preventDefault();
      setFocusAddressNonce((value) => value + 1);
    } else if (ctrl && key === "d") {
      event.preventDefault();
      toggleCurrentFavorite();
    } else if (ctrl && key === "h") {
      event.preventDefault();
      visit(HISTORY_URL);
    } else if (event.key === "F5" || (ctrl && key === "r")) {
      event.preventDefault();
      reload();
    } else if (event.altKey && event.key === "ArrowLeft") {
      event.preventDefault();
      goBack();
    } else if (event.altKey && event.key === "ArrowRight") {
      event.preventDefault();
      goForward();
    } else if (event.altKey && event.key === "Home") {
      event.preventDefault();
      visit(NEW_TAB_URL);
    }
  };

  return (
    <div className={cn("w11-browser__panel", active && "is-active")} role="tabpanel" aria-hidden={!active} onKeyDown={handleKeyDown}>
      <BrowserToolbar
        address={address}
        security={security}
        loadState={loadState}
        canGoBack={canGoBack}
        canGoForward={canGoForward}
        isFavorite={isFavorite}
        canFavorite={Boolean(remoteUrl)}
        focusAddressNonce={focusAddressNonce}
        onAddressChange={setAddress}
        onSubmit={() => visit(address)}
        onRevert={() => setAddress(currentUrl)}
        onBack={goBack}
        onForward={goForward}
        onReload={reload}
        onHome={() => visit(NEW_TAB_URL)}
        onToggleFavorite={toggleCurrentFavorite}
        onMenu={openMenu}
      />

      {favorites.length > 0 ? (
        <div className="w11-browser__favorites" role="toolbar" aria-label="Favorites">
          {favorites.map((favorite) => (
            <button key={favorite.url} type="button" className="w11-browser__favorite" title={favorite.url} onClick={() => visit(favorite.url)}>
              <SiteBadge url={favorite.url} size={16} />
              <span>{favorite.label}</span>
            </button>
          ))}
        </div>
      ) : null}

      <section className="browser-app__viewport w11-browser__viewport">
        {isInternal ? (
          currentUrl === HISTORY_URL ? <HistoryPage onVisit={visit} /> : <NewTabPage onVisit={visit} />
        ) : (
          <BrowserViewport
            document={resolvedDocument}
            viewMode={viewMode}
            loadState={loadState}
            fallback={fallback}
            refreshToken={refreshToken}
            canOpenExternally={Boolean(remoteUrl)}
            onLocalNavigate={visit}
            onFrameLoad={handleFrameLoad}
            onFrameError={handleFrameError}
            onOpenInNewTab={openExternally}
            onRetryWithProxy={retryWithProxy}
          />
        )}
      </section>
    </div>
  );
}

