import { BrowserViewport } from "@/components/apps/browser/browser-viewport";
import type { BrowserResolvedDocument } from "@/lib/browser/types";

const noop = vi.fn();

function renderViewport(document: BrowserResolvedDocument) {
  render(
    <BrowserViewport
      document={document}
      viewMode="web"
      loadState="ready"
      fallback={null}
      refreshToken={0}
      canOpenExternally
      onLocalNavigate={noop}
      onFrameLoad={noop}
      onFrameError={noop}
      onOpenInNewTab={noop}
      onRetryWithProxy={noop}
    />,
  );
}

describe("BrowserViewport sandbox policy", () => {
  it("does not allow scripts in local srcDoc previews", () => {
    renderViewport({
      kind: "local",
      localKind: "file",
      title: "Local preview",
      displayUrl: "/Documents/test.html",
      note: "Local file",
      frameSource: {
        kind: "srcDoc",
        value: "<p>hello</p>",
      },
    });

    const frame = screen.getByTitle("Local preview");
    expect(frame.getAttribute("sandbox")).not.toContain("allow-scripts");
    expect(frame.getAttribute("sandbox")).toContain("allow-same-origin");
  });

  it("keeps script support for remote browser pages", () => {
    renderViewport({
      kind: "remote",
      title: "Remote page",
      displayUrl: "https://example.com",
      note: "Remote page",
      frameSource: {
        kind: "src",
        value: "https://example.com",
      },
    });

    expect(screen.getByTitle("Remote page").getAttribute("sandbox")).toContain("allow-scripts");
  });
});

import { useCallback, useRef } from "react";
import { BrowserFallbackPanel } from "@/components/apps/browser/browser-fallback-panel";
import type {
  BrowserFallbackState,
  BrowserLoadState,
  BrowserResolvedDocument,
  ViewMode,
} from "@/lib/browser/types";

declare module "react" {
  interface IframeHTMLAttributes<T> extends React.HTMLAttributes<T> {
    credentialless?: "credentialless";
  }
}

interface BrowserViewportProps {
  document: BrowserResolvedDocument | null;
  viewMode: ViewMode;
  loadState: BrowserLoadState;
  fallback: BrowserFallbackState | null;
  refreshToken: number;
  canOpenExternally: boolean;
  onLocalNavigate: (path: string) => void;
  onFrameLoad: () => void;
  onFrameError: () => void;
  onOpenInNewTab: () => void;
  onRetryWithProxy: () => void;
}

const REMOTE_FRAME_SANDBOX =
  "allow-downloads allow-forms allow-modals allow-pointer-lock allow-popups allow-presentation allow-same-origin allow-scripts";
const LOCAL_FRAME_SANDBOX =
  "allow-downloads allow-forms allow-modals allow-pointer-lock allow-popups allow-presentation allow-same-origin";

export function BrowserViewport({
  document,
  viewMode,
  loadState,
  fallback,
  refreshToken,
  canOpenExternally,
  onLocalNavigate,
  onFrameLoad,
  onFrameError,
  onOpenInNewTab,
  onRetryWithProxy,
}: BrowserViewportProps) {
  const iframeRef = useRef<HTMLIFrameElement | null>(null);
  const supportsCredentialless =
    typeof HTMLIFrameElement !== "undefined" &&
    "credentialless" in HTMLIFrameElement.prototype;

  const handleFrameLoad = useCallback(() => {
    if (document?.kind === "local" && document.localKind === "directory") {
      try {
        const frameDocument = iframeRef.current?.contentDocument;

        if (frameDocument && frameDocument.body.dataset.browserLocalBound !== "true") {
          frameDocument.addEventListener("click", (event) => {
            const target = event.target;

            if (!(target instanceof Element)) {
              return;
            }

            const activator = target.closest("[data-browser-path]");

            if (!(activator instanceof HTMLElement)) {
              return;
            }

            const targetPath = activator.getAttribute("data-browser-path");

            if (!targetPath) {
              return;
            }

            event.preventDefault();
            onLocalNavigate(targetPath);
          });

          frameDocument.body.dataset.browserLocalBound = "true";
        }
      } catch {
        // Ignore failure to bind local directory navigation inside iframe content.
      }
    }

    onFrameLoad();
  }, [document, onFrameLoad, onLocalNavigate]);

  if (viewMode === "fallback") {
    const fallbackState = fallback ?? {
      title: document?.title ?? "Unable to open page",
      url: document?.displayUrl ?? "No URL available",
      message: "This site cannot be embedded due to browser restrictions",
    };

    return (
      <BrowserFallbackPanel
        fallback={fallbackState}
        canOpenExternally={canOpenExternally}
        onOpenInNewTab={onOpenInNewTab}
        onRetryWithProxy={onRetryWithProxy}
      />
    );
  }

  if (!document) {
    return (
      <BrowserFallbackPanel
        fallback={{
          title: "Unable to open page",
          url: "No URL available",
          message: "This site cannot be embedded due to browser restrictions",
        }}
        canOpenExternally={canOpenExternally}
        onOpenInNewTab={onOpenInNewTab}
        onRetryWithProxy={onRetryWithProxy}
      />
    );
  }

  return (
    <div className="browser-app__frame-shell" data-state={loadState}>
      {loadState === "loading" ? (
        <div className="browser-app__loading-bar" aria-hidden="true">
          <span />
        </div>
      ) : null}

      <iframe
        ref={iframeRef}
        key={`${document.displayUrl}:${document.frameSource.kind}:${document.frameSource.value}:${refreshToken}`}
        src={document.frameSource.kind === "src" ? document.frameSource.value : undefined}
        srcDoc={document.frameSource.kind === "srcDoc" ? document.frameSource.value : undefined}
        title={document.title}
        sandbox={document.kind === "local" ? LOCAL_FRAME_SANDBOX : REMOTE_FRAME_SANDBOX}
        referrerPolicy="no-referrer"
        credentialless={supportsCredentialless ? "credentialless" : undefined}
        onLoad={handleFrameLoad}
        onError={onFrameError}
      />
    </div>
  );
}

