          {locations.map((location) => {
            const Icon = location.icon;
            const active = activePath === location.path || activePath.startsWith(`${location.path}/`);

            return (
              <Button
                key={location.path}
                type="button"
                variant="panel"
                block
                align="start"
                className={cn("explorer-window__sidebar-item", active && "is-active")}
