import { useMemo, useState } from "react";
import { Download, Printer, Scan, ZoomIn, ZoomOut } from "lucide-react";
import { AppContent, AppScaffold, AppToolbar, ScrollArea } from "@/components/apps/app-layout";
import { getResumeDownloadUrls, resumePdfPath } from "@/data/portfolio";
import { getNodeByPath } from "@/lib/filesystem";
import { formatBytes } from "@/lib/utils";
import { usePdfViewer } from "@/hooks/use-pdf-viewer";
import { useFileSystemStore } from "@/stores/filesystem-store";
import type { AppComponentProps } from "@/types/system";

async function printPdfSource(source: string) {
  const printFrame = document.createElement("iframe");
  printFrame.style.position = "fixed";
  printFrame.style.opacity = "0";
  printFrame.style.pointerEvents = "none";
  printFrame.style.width = "0";
  printFrame.style.height = "0";
  printFrame.src = source;
  document.body.append(printFrame);

  await new Promise<void>((resolve) => {
    printFrame.onload = () => resolve();
  });

  printFrame.contentWindow?.focus();
  printFrame.contentWindow?.print();
  window.setTimeout(() => printFrame.remove(), 1000);
}

export function PdfViewerApp({ window }: AppComponentProps) {
  const nodes = useFileSystemStore((state) => state.nodes);
  const selectedFile = window.payload?.filePath ? getNodeByPath(nodes, window.payload.filePath) : undefined;
  const primarySource =
    selectedFile && selectedFile.kind === "file" ? selectedFile.source ?? resumePdfPath : resumePdfPath;
  const isResumeDocument =
    window.payload?.filePath?.endsWith("Taaniel-Vananurm-CV.pdf") ?? false;
  const [renderMode, setRenderMode] = useState<"browser" | "canvas">(() => (isResumeDocument ? "browser" : "canvas"));
  const pdfSources = useMemo(() => {
    if (isResumeDocument || primarySource === resumePdfPath) {
      return getResumeDownloadUrls();
    }
    return [primarySource];
  }, [isResumeDocument, primarySource]);

  const { canvasRef, errorMessage, loading, pageCount, pageNumber, scale, setPageNumber, setScale, activeSource, allSources } =
    usePdfViewer(pdfSources);

  const fileSize =
    selectedFile?.kind === "file"
      ? selectedFile.size ?? (selectedFile.content != null ? new Blob([selectedFile.content]).size : undefined)
      : undefined;

  return (
    <AppScaffold className="pdf-viewer">
      <AppToolbar className="app-toolbar">
        <div className="app-toolbar__title">
          <strong>{selectedFile?.kind === "file" ? selectedFile.name : "Resume PDF"}</strong>
          <small>
            PDF viewer{fileSize != null ? ` | ${formatBytes(fileSize)}` : ""}
            {pageCount > 0 ? ` | ${pageCount} ${pageCount === 1 ? "page" : "pages"}` : ""}
          </small>
        </div>
        <div className="app-toolbar__group">
          <button
            type="button"
            className="pill-button"
            onClick={() => setRenderMode((mode) => (mode === "canvas" ? "browser" : "canvas"))}
          >
            {renderMode === "canvas" ? "Use browser preview" : "Use renderer"}
          </button>
          <button
            type="button"
            className="icon-button"
            aria-label="Zoom out"
            disabled={renderMode === "browser"}
            onClick={() => setScale((currentScale) => Math.max(0.6, currentScale - 0.15))}
          >
            <ZoomOut size={15} />
          </button>
          <button type="button" className="icon-button" aria-label="Reset zoom" disabled={renderMode === "browser"} onClick={() => setScale(1)}>
            <Scan size={15} />
          </button>
          <button
            type="button"
            className="icon-button"
            aria-label="Zoom in"
            disabled={renderMode === "browser"}
            onClick={() => setScale((currentScale) => Math.min(2.75, currentScale + 0.15))}
          >
            <ZoomIn size={15} />
          </button>
          <label className="pdf-viewer__page-input">
            <span>Page</span>
            <input
              type="number"
              disabled={renderMode === "browser"}
              min={1}
              max={Math.max(1, pageCount)}
              value={pageNumber}
              onChange={(event) => {
                const nextPage = Number(event.target.value);

                if (!Number.isNaN(nextPage)) {
                  setPageNumber(Math.min(Math.max(1, nextPage), Math.max(1, pageCount)));
                }
              }}
            />
          </label>
          <button type="button" className="pill-button" onClick={() => void printPdfSource(activeSource)}>
            <Printer size={15} />
            Print
          </button>
          <a className="pill-button" href={activeSource} download>
            <Download size={15} />
            {isResumeDocument || primarySource === resumePdfPath ? "Download CV" : "Download"}
          </a>
        </div>
      </AppToolbar>

      <AppContent className="pdf-viewer__content" padded={false} scrollable={false}>
        <div className="pdf-viewer__stage">
          <div className="pdf-viewer__meta">
            <span>
              Page {Math.min(pageNumber, Math.max(1, pageCount || 1))} / {Math.max(1, pageCount || 1)}
            </span>
            {renderMode === "canvas" ? <span>Zoom {Math.round(scale * 100)}%</span> : null}
          </div>

          {renderMode === "browser" ? (
            <div className="pdf-viewer__browser">
              <iframe className="resume-app__frame" src={activeSource} title="PDF preview" />
            </div>
          ) : errorMessage ? (
            <div className="pdf-viewer__fallback">
              <strong>PDF preview unavailable</strong>
              <p>{errorMessage}</p>
              <p className="pdf-viewer__fallback-hint">You can still download the file — links try each hosted copy.</p>
              <div className="pdf-viewer__fallback-actions">
                {allSources.map((url) => (
                  <a key={url} className="pill-button" href={url} target="_blank" rel="noreferrer">
                    Open / download
                  </a>
                ))}
              </div>
            </div>
          ) : (
            <ScrollArea className="pdf-viewer__canvas-wrap">
              <canvas ref={canvasRef} />
              {loading ? <div className="pdf-viewer__loading">Rendering page...</div> : null}
            </ScrollArea>
          )}
        </div>
      </AppContent>
    </AppScaffold>
  );
}

