    fireEvent.change(size, { target: { value: "18" } });
    fireEvent.blur(size);
    expect(useTerminalSettingsStore.getState().fontSize).toBe(18);
    fireEvent.change(size, { target: { value: "400" } });
    fireEvent.blur(size);
    expect(size.value).toBe("32");
