import { useRef } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "framer-motion";
import { useDialogFocus } from "@/hooks/use-dialog-focus";
import { getAppDefinition } from "@/lib/app-registry";
import { getOpenWithOptions } from "@/lib/file-registry";
import { getDisplayName } from "@/lib/shortcuts";
import type { AppId, VirtualNode } from "@/types/system";

interface OpenWithDialogProps {
  filePath: string;
  node: VirtualNode;
  onOpen: (appId: AppId) => void;
  onClose: () => void;
}

function OpenWithDialogInner({ filePath, node, onOpen, onClose }: OpenWithDialogProps) {
  const options = getOpenWithOptions(node);
  // Shortcuts show without their .lnk, as everywhere else.
  const fileName = getDisplayName(node) || (filePath.split("/").pop() ?? filePath);
  const dialogRef = useRef<HTMLDivElement>(null);
  useDialogFocus(dialogRef);

  return (
    <div className="open-with-overlay" onPointerDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <motion.div
        ref={dialogRef}
        className="open-with-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="open-with-title"
        aria-describedby="open-with-file"
        initial={{ opacity: 0, scale: 0.94, y: 12 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.96, y: 8 }}
        transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
      >
        <div className="open-with-dialog__header">
          <strong id="open-with-title" className="open-with-dialog__title">Open with</strong>
          <small id="open-with-file" className="open-with-dialog__subtitle">{fileName}</small>
        </div>
        <ul className="open-with-dialog__list">
          {options.map((appId) => {
            const def = getAppDefinition(appId);
            const Icon = def.icon;
            return (
              <li key={appId}>
                <button
                  className="open-with-dialog__item"
                  type="button"
                  onClick={() => { onOpen(appId); onClose(); }}
                >
                  <span className="open-with-dialog__item-icon" style={{ color: def.accent }}>
                    <Icon size={18} />
                  </span>
                  <span className="open-with-dialog__item-label">{def.title}</span>
                </button>
              </li>
            );
          })}
        </ul>
        <div className="open-with-dialog__footer">
          <button className="open-with-dialog__cancel" type="button" onClick={onClose}>
            Cancel
          </button>
        </div>
      </motion.div>
    </div>
  );
}

interface OpenWithDialogPortalProps {
  target: { filePath: string; node: VirtualNode } | null;
  onOpen: (appId: AppId) => void;
  onClose: () => void;
}

export function OpenWithDialog({ target, onOpen, onClose }: OpenWithDialogPortalProps) {
  if (typeof document === "undefined") return null;
  return createPortal(
    <AnimatePresence>
      {target ? (
        <OpenWithDialogInner
          key={target.filePath}
          filePath={target.filePath}
          node={target.node}
          onOpen={onOpen}
          onClose={onClose}
        />
      ) : null}
    </AnimatePresence>,
    document.body
  );
}

import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { formatDateTime, formatSize } from "@/components/apps/explorer/explorer-model";
import { describeFileType } from "@/components/icons/file-icon";
import { NodeIcon } from "@/components/icons/node-icon";
import { useDialogFocus } from "@/hooks/use-dialog-focus";
import { describeProperties } from "@/lib/file-properties";
import { toWindowsPath } from "@/lib/windows-path";
import { useFileSystemStore } from "@/stores/filesystem-store";
import { usePropertiesStore } from "@/stores/properties-store";
import "@/styles/properties-dialog.css";

const count = (amount: number, noun: string) => `${amount} ${noun}${amount === 1 ? "" : "s"}`;

function PropertiesInner({ paths, onClose }: { paths: string[]; onClose: () => void }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const nodes = useFileSystemStore((state) => state.nodes);
  const details = describeProperties(nodes, paths);
  useDialogFocus(dialogRef, { trap: true });

  // The item can go while the dialog is open, say deleted from another window.
  useEffect(() => {
    if (!details) onClose();
  }, [details, onClose]);

  if (!details) return null;

  const { node } = details;
  const inside = details.folders - (node?.kind === "directory" ? 1 : 0);
  const rows: [string, string | null][] = [
    ["Type", node ? describeFileType(node) : "Multiple items"],
    ["Target", details.target && toWindowsPath(details.target)],
    ["Location", details.location && toWindowsPath(details.location)],
    ["Size", formatSize(details.bytes) || "0 bytes"],
    ["Contains", node?.kind === "file" ? null : `${count(details.files, "file")}, ${count(inside, "folder")}`],
    ["Created", details.created ? formatDateTime(details.created) : null],
    ["Modified", details.modified ? formatDateTime(details.modified) : null],
    ["Attributes", details.readOnly ? "Read-only" : "Normal"],
  ];

  return (
    <div className="props-overlay" onPointerDown={(event) => event.target === event.currentTarget && onClose()} onKeyDown={(event) => event.key === "Escape" && (event.stopPropagation(), onClose())}>
      <div ref={dialogRef} className="props w11-flyout" role="dialog" aria-modal="true" aria-labelledby="props-title">
        <header>
          <strong id="props-title">{details.name} Properties</strong>
          <button type="button" aria-label="Close" onClick={onClose}>
            <X size={16} />
          </button>
        </header>
        <div className="props__summary">
          {node ? <NodeIcon node={node} size={32} /> : null}
          <span>{details.name}</span>
        </div>
        <dl className="props__rows">
          {rows.map(([label, value]) =>
            value ? (
              <div key={label}>
                <dt>{label}</dt>
                <dd>{value}</dd>
              </div>
            ) : null
          )}
        </dl>
        <footer>
          <button type="button" className="w11-button w11-button--accent" onClick={onClose}>
            OK
          </button>
        </footer>
      </div>
    </div>
  );
}

export function PropertiesDialog() {
  const paths = usePropertiesStore((state) => state.paths);
  const close = usePropertiesStore((state) => state.close);
  return paths ? createPortal(<PropertiesInner paths={paths} onClose={close} />, document.body) : null;
}

