export function normalizeExtensionKey(extension: string) {
  if (!extension) {
    return "";
  }

  return extension.startsWith(".") ? extension.toLowerCase() : `.${extension.toLowerCase()}`;
}

export function getFileAssociationDescriptor(extension: string) {
  return fileAssociations[normalizeExtensionKey(extension)];
}

export function inferMimeTypeFromExtension(extension: string) {
  return getFileAssociationDescriptor(extension)?.mimeType ?? "application/octet-stream";
}

export function isTextLikeExtension(extension: string) {
  return Boolean(getFileAssociationDescriptor(extension)?.textLike);
}

export function supportsInlinePreview(extensionOrNode: string | VirtualNode | undefined) {
  const association =
    typeof extensionOrNode === "string"
      ? getFileAssociationDescriptor(extensionOrNode)
      : extensionOrNode?.kind === "file"
        ? getFileAssociationDescriptor(extensionOrNode.extension)
        : undefined;

  return Boolean(association?.capabilities.includes("inline-preview"));
}

export function isBrowserRenderableImageExtension(extension: string) {
  const normalized = extension.startsWith(".") ? extension : `.${extension}`;
  const association = getFileAssociationDescriptor(normalized);
  return Boolean(association?.family === "image" && association.browserRenderable);
}

function resolveFallbackApp(node: VirtualNode) {
  if (node.kind === "directory") {
    return "files";
  }

  if (node.mimeType.startsWith("image/")) {
    return "photos";
  }

  if (node.mimeType.startsWith("audio/")) {
    return "music";
  }

  if (node.mimeType.startsWith("video/")) {
    return "video";
  }

  if (node.mimeType === "application/pdf") {
    return "pdf";
  }

  return "editor";
}

export function resolveOpenApp(node?: VirtualNode): AppId {
  if (!node) {
    return "files";
  }

  if (node.kind === "directory") {
    return "files";
  }

  if (isNotesNode(node)) {
    return "notes";
  }

  // Settings > Apps > Default apps. Only apps the Open with list offers are ever stored.
  const chosen = getSystemSettings().defaultApps[normalizeExtensionKey(node.extension)];
  if (chosen && getOpenWithOptionsForExtension(node.extension).includes(chosen)) {
    return chosen;
  }

  return getFileAssociationDescriptor(node.extension)?.openWith ?? resolveFallbackApp(node);
}

export function resolveEditApp(node?: VirtualNode): AppId | null {
  if (!node || node.kind === "directory") {
    return null;
  }

  if (isNotesNode(node)) {
    return "notes";
  }

  return getFileAssociationDescriptor(node.extension)?.editWith ?? (isTextLikeExtension(node.extension) ? "editor" : null);
}

export function resolveAppIdForNode(node?: VirtualNode): AppId {
  return resolveOpenApp(node);
}

/** All apps that can meaningfully open this file type (used by "Open With" dialog). */
const FAMILY_ALTERNATIVES: Partial<Record<string, AppId[]>> = {
  text: ["notes", "editor", "markdown"],
  code: ["editor"],
  image: ["photos", "paint"],
};

/** Apps that can open a file type, without the visitor's default folded in. */
export function getOpenWithOptionsForExtension(extension: string): AppId[] {
  const assoc = getFileAssociationDescriptor(extension);
  const options: AppId[] = [];
  const add = (id: AppId | undefined | null) => {
    if (id && !options.includes(id)) options.push(id);
  };

  add(assoc?.openWith);
  add(assoc?.editWith);
  for (const alt of FAMILY_ALTERNATIVES[assoc?.family ?? ""] ?? []) add(alt);

  return options;
}

/** Every file type the OS knows, for the Default apps list. */
export function getKnownExtensions(): string[] {
  return Object.keys(fileAssociations);
}

export function getOpenWithOptions(node: VirtualNode): AppId[] {
  if (node.kind === "directory") return [];

  const assoc = getFileAssociationDescriptor(node.extension);
  const seen = new Set<AppId>();
  const options: AppId[] = [];

  const add = (id: AppId | undefined | null) => {
    if (id && !seen.has(id)) { seen.add(id); options.push(id); }
  };

  add(resolveOpenApp(node));
  add(resolveEditApp(node));

  for (const alt of FAMILY_ALTERNATIVES[assoc?.family ?? ""] ?? []) {
    add(alt);
  }

  return options;
}

