    ["AVERAGE(A1:A3)", 2],
    ["MIN(A1:A3)", 1],
    ["MAX(A1:A3,9)", 9],
    ["COUNT(A1:B3)", 3],
    ["COUNTA(A1:B3)", 5],
    ["ABS(-3)", 3],
    ["INT(-1.5)", -2],
    ["SQRT(16)", 4],
    ["ROUND(2.345,2)", 2.35],
    ["ROUND(1234,-2)", 1200],
    ["POWER(2,10)", 1024],
    ["MOD(7,3)", 1],
    ["MOD(-1,3)", 2],
    ["IF(A1=1,\"yes\",\"no\")", "yes"],
    ["IF(A1=2,\"yes\")", false],
    ["IFERROR(1/0,\"oops\")", "oops"],
    ["IFERROR(5,\"oops\")", 5],
    ["AND(TRUE,A1=1)", true],
    ["OR(FALSE,A1=2)", false],
    ["NOT(FALSE)", true],
    ['LEN("hello")', 5],
    ['UPPER("ab")', "AB"],
    ['LOWER("AB")', "ab"],
    ['TRIM("  a   b ")', "a b"],
    ['LEFT("hello",2)', "he"],
    ['RIGHT("hello",2)', "lo"],
    ['RIGHT("hello",0)', ""],
    ['MID("hello",2,3)', "ell"],
    ['CONCAT("a",1,B1:B2)', "a1xy"],
    ['COUNTIF(A1:A3,">1")', 2],
    ['COUNTIF(B1:B2,"x")', 1],
    ['SUMIF(A1:A3,">=2")', 5],
    ['SUMIF(B1:B2,"y",A1:A2)', 2],
  ])("%s", (source, expected) => {
    expect(run(source)).toBe(expected);
  });

  it("knows pi", () => {
    expect(run("PI()")).toBeCloseTo(Math.PI);
  });

  it("evaluates only the chosen IF branch", () => {
    expect(run("IF(TRUE,1,1/0)")).toBe(1);
    expect(run("IF(FALSE,1/0,2)")).toBe(2);
  });
