import { describe, expect, it } from "vitest";
import { DEFAULT_TERMINAL_SCHEME_ID, getTerminalScheme, terminalSchemes } from "@/lib/terminal-schemes";

const COLOR_KEYS = [
  "black", "red", "green", "yellow", "blue", "magenta", "cyan", "white",
