    expect(createTab("a", "pwsh", "/").zoomDelta).toBe(0);
    const zoomed = zoomTab(three(), "b", 1, 14);
    expect(duplicateTab(zoomed, "b", "d").tabs[3].zoomDelta).toBe(0);
