    // Zoomed up by 10 at 14, then the saved size is raised to 30: the tab shows 32 (clamped), and one press down must shrink it.
    const zoomed = { ...three(), tabs: three().tabs.map((tab) => (tab.id === "a" ? { ...tab, zoomDelta: 10 } : tab)) };
