    expect(launchPayloadsMatch({ launchNonce: "a" }, { launchNonce: "b" })).toBe(false);
    expect(launchPayloadsMatch({ profile: "cmd", launchNonce: "a" }, { profile: "cmd", launchNonce: "a" })).toBe(true);
  });
});

describe("legacy system runtime migration", () => {
  beforeEach(() => {
