    expect(useTerminalSettingsStore.getState().schemeId).toBe(DEFAULT_TERMINAL_SETTINGS.schemeId);
  });

  it("zooms the font within bounds", () => {
    const { changeFontSize } = useTerminalSettingsStore.getState();
    changeFontSize(-100);
