});

describe("window store persistence sanitizers", () => {
  it("normalizes persisted windows with missing optional fields", () => {
    expect(
      sanitizePersistedWindows([
        {
          id: "window-1",
          processId: "process-1",
          x: 40,
          y: 50,
          width: 640,
          height: 420,
          zIndex: 7,
          createdAt: 123,
        },
      ])[0],
    ).toEqual(
      expect.objectContaining({
        id: "window-1",
        processId: "process-1",
        title: "Window",
        minimized: false,
        maximized: false,
        focused: false,
        zIndex: 7,
        createdAt: 123,
      }),
    );
  });

  it("drops malformed windows", () => {
    expect(
      sanitizePersistedWindows([
        {
          id: "window-1",
          x: 40,
          y: 50,
          width: 640,
          height: 420,
        },
        null,
        "window-2",
      ]),
    ).toEqual([]);
  });

  it("falls back to safe bounds for non-finite persisted geometry", () => {
    expect(
      sanitizePersistedWindows([
        {
          id: "window-1",
          processId: "process-1",
          x: Number.NaN,
          y: Number.POSITIVE_INFINITY,
          width: "wide",
          height: null,
          zIndex: "top",
        },
      ])[0],
    ).toEqual(
      expect.objectContaining({
        x: 120,
        y: 88,
        width: 720,
        height: 480,
        zIndex: 2,
      }),
    );
  });

  it("falls back to an empty window list for non-array values", () => {
    expect(sanitizePersistedWindows({ windows: [] })).toEqual([]);
  });
});

