  display: grid;
  justify-items: center;
  gap: 10px;
  margin: 0;
  padding: 10px 16px;
  border-radius: 6px;
  background: rgb(0 0 0 / 72%);
  color: #fff;
  font-size: 14px;
}

.doom-app__notice p {
  margin: 0;
}

files.src/styles/explorer-panes.css:
/* The window is the container, so the panes can restack in a narrow one. */
.w11-explorer {
  container: explorer / inline-size;
}

.w11-explorer .explorer-window__layout.has-preview {
  grid-template-columns: auto minmax(0, 1fr) 260px;
}

.explorer-preview {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  border-left: 1px solid var(--w11-explorer-line);
  background: var(--w11-explorer-chrome);
  color: #fff;
  font-size: 13px;
}

.explorer-preview__note {
  margin: auto;
  padding: 16px;
  color: rgba(255, 255, 255, 0.7);
  text-align: center;
}

.explorer-preview__body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 12px;
}

.explorer-preview__body .explorer-preview__note {
  margin: 8px 0 0;
  padding: 0;
}

.explorer-preview__body img,
.explorer-preview__body video {
  max-width: 100%;
  max-height: 100%;
  border-radius: var(--w11-radius-control);
  object-fit: contain;
}

.explorer-preview__body audio {
  width: 100%;
}

.explorer-preview__body pre {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: auto;
  font-family: ui-monospace, Consolas, monospace;
  font-size: 12px;
  line-height: 18px;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.explorer-preview__details {
  display: grid;
  flex: none;
  gap: 4px 8px;
  grid-template-columns: 72px minmax(0, 1fr);
  margin: 0;
  padding: 12px;
  border-top: 1px solid var(--w11-explorer-line);
}

.explorer-preview__details dt {
  color: rgba(255, 255, 255, 0.7);
}

.explorer-preview__details dd {
  margin: 0;
  overflow-wrap: anywhere;
}

/* Too narrow for three columns: the pane goes under the files. */
@container explorer (max-width: 720px) {
  .w11-explorer .explorer-window__layout.has-preview {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) minmax(0, 42%);
  }

  .w11-explorer .explorer-window__layout.has-preview .explorer-window__sidebar {
    display: none;
  }

  .explorer-preview {
    border-top: 1px solid var(--w11-explorer-line);
    border-left: 0;
  }

  .explorer-preview__details {
    padding: 8px 12px;
  }
}

.explorer-tabs {
  display: flex;
  flex: none;
  align-items: flex-end;
  gap: 2px;
  min-width: 0;
  padding: 4px 8px 0;
  background: var(--w11-explorer-chrome);
  color: #fff;
  font-size: 12px;
}

.explorer-tabs__list {
  display: flex;
  min-width: 0;
  gap: 2px;
  overflow-x: auto;
  scrollbar-width: none;
}

.explorer-tabs__tab {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  width: 148px;
  height: 30px;
  border-radius: var(--w11-radius-control) var(--w11-radius-control) 0 0;
}

.explorer-tabs__tab:hover {
  background: rgba(255, 255, 255, 0.05);
}

.explorer-tabs__tab.is-active {
  background: rgba(255, 255, 255, 0.09);
}

.explorer-tabs__tab > button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.explorer-tabs__tab > [role="tab"] {
  overflow: hidden;
  min-width: 0;
  height: 100%;
  flex: 1;
  padding: 0 4px 0 10px;
  font: inherit;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.explorer-tabs__close,
.explorer-tabs__new {
  display: grid;
  width: 24px;
  height: 24px;
  flex: none;
  place-items: center;
  margin-right: 3px;
  border-radius: var(--w11-radius-control);
}

.explorer-tabs__new {
  height: 28px;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.explorer-tabs__close:hover,
.explorer-tabs__new:hover {
  background: rgba(255, 255, 255, 0.1);
}

@media (pointer: coarse) {
  .explorer-tabs__tab {
    width: 132px;
    height: 36px;
  }

  .explorer-tabs__close {
    width: 32px;
    height: 32px;
  }

  .explorer-tabs__new {
    width: 36px;
    height: 36px;
  }
}

files.src/styles/global.css:
:root {
  font-size: 16px;
  font-family: "IBM Plex Sans", sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color: #eff4ff;
  background: #08111d;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  --text-strong: #f6f9ff;
  --text: rgba(232, 240, 255, 0.92);
  --text-muted: rgba(206, 219, 242, 0.72);
  --border: rgba(255, 255, 255, 0.09);
  --border-strong: rgba(255, 255, 255, 0.18);
  --surface-strong: rgba(9, 16, 28, 0.94);
  --shadow-ambient: 0 22px 56px rgba(0, 0, 0, 0.34);
  --shadow-window: 0 24px 72px rgba(0, 0, 0, 0.42);
  --theme-accent: #77c7ff;
  --desktop-wallpaper: linear-gradient(160deg, #071019 0%, #0c1828 100%);
  --desktop-tint: rgba(9, 18, 32, 0.66);
  --desktop-glow: rgba(255, 141, 88, 0.42);
  --shell-surface: rgba(10, 16, 26, 0.82);
  --space-1: 0.35rem;
  --space-2: 0.55rem;
  --space-3: 0.78rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --radius-sm: 0.58rem;
  --radius-md: 0.76rem;
  --radius-lg: 0.94rem;
  --radius-xl: 1.08rem;
  --control-height-compact: 2rem;
  --control-height-regular: 2.3rem;
  --panel-padding: var(--space-4);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  width: 100%;
  min-height: 100%;
}

body {
  overflow: hidden;
}

body.recruiter-scroll {
  overflow: auto;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 3px;
}

@keyframes desktop-icon-onboarding-hint {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.12);
  }
}

/* Icon bounce-launch on double-click activation */
@keyframes icon-launch {
  0%   { transform: scale(1); }
  35%  { transform: scale(1.18) translateY(-6px); }
  65%  { transform: scale(0.93) translateY(0); }
  85%  { transform: scale(1.05) translateY(-2px); }
  100% { transform: scale(1) translateY(0); }
}

.desktop-icon.is-launching .desktop-icon__glyph {
  animation: icon-launch 0.38s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

button,
input,
textarea,
select,
a {
  color: inherit;
  font: inherit;
}

button,
input,
textarea,
select {
  min-width: 0;
  max-width: 100%;
}

button {
  border: 0;
  background: transparent;
}

textarea {
  resize: vertical;
}

a {
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

.os-root {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background: #06101b;
}

.os-root__wallpaper,
.os-root__noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.os-root__wallpaper {
  background: var(--desktop-wallpaper);
}

.os-root__wallpaper::before,
.os-root__wallpaper::after {
  content: "";
  position: absolute;
  inset: 0;
}

.os-root__wallpaper::before {
  background:
    radial-gradient(circle at 12% 18%, var(--desktop-glow), transparent 30%),
    radial-gradient(circle at 84% 22%, rgba(124, 215, 255, 0.18), transparent 25%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent);
  mix-blend-mode: screen;
}

.os-root__wallpaper::after {
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(to bottom, transparent 0%, black 18%, black 74%, transparent 100%);
  opacity: 0.18;
}

.os-root__noise {
  background:
    linear-gradient(var(--desktop-tint), var(--desktop-tint)),
    radial-gradient(circle at 0 0, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px);
  background-size: auto, 8px 8px;
  opacity: 0.8;
}

.os-offline-banner {
  position: absolute;
  top: 0.75rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 50;
  /* Sized by its text, not by the half of the screen left of its 50% offset, so it stays one line on phones. */
  width: max-content;
  max-width: calc(100% - 1.5rem);
  text-align: center;
  /* It sits over the title bars, so it must never take their clicks. */
  pointer-events: none;
  padding: 0.35rem 0.6rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(10, 14, 20, 0.78);
  color: var(--text-muted);
  font-size: 0.78rem;
  backdrop-filter: blur(8px);
}

.os-root.is-animated-wallpaper .os-root__wallpaper {
  background-size: 120% 120%;
  animation: wallpaper-pan 22s ease-in-out infinite alternate;
}

.os-root.is-animated-wallpaper .os-root__wallpaper::before {
  animation: wallpaper-breathe 18s ease-in-out infinite alternate;
}

@keyframes wallpaper-pan {
  from {
    background-position: 0% 0%;
  }

  to {
    background-position: 100% 100%;
  }
}

@keyframes wallpaper-breathe {
  from {
    transform: scale(1);
    opacity: 0.82;
  }

  to {
    transform: scale(1.08);
    opacity: 1;
  }
}

.desktop-surface {
  position: absolute;
  inset: 0 0 84px;
  overflow: hidden;
}

.desktop-surface__grid {
  position: absolute;
  inset: 0;
}

.desktop-surface__cell-preview {
  position: absolute;
  z-index: 1;
  border: 1.5px solid color-mix(in srgb, var(--theme-accent) 58%, rgba(255, 255, 255, 0.16));
  border-radius: 0.9rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent),
    color-mix(in srgb, var(--theme-accent) 14%, rgba(255, 255, 255, 0.02));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.05);
  pointer-events: none;
}

.desktop-surface__overlay {
  position: absolute;
  inset-inline: 0;
  pointer-events: none;
}

.desktop-surface__dropzone {
  position: absolute;
  inset: 1rem 1rem 1rem;
  z-index: 3;
  display: grid;
  gap: 0.35rem;
  align-content: center;
  justify-items: center;
  padding: 1.5rem;
  border: 1.5px dashed color-mix(in srgb, var(--theme-accent) 56%, rgba(255, 255, 255, 0.2));
  border-radius: 1.5rem;
  background:
    linear-gradient(180deg, rgba(6, 11, 18, 0.22), rgba(6, 11, 18, 0.48)),
    color-mix(in srgb, var(--theme-accent) 14%, rgba(255, 255, 255, 0.03));
  color: var(--text-strong);
  text-align: center;
  pointer-events: none;
  backdrop-filter: blur(8px);
}

.desktop-surface__dropzone small {
  max-width: 34rem;
  color: var(--text-muted);
}

.desktop-surface__overlay--top {
  top: 0;
  height: 160px;
  background: linear-gradient(180deg, rgba(8, 13, 21, 0.28), transparent);
}

.desktop-surface__overlay--bottom {
  bottom: 0;
  height: 200px;
  background: linear-gradient(180deg, transparent, rgba(6, 11, 18, 0.32));
}

.desktop-icon {
  position: absolute;
  z-index: 2;
  display: flex;
  width: clamp(72px, calc(var(--desktop-cell-width) - 10px), 92px);
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  padding: 0.7rem 0.45rem;
  border-radius: 0.85rem;
  color: var(--text-strong);
  text-align: center;
  cursor: default;
  user-select: none;
  will-change: transform;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.desktop-icon-button {
  margin: 0;
  border: 0;
  background: transparent;
}

/* Hover + selected styles live in visual-redesign.css (blue tint + ring) */

/* Opacity for the grid cell being dragged; keep pointer-events until a real move so double-click still works. */
.desktop-icon.is-dragging {
  opacity: 0.22;
}

.desktop-icon.is-dragging-sink {
  pointer-events: none;
}

.desktop-icon.desktop-drag-ghost {
  z-index: 4;
  pointer-events: none;
  opacity: 0.96;
  background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 20px 42px rgba(0, 0, 0, 0.28);
}

.desktop-icon__glyph {
  display: grid;
  width: clamp(50px, calc(var(--desktop-cell-width) * 0.72), 58px);
  height: clamp(50px, calc(var(--desktop-cell-width) * 0.72), 58px);
  place-items: center;
  border-radius: 0;
}

.desktop-icon__label {
  max-width: 100%;
  font-size: 0.78rem;
  font-weight: 600;
  line-height: 1.35;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  text-overflow: ellipsis;
  overflow-wrap: break-word;
  word-break: normal;
}

/* ── Ambient desktop widget (wide screens only) ─────────────────── */
.window-manager {
  position: absolute;
  inset: 0 0 84px;
  pointer-events: none;
}

.window-frame__rnd {
  pointer-events: auto !important;
}

/* ── Window snap ghost overlay ──────────────────────────────────── */
.window-snap-ghost {
  position: fixed;
  z-index: 59;
  border: 2px solid color-mix(in srgb, var(--theme-accent) 55%, transparent);
  border-radius: 0.94rem;
  background: color-mix(in srgb, var(--theme-accent) 7%, transparent);
  backdrop-filter: blur(4px);
  pointer-events: none;
  animation: snap-ghost-in 0.1s ease-out both;
}

@keyframes snap-ghost-in {
  from { opacity: 0; scale: 0.98; }
  to   { opacity: 1; scale: 1; }
}

.window-snap-ghost--top {
  inset: 4px 4px 60px 4px;
}

.window-snap-ghost--left {
  inset: 4px 50% 60px 4px;
}

.window-snap-ghost--right {
  inset: 4px 4px 60px 50%;
}

.window-frame__rnd.is-animated {
  transition:
    transform 180ms ease,
    left 180ms ease,
    top 180ms ease,
    width 180ms ease,
    height 180ms ease;
}

.window-frame {
  display: flex;
  height: 100%;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent 24%),
    var(--shell-surface);
  box-shadow: var(--shadow-window);
  backdrop-filter: blur(16px);
}

.window-frame.is-active {
  border-color: color-mix(in srgb, var(--theme-accent) 38%, rgba(255, 255, 255, 0.12));
}

.window-frame__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 0.55rem;
  height: 38px;
  flex-shrink: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0));
  cursor: move;
  touch-action: none;
  position: relative;
}

/* Centred title — sits in the absolute middle regardless of button widths */
.window-frame__title--centered {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  pointer-events: none;
  white-space: nowrap;
}

/* Left spacer mirrors right buttons to keep title truly centred */
.window-frame__actions-spacer {
  width: calc(3 * 13px + 2 * 0.38rem); /* 3 buttons + 2 gaps */
  flex-shrink: 0;
}

.window-frame__title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.8rem;
  font-weight: 600;
  line-height: 1;
}

.window-frame__title strong,
.app-toolbar__title strong,
.section-row strong {
  color: var(--text-strong);
}

.section-title {
  color: var(--text-muted);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.window-frame__title strong,
.window-frame__title small {
  display: block;
}

.window-frame__title small,
.app-toolbar__title small,
.mini-facts dt,
.explorer-item small,
.taskbar__item span,
.taskbar__clock small,
.theme-card__meta small,
.contact-link-card span {
  color: var(--text-muted);
}

.window-frame__title-icon {
  display: grid;
  width: 1.25rem;
  height: 1.25rem;
  place-items: center;
  border-radius: 0.35rem;
  background: none;
  color: color-mix(in srgb, var(--app-accent) 82%, white 18%);
}

.window-frame__title-icon svg {
  width: 14px;
  height: 14px;
}

.window-frame__actions {
  display: inline-flex;
  gap: 0.38rem;
  align-items: center;
}

.window-action-buttons {
  touch-action: auto;
}

/* ── Traffic-light window buttons ────────────────────────── */
.window-frame__actions button {
  position: relative;
  display: grid;
  width: 13px;
  height: 13px;
  place-items: center;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  color: transparent;
  transition:
    filter 160ms ease,
    transform 120ms ease,
    color 120ms ease;
  flex-shrink: 0;
}

/* Expand hit target to 24×24 without changing visual size */
.window-frame__actions button::before {
  content: "";
  position: absolute;
  inset: -6px;
}

.window-frame__actions button.is-close   { background: #ff5f56; }
.window-frame__actions button.is-minimize { background: #ffbd2e; }
.window-frame__actions button.is-maximize { background: #28c940; }

/* Icon hidden by default, visible on header hover */
.window-frame__actions button svg {
  width: 9px;
  height: 9px;
  opacity: 0;
  transition: opacity 100ms ease;
  color: rgba(0, 0, 0, 0.6);
}

.window-frame__header:hover .window-frame__actions button svg,
.window-frame__actions button:focus-visible svg {
  opacity: 1;
}

/* Dim buttons when window not focused */
.window-frame:not(.is-active) .window-frame__actions button {
  filter: saturate(0) brightness(0.55);
}

.icon-button {
  display: grid;
  width: var(--control-height-compact);
  height: var(--control-height-compact);
  place-items: center;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
