  height: var(--control-height-regular);
}

.icon-button--panel {
  border-color: var(--border);
  background: rgba(255, 255, 255, 0.045);
}

.icon-button--danger {
  color: #ffd3d3;
}

.window-frame__body {
  display: flex;
  min-height: 0;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.window-frame__body > * {
