  gap: 0.55rem;
  padding: 0 0 0.1rem;
}

.photo-viewer__thumb {
  width: 96px;
  gap: 0.35rem;
  padding: 0.35rem;
  border-radius: 0.72rem;
}

.photo-viewer__thumb img {
  border-radius: 0.55rem;
}

.photo-viewer__footer > span {
  color: var(--text-muted);
  font-size: 0.76rem;
  white-space: nowrap;
}

.pdf-viewer__stage {
  display: grid;
  min-height: 0;
  min-width: 0;
  flex: 1;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 1rem;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.24);
}

.pdf-viewer__meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.7rem;
  color: var(--text-muted);
  font-size: 0.82rem;
}

.pdf-viewer__page-input {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.55rem;
  border-radius: 0.8rem;
  background: rgba(255, 255, 255, 0.04);
}

.pdf-viewer__page-input input {
  width: 4.5rem;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text-strong);
}

.pdf-viewer__canvas-wrap {
  position: relative;
  display: grid;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  place-items: start center;
  padding: 1rem;
  border-radius: 1.1rem;
  background: rgba(255, 255, 255, 0.03);
}

.pdf-viewer__canvas-wrap canvas {
  border-radius: 0.8rem;
  background: white;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.28);
}

.pdf-viewer__loading {
  position: absolute;
  top: 1.25rem;
  right: 1.25rem;
  padding: 0.55rem 0.75rem;
  border-radius: 999px;
  background: rgba(8, 14, 22, 0.78);
  color: var(--text-muted);
  font-size: 0.78rem;
}

.browser-app {
  display: flex;
  height: 100%;
  flex-direction: column;
  overflow: hidden;
}

.browser-app__toolbar {
  gap: 0.45rem;
}

.browser-app__address-form {
  display: flex;
  min-width: 0;
  flex: 1;
}

.browser-app__address {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  min-height: var(--control-height-compact);
}

.browser-app__mode-cluster {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.browser-app__loading-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  min-height: 1.6rem;
  padding: 0.18rem 0.46rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  font-size: 0.72rem;
}

.browser-app__loading-chip svg {
  animation: browser-app-spin 0.9s linear infinite;
}

.browser-app__proxy-select-shell {
  display: inline-flex;
  align-items: center;
  min-width: 0;
}

.browser-app__proxy-select {
  min-height: 1.6rem;
  padding: 0.18rem 1.65rem 0.18rem 0.56rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background:
    linear-gradient(45deg, transparent 50%, var(--text-muted) 50%),
    linear-gradient(135deg, var(--text-muted) 50%, transparent 50%),
    rgba(255, 255, 255, 0.05);
  background-position:
    calc(100% - 15px) calc(50% - 1px),
    calc(100% - 10px) calc(50% - 1px),
    0 0;
  background-size:
    5px 5px,
    5px 5px,
    100% 100%;
  background-repeat: no-repeat;
  color: var(--text-strong);
  font-size: 0.74rem;
  appearance: none;
}

.browser-app__proxy-select:focus {
  outline: none;
  border-color: color-mix(in srgb, var(--theme-accent) 45%, var(--border));
}

.browser-app__content {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
}

.browser-app__sidebar {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  padding: 0.24rem 0.38rem;
  border-right: none;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.015);
}

.browser-app__sidebar-label {
  flex: 0 0 auto;
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.browser-app__bookmark-list {
  display: flex;
  min-width: 0;
  flex: 1;
  gap: 0.22rem;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.05rem;
}

.browser-app__bookmark {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  flex: 0 0 auto;
  min-height: 1.42rem;
  padding: 0.16rem 0.38rem;
  border: 1px solid transparent;
  border-radius: 0.42rem;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.72rem;
  line-height: 1;
  text-align: left;
}

.browser-app__bookmark.is-active {
  border-color: color-mix(in srgb, var(--theme-accent) 26%, rgba(255, 255, 255, 0.08));
  background: color-mix(in srgb, var(--theme-accent) 8%, transparent);
  color: var(--text-strong);
}

.browser-app__viewport {
  display: flex;
  min-width: 0;
  flex-direction: column;
  min-height: 0;
  flex: 1;
  overflow: hidden;
  padding: 0.35rem;
  background: rgba(0, 0, 0, 0.16);
}

.browser-app__frame-shell {
  position: relative;
  min-width: 0;
  min-height: 0;
  flex: 1;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 0.62rem;
  background: #ffffff;
}

.browser-app__loading-bar {
  position: absolute;
  inset: 0 0 auto;
  z-index: 2;
  height: 3px;
  overflow: hidden;
  background: rgba(17, 24, 39, 0.08);
}

.browser-app__loading-bar span {
  display: block;
  width: 40%;
  height: 100%;
  border-radius: 999px;
  background: var(--theme-accent);
  animation: browser-app-loading-bar 1.1s ease-in-out infinite;
}

.browser-app__frame-shell iframe {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #ffffff;
}

.browser-app__fallback {
  border: 1px solid var(--border);
  border-radius: 0.72rem;
  background: rgba(255, 255, 255, 0.04);
}

.browser-app__fallback {
  display: grid;
  min-width: 0;
  align-content: start;
  justify-items: start;
  gap: 0.6rem;
  padding: 0.72rem;
}

.browser-app__fallback-icon {
  display: grid;
  width: 2.65rem;
  height: 2.65rem;
  place-items: center;
  border-radius: 0.64rem;
  background: color-mix(in srgb, var(--theme-accent) 18%, rgba(255, 255, 255, 0.06));
  color: color-mix(in srgb, var(--theme-accent) 82%, white 18%);
}

.browser-app__fallback-copy {
  display: grid;
  gap: 0.3rem;
}

.browser-app__fallback-copy small {
  color: var(--text-muted);
}

.browser-app__fallback-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.browser-app__fallback code {
  display: block;
  max-width: 100%;
  overflow: hidden;
  padding: 0.55rem 0.68rem;
  border-radius: 0.68rem;
  background: rgba(0, 0, 0, 0.22);
  color: var(--text-muted);
  font-family: "IBM Plex Mono", monospace;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@keyframes browser-app-loading-bar {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(260%);
  }
}

@keyframes browser-app-spin {
  to {
    transform: rotate(360deg);
  }
}

.paint-app {
  overflow: hidden;
}

.paint-app__content,
.embedded-game__content,
.v86-app__content {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: 0.45rem;
  padding: 0.5rem;
}

.v86-app__content {
  gap: 0;
  padding: 0;
}

.music-player__content {
  min-width: 0;
  min-height: 0;
}

.paint-app__toolbar {
  gap: 0.6rem;
}

.paint-app__toolbar-group {
  gap: 0.45rem;
  flex-wrap: wrap;
}

.paint-app .pill-button,
.paint-app .ghost-button,
.paint-app .icon-button {
  border-radius: 0.65rem;
}

.paint-app .icon-button {
  width: 2.05rem;
  height: 2.05rem;
}

.paint-app .ghost-button,
.paint-app .pill-button {
  min-height: 2.05rem;
  padding: 0.42rem 0.62rem;
  font-size: 0.78rem;
}

.paint-app__stage {
  display: grid;
  flex: 1;
  min-height: 0;
  min-width: 0;
  place-items: stretch;
  overflow: hidden;
  padding: 0.5rem;
  border-radius: 0.95rem;
  background: rgba(0, 0, 0, 0.28);
}

.paint-app__canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: white;
  border-radius: 0.85rem;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.35);
  touch-action: none;
  cursor: crosshair;
}

.paint-app__swatches {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.paint-app__swatch {
  width: 1.6rem;
  height: 1.6rem;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
}

.paint-app__swatch.is-active {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--theme-accent) 42%, rgba(255, 255, 255, 0.16));
}

.paint-app__size {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  min-height: var(--control-height-compact);
  padding: 0.3rem 0.52rem;
  border-radius: 0.72rem;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
  font-size: 0.76rem;
}

.paint-app__size input {
  width: 84px;
}

.paint-app__fallback {
  display: grid;
  gap: 0.45rem;
  padding: 0.7rem 0.82rem;
  border-radius: 0.8rem;
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
}

.paint-app__footer {
  justify-content: space-between;
}

.music-player__layout,
.tetris-game__layout {
  display: grid;
  gap: 1rem;
}

.music-player__hero,
.music-player__playlist,
.tetris-game__aside,
.games-hub__card {
  display: grid;
  gap: 0.85rem;
}

.music-player__content {
  display: grid;
  grid-template-columns: minmax(250px, 300px) minmax(0, 1fr);
}

.music-player__sidebar {
  min-width: 0;
  min-height: 0;
  gap: 0.72rem;
  padding: 0.78rem;
  border-right: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.03);
}

.music-player__main {
  display: grid;
  min-width: 0;
  min-height: 0;
  align-content: start;
  gap: 0.95rem;
  padding: 0.9rem;
}

.music-player__hero {
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
}

.music-player__cover {
  display: grid;
  width: 4.1rem;
  height: 4.1rem;
  place-items: center;
  overflow: hidden;
  border-radius: 0.95rem;
  background: color-mix(in srgb, var(--theme-accent) 18%, rgba(255, 255, 255, 0.08));
  color: color-mix(in srgb, var(--theme-accent) 72%, white 28%);
}

.music-player__cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.music-player__meta {
  display: grid;
  min-width: 0;
  gap: 0.22rem;
}

.music-player__meta p:last-child,
.music-player__track-copy small,
.arcade-game__footer small,
.tetris-game__aside small {
  color: var(--text-muted);
}

.music-player__controls,
.music-player__timeline {
  display: grid;
  gap: 0.68rem;
}

.music-player__transport,
.music-player__volume {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.music-player__play {
  display: grid;
  width: 2.6rem;
  height: 2.6rem;
  place-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-accent) 26%, rgba(255, 255, 255, 0.08));
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.22);
}

.music-player__progress {
  position: relative;
  height: 0.4rem;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
}

.music-player__progress span {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--theme-accent), rgba(255, 255, 255, 0.85));
}

.music-player__time {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.78rem;
}

.music-player__volume input {
  width: min(170px, 30vw);
}

.music-player__seek {
  position: relative;
  display: grid;
}

.music-player__seek input {
  position: absolute;
  inset: -0.45rem 0;
  width: 100%;
  opacity: 0;
  cursor: pointer;
}

.music-player__empty {
  max-width: 28rem;
}

.music-player__playlist-list {
  display: grid;
  gap: 0.5rem;
  min-height: 0;
}

.music-player__playlist {
  min-width: 0;
}

.music-player__track {
  display: grid;
  grid-template-columns: auto 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.65rem;
  padding: 0.64rem 0.7rem;
  border: 1px solid transparent;
  border-radius: 0.8rem;
  background: rgba(255, 255, 255, 0.03);
  text-align: left;
}

.music-player__track-art {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  overflow: hidden;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.06);
}

.music-player__track-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.music-player__track.is-active {
  border-color: color-mix(in srgb, var(--theme-accent) 38%, rgba(255, 255, 255, 0.12));
  background: color-mix(in srgb, var(--theme-accent) 12%, rgba(255, 255, 255, 0.03));
}

.music-player__track-index,
.music-player__track-status,
.arcade-game__header-actions span {
  color: var(--text-muted);
  font-size: 0.78rem;
}

.music-player__track-copy {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}

.music-player__track-copy strong,
.music-player__track-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.music-player__footer {
  gap: var(--space-3);
  justify-content: space-between;
}

.games-hub__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.85rem;
}

.games-hub__card {
  display: grid;
  min-height: 0;
  min-width: 0;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  align-content: start;
  padding: 0.78rem;
  border: 1px solid var(--border);
  border-radius: 0.85rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent),
    rgba(255, 255, 255, 0.03);
  text-align: left;
}

.games-hub__card-icon {
  display: grid;
  width: 2.5rem;
  height: 2.5rem;
  place-items: center;
  border-radius: 0;
  color: color-mix(in srgb, var(--app-accent) 80%, white 20%);
}

.games-hub__card-copy {
  display: grid;
  min-width: 0;
  gap: 0.25rem;
}

.games-hub__card-copy strong,
.games-hub__card-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
}

.games-hub__card-copy small {
  color: var(--text-muted);
}

.games-hub__toolbar,
.games-hub__statusbar {
  gap: 0.7rem;
}

.games-hub__content {
  gap: 0.9rem;
}

.games-hub__sections {
  display: grid;
  gap: 1rem;
}

.games-hub__section {
  display: grid;
  gap: 0.8rem;
}

.games-hub__section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.8rem;
}

.games-hub__section-copy {
  display: grid;
  gap: 0.2rem;
}

.games-hub__section-copy small {
  color: var(--text-muted);
}

.games-hub__intro {
  display: grid;
  gap: 0.35rem;
}

.games-hub__chip {
  padding: 0.35rem 0.58rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  font-size: 0.76rem;
  font-weight: 600;
}

.v86-app {
  overflow: hidden;
}

.v86-app__stage {
  position: relative;
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
  background: #000;
}

/* Sized by the guest. The fit in v86-app.tsx scales it into the stage. */
.v86-app__screen {
  position: absolute;
  top: 50%;
  left: 50%;
  width: max-content;
  transform: translate(-50%, -50%);
  color: #fff;
}

/* The guest's text mode: a grid, so it stays 80 by 25 however little is on it. */
.v86-app__screen > div {
  min-width: 80ch;
  min-height: 400px;
  font: 16px/16px Consolas, "Cascadia Mono", "IBM Plex Mono", monospace;
  white-space: pre;
}

.v86-app__screen canvas {
  display: block;
}

.v86-app__shared {
  flex: none;
  max-height: 40%;
  overflow-y: auto;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding: 8px 12px;
  font-size: 13px;
}

.v86-app__shared-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.v86-app__shared-head span {
  flex: 1;
  min-width: 0;
}

.v86-app__shared ul {
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.v86-app__shared li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 32px;
}

.v86-app__shared li span {
  overflow: hidden;
  font-family: "IBM Plex Mono", monospace;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v86-app__shared p {
  margin: 8px 0 0;
  color: var(--text-muted);
}

.v86-app__empty,
.v86-app__error {
  display: grid;
  gap: 0.55rem;
  padding: 1rem;
  border-radius: 0.95rem;
  background: rgba(255, 255, 255, 0.04);
}

.v86-app__error {
  color: #ffd1d1;
}

.embedded-game {
  overflow: hidden;
}

.embedded-game__status-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  border-radius: 0.9rem;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
  font-size: 0.82rem;
}

.embedded-game__viewport {
  position: relative;
  display: grid;
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
  border-radius: 0.85rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),
    rgba(5, 8, 12, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.embedded-game__frame {
  display: block;
  min-width: 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: #05080c;
}

.embedded-game__loading,
.embedded-game__error {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: grid;
  gap: 0.45rem;
  place-content: center;
  padding: 1.5rem;
  text-align: center;
}

.embedded-game__loading {
  background: rgba(5, 8, 12, 0.78);
}

.embedded-game__error {
  background: rgba(11, 17, 27, 0.9);
  color: #ffd6d6;
}

.embedded-game__viewport.is-loaded .embedded-game__loading {
  display: none;
}

.embedded-game__footer {
  gap: 0.65rem;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}

.embedded-game__footer small {
  color: var(--text-muted);
}

.arcade-game-shell__toolbar,
.arcade-game-shell__footer {
  gap: 0.7rem;
}

.arcade-game-shell__actions {
  justify-content: flex-end;
}

.arcade-game-shell__actions .button {
  flex: 0 0 auto;
}

.arcade-game-shell__content {
  display: flex;
  min-width: 0;
  min-height: 0;
}

.arcade-game-shell__interactive {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  padding: 0.9rem;
  outline: none;
}

.arcade-game-shell__interactive:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--theme-accent) 38%, rgba(255, 255, 255, 0.12));
}

.arcade-game-shell__viewport {
  display: grid;
  flex: 1;
  min-width: 0;
  min-height: 0;
  place-items: center;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),
    rgba(7, 13, 21, 0.76);
}

.arcade-game-shell__footer {
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}

.arcade-game-shell__footer small {
  color: var(--text-muted);
}

.snake-game__board,
.tetris-game__board {
  display: grid;
  width: max-content;
  height: max-content;
  gap: 0.24rem;
  padding: 0.65rem;
  border-radius: 1rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),
    rgba(7, 13, 21, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.22);
}

.snake-game__cell,
.tetris-game__cell {
  aspect-ratio: 1;
  border-radius: 0.32rem;
  background: rgba(255, 255, 255, 0.04);
}

.snake-game__cell.is-snake {
  background: color-mix(in srgb, var(--theme-accent) 38%, rgba(118, 255, 166, 0.28));
}

.snake-game__cell.is-head {
  background: color-mix(in srgb, var(--theme-accent) 22%, rgba(255, 255, 255, 0.82));
}

.snake-game__cell.is-food {
  background: #ff8a5c;
}

.tetris-game__layout {
  display: grid;
  min-width: 0;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr) 180px;
  align-items: stretch;
}

.tetris-game__cell.is-filled {
  background: var(--tetris-cell);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
}

.tetris-game__aside {
  display: grid;
  align-content: start;
  gap: 0.35rem;
  padding: 0.9rem 1rem;
  border-radius: 1rem;
}

.dino-game__track {
  position: relative;
  min-height: 0;
  overflow: hidden;
  border-radius: 1rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent),
    linear-gradient(180deg, rgba(8, 14, 22, 0.92), rgba(8, 14, 22, 0.76));
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.dino-game__runner,
.dino-game__obstacle,
.dino-game__ground {
  position: absolute;
}

.dino-game__runner {
  left: 64px;
  bottom: 28px;
  width: 42px;
  height: 42px;
  border-radius: 0.6rem;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(202, 216, 239, 0.9));
  box-shadow: 0 10px 18px rgba(0, 0, 0, 0.16);
}

.dino-game__obstacle {
  bottom: 28px;
  border-radius: 0.4rem 0.4rem 0 0;
  background: linear-gradient(180deg, #ffd27d, #ff8a5c);
}

.dino-game__ground {
  right: 0;
  bottom: 18px;
  left: 0;
  height: 2px;
  background: rgba(255, 255, 255, 0.16);
}

.theme-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.theme-card {
  display: grid;
  gap: 0.8rem;
  padding: 0.75rem;
  border-radius: 1rem;
  text-align: left;
}

.theme-card.is-active {
  border-color: color-mix(in srgb, var(--theme-accent) 46%, rgba(255, 255, 255, 0.16));
}

.theme-card__preview {
  display: block;
  aspect-ratio: 16 / 10;
  border-radius: 0.9rem;
}

.theme-card__meta {
  display: grid;
}

.taskbar {
  position: absolute;
  right: 12px;
  bottom: 12px;
  left: 12px;
  z-index: 60;
  display: grid;
  grid-template-columns: auto minmax(140px, 220px) minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.45rem;
  padding: 0.35rem 0.42rem;
  border-radius: 0.72rem;
}

.taskbar__start,
.taskbar__search-field,
.taskbar__item,
.taskbar__clock,
.taskbar__desktop {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 30px;
  padding: 0.24rem 0.62rem;
  border-radius: var(--radius-sm);
}

.taskbar__start.is-active,
.taskbar__search-field.is-active,
.taskbar__item.is-active,
.taskbar__clock.is-active {
  background: color-mix(in srgb, var(--theme-accent) 16%, rgba(255, 255, 255, 0.06));
  border-color: color-mix(in srgb, var(--theme-accent) 32%, rgba(255, 255, 255, 0.14));
}

.taskbar__search-field {
  margin: 0;
  min-width: min(190px, 28vw);
  max-width: min(280px, 34vw);
  flex: 1 1 200px;
  cursor: text;
  min-height: 30px;
  padding-block: 0.18rem;
  color: var(--text-muted);
}

.taskbar__search-field .search-input__field {
  min-width: 0;
  flex: 1;
}

.taskbar__search-field .search-input__field::placeholder {
  color: var(--text-muted);
}

.taskbar__windows {
  min-width: 0;
  overflow: hidden;
}

.taskbar__window-strip {
  display: flex;
  min-width: 0;
  gap: 0.55rem;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}

.taskbar__window-strip::-webkit-scrollbar {
  display: none;
}

.taskbar__item {
  position: relative;
  display: inline-flex;
  max-width: min(168px, 26vw);
  flex: 0 1 auto;
  align-items: center;
  overflow: hidden;
  padding-bottom: 0.54rem;
}

.taskbar__item > svg {
  flex-shrink: 0;
}

.taskbar__item-copy {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.taskbar__item-indicator {
  position: absolute;
  right: 0.62rem;
  bottom: 0.16rem;
  left: 0.62rem;
  height: 2px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-accent) 74%, rgba(255, 255, 255, 0.22));
  opacity: 0.22;
  transform: scaleX(0.38);
  transform-origin: center;
  transition:
    opacity 160ms ease,
    transform 160ms ease;
}

.taskbar__item.is-active .taskbar__item-indicator {
  opacity: 1;
  transform: scaleX(1);
}

.taskbar__item.is-minimized .taskbar__item-indicator {
  opacity: 0.42;
  transform: scaleX(0.62);
}

/* Pinned but no window open — icon-only, dimmed */
.taskbar__item--pinned-closed {
  opacity: 0.52;
  padding-inline: 0.52rem;
}

.taskbar__item--pinned-closed:hover,
.taskbar__item--pinned-closed:focus-visible {
  opacity: 1;
}

/* ── Toast notifications ───────────────────────────────────────── */
.toast-container {
  position: fixed;
  right: 20px;
  bottom: 80px;
  z-index: 300;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.5rem;
  pointer-events: none;
}

.toast {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  max-width: 320px;
  padding: 0.6rem 0.55rem 0.6rem 0.8rem;
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  background: rgba(12, 20, 34, 0.92);
  backdrop-filter: blur(28px) saturate(1.5);
  box-shadow:
    0 16px 48px rgba(0, 0, 0, 0.45),
    0 1px 0 rgba(255, 255, 255, 0.07) inset;
  font-size: 0.8rem;
  color: var(--text);
  pointer-events: auto;
}

.toast--success {
  color: #7defa1;
  border-color: rgba(125, 239, 161, 0.25);
  background: color-mix(in srgb, rgba(125, 239, 161, 0.1) 100%, rgba(12, 20, 34, 0.92));
}

.toast--error {
  color: #ff8a8a;
  border-color: rgba(255, 138, 138, 0.25);
  background: color-mix(in srgb, rgba(255, 138, 138, 0.1) 100%, rgba(12, 20, 34, 0.92));
}

.toast__icon {
  flex-shrink: 0;
}

.toast__message {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: inherit;
}

.toast__dismiss {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  padding: 0.2rem;
  border: none;
  border-radius: 0.3rem;
  background: none;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0.7;
}

.toast__dismiss:hover {
  background: rgba(255, 255, 255, 0.09);
  color: var(--text);
  opacity: 1;
}

/* ── Keyboard shortcut cheatsheet ───────────────────────────────── */
.cheatsheet-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
}

.cheatsheet {
  width: min(680px, calc(100vw - 2rem));
  max-height: calc(100vh - 4rem);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-strong);
  border-radius: 1.2rem;
  background: var(--surface-strong);
  backdrop-filter: blur(24px);
  box-shadow: var(--shadow-ambient), 0 0 0 1px rgba(255, 255, 255, 0.04) inset;
  overflow: hidden;
}

.cheatsheet__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.1rem 0.75rem;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.cheatsheet__title {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-strong);
}

.cheatsheet__close {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.32rem;
  border: none;
  border-radius: 0.44rem;
  background: none;
  color: var(--text-muted);
  cursor: pointer;
  transition: background 100ms ease, color 100ms ease;
}

.cheatsheet__close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
}

.cheatsheet__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 0;
  overflow-y: auto;
  padding: 0.75rem 1rem;
  gap: 0.5rem 1.5rem;
}

.cheatsheet__group {
  padding: 0.5rem 0;
}

.cheatsheet__group-title {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 0.5rem;
}

.cheatsheet__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.cheatsheet__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.22rem 0;
}

.cheatsheet__item-label {
  font-size: 0.82rem;
  color: var(--text);
  flex: 1;
  min-width: 0;
}

.cheatsheet__item-keys {
  display: flex;
  align-items: center;
  gap: 0.2rem;
  flex-shrink: 0;
}

.cheatsheet__item-keys > span {
  display: flex;
  align-items: center;
  gap: 0.2rem;
}

.cheatsheet__plus {
  font-size: 0.72rem;
  color: var(--text-muted);
}

.cheatsheet__kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.6rem;
  padding: 0.16rem 0.42rem;
  border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 0.34rem;
  background: rgba(255, 255, 255, 0.06);
  font-family: inherit;
  font-size: 0.72rem;
  color: var(--text-strong);
  white-space: nowrap;
}

.cheatsheet__footer {
  flex-shrink: 0;
  padding: 0.6rem 1.1rem;
  border-top: 1px solid var(--border);
  font-size: 0.76rem;
  color: var(--text-muted);
  text-align: center;
}

/* ── Calculator app ─────────────────────────────────────────────── */
.calculator {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: transparent;
  user-select: none;
  font-feature-settings: "tnum";
}

.calculator__display {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  flex: 0 0 auto;
  padding: 1rem 1.1rem 0.75rem;
  min-height: 110px;
  background: rgba(0, 0, 0, 0.18);
  border-bottom: 1px solid var(--border);
}

.calculator__history {
  font-size: 0.78rem;
  color: var(--text-muted);
  min-height: 1.2em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.calculator__value {
  font-size: 2.6rem;
  font-weight: 300;
  color: var(--text-strong);
  line-height: 1.1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  letter-spacing: -0.5px;
}

.calculator__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  flex: 1 1 auto;
  background: var(--border);
  overflow: hidden;
}

.calculator__btn {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.03);
  border: none;
  color: var(--text);
  font-size: 1.3rem;
  font-weight: 400;
  cursor: pointer;
  transition: background 80ms ease;
  min-height: 64px;
}

.calculator__btn:hover,
.calculator__btn:focus-visible {
  background: rgba(255, 255, 255, 0.09);
}

.calculator__btn:active {
  background: rgba(255, 255, 255, 0.15);
}

.calculator__btn.is-secondary {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-muted);
  font-size: 1rem;
}

.calculator__btn.is-secondary:hover {
  background: rgba(255, 255, 255, 0.12);
  color: var(--text);
}

.calculator__btn.is-operator {
  background: rgba(255, 255, 255, 0.05);
  color: var(--theme-accent, #a8ff80);
  font-size: 1.4rem;
}

.calculator__btn.is-operator:hover {
  background: rgba(255, 255, 255, 0.11);
}

.calculator__btn.is-equals {
  background: color-mix(in srgb, var(--theme-accent, #a8ff80) 28%, transparent);
  color: var(--theme-accent, #a8ff80);
  font-size: 1.4rem;
}

.calculator__btn.is-equals:hover {
  background: color-mix(in srgb, var(--theme-accent, #a8ff80) 40%, transparent);
}

.calculator__btn.is-wide {
  grid-column: span 2;
  justify-content: flex-start;
  padding-left: 1.4rem;
}

/* ── Open With dialog ───────────────────────────────────────────── */
.open-with-overlay {
  position: fixed;
  inset: 0;
  z-index: 400;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.44);
  backdrop-filter: blur(3px);
}

.open-with-dialog {
  min-width: 280px;
  max-width: 360px;
  width: 100%;
  padding: 1.1rem 1rem 0.9rem;
  border: 1px solid var(--border-strong);
  border-radius: 1.1rem;
  background: var(--surface-strong);
  backdrop-filter: blur(22px);
  box-shadow: var(--shadow-ambient), 0 0 0 1px rgba(255, 255, 255, 0.04) inset;
}

.open-with-dialog__header {
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0.5rem;
}

.open-with-dialog__title {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-strong);
}

.open-with-dialog__subtitle {
  font-size: 0.74rem;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.open-with-dialog__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.18rem;
}

.open-with-dialog__item {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  width: 100%;
  padding: 0.5rem 0.6rem;
  border: none;
  border-radius: 0.58rem;
  background: none;
  color: var(--text);
  font-size: 0.84rem;
  cursor: pointer;
  text-align: left;
  transition: background 120ms ease;
}

.open-with-dialog__item:hover,
.open-with-dialog__item:focus-visible {
  background: rgba(255, 255, 255, 0.07);
}

.open-with-dialog__item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 0.44rem;
  background: rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.open-with-dialog__item-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.open-with-dialog__footer {
  display: flex;
  justify-content: flex-end;
  padding-top: 0.75rem;
  margin-top: 0.25rem;
  border-top: 1px solid var(--border);
}

.open-with-dialog__cancel {
  padding: 0.36rem 0.9rem;
  border: 1px solid var(--border-strong);
  border-radius: 0.44rem;
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-muted);
  font-size: 0.8rem;
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease;
}

.open-with-dialog__cancel:hover {
  background: rgba(255, 255, 255, 0.11);
  color: var(--text);
}

/* ── Taskbar jump list ──────────────────────────────────────────── */
.taskbar__jump-list {
  position: fixed;
  z-index: 310;
  min-width: 200px;
  max-width: 240px;
  padding: 0.38rem 0.38rem;
  border: 1px solid var(--border-strong);
  border-radius: 0.82rem;
  background: var(--surface-strong);
  backdrop-filter: blur(20px);
  box-shadow: var(--shadow-ambient), 0 0 0 1px rgba(255, 255, 255, 0.04) inset;
}

.taskbar__jump-list-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.32rem 0.52rem 0.42rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0.2rem;
}

.taskbar__jump-list-icon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.taskbar__jump-list-title {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-strong);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.taskbar__jump-list-section {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 0.18rem 0;
}

.taskbar__jump-list-divider {
  height: 1px;
  background: var(--border);
  margin: 0.2rem 0.38rem;
}

.taskbar__jump-list-item {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 0.34rem 0.58rem;
  border: none;
  border-radius: 0.46rem;
  background: none;
  color: var(--text);
  font-size: 0.8rem;
  text-align: left;
  cursor: pointer;
  transition: background 100ms ease;
}

.taskbar__jump-list-item:hover,
.taskbar__jump-list-item:focus-visible {
  background: rgba(255, 255, 255, 0.08);
}

.taskbar__jump-list-item.is-danger {
  color: #ff8a8a;
}

.taskbar__jump-list-item.is-danger:hover,
.taskbar__jump-list-item.is-danger:focus-visible {
  background: rgba(255, 138, 138, 0.1);
}

/* ── Taskbar window preview ─────────────────────────────────────── */
.taskbar__preview {
  position: fixed;
  min-width: 180px;
  padding: 0.75rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: 0.9rem;
  background: var(--surface-strong);
  box-shadow: var(--shadow-window);
  pointer-events: none;
  z-index: 82;
}

.taskbar__preview strong,
.taskbar__preview small {
  display: block;
}

.taskbar__preview-frame {
  display: grid;
  aspect-ratio: 16 / 10;
  margin-bottom: 0.75rem;
  overflow: hidden;
  border-radius: 0.85rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),
    rgba(6, 11, 18, 0.74);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.taskbar__preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.taskbar__preview-fallback {
  display: grid;
  place-items: center;
  gap: 0.6rem;
  padding: 1rem;
  text-align: center;
}

.taskbar__preview-fallback-icon {
  display: grid;
  width: 3.2rem;
  height: 3.2rem;
  place-items: center;
  border-radius: 0;
  color: color-mix(in srgb, var(--app-accent) 82%, white 18%);
}

.taskbar__preview small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.taskbar__preview-status {
  display: inline-flex;
  width: fit-content;
  margin-top: 0.55rem;
  padding: 0.25rem 0.5rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  font-size: 0.72rem;
  text-transform: capitalize;
}

.taskbar__preview-status.is-active {
  color: color-mix(in srgb, var(--theme-accent) 72%, white 28%);
}

.taskbar__tray {
  justify-content: flex-end;
}

.taskbar__clock {
  flex-direction: column;
  align-items: flex-end;
  gap: 0.05rem;
}

.taskbar__clock strong {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.78rem;
}

.taskbar__clock small {
  font-size: 0.65rem;
}

.context-menu {
  position: absolute;
  z-index: 70;
}

.shell-search-results {
  display: flex;
  min-height: 0;
  flex: 1 1 0%;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0 1rem 0.75rem;
  overflow: hidden;
}

.shell-search-results__hint {
  flex-shrink: 0;
