.solitaire .arcade-game-shell__content {
  min-height: 0;
  container-type: size;
}

.solitaire__table {
  --gap: 8px;
  --card-w: min((100cqw - 24px - 6 * var(--gap)) / 7, (100cqh - 24px - var(--gap)) / 4.6);
  --card-h: calc(var(--card-w) * 1.4);
  --step: calc(var(--card-h) * 0.26);
  --room: calc(100cqh - 24px - var(--gap) - var(--card-h) - var(--card-h));

  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  flex-direction: column;
  align-items: center;
  gap: var(--gap);
  padding: 12px;
  background: radial-gradient(circle at 50% 30%, #2f6b53, #173a2d 80%);
  font-family: var(--w11-font);
  user-select: none;
}

.solitaire__top,
.solitaire__columns {
  display: grid;
  grid-template-columns: repeat(7, var(--card-w));
  gap: var(--gap);
}

.solitaire__columns {
  min-height: 0;
  flex: 1;
}

.solitaire__column {
  position: relative;
  min-height: var(--card-h);
}

.solitaire__slot,
.solitaire__card {
  width: var(--card-w);
  height: var(--card-h);
  padding: 0;
  border-radius: calc(var(--card-w) * 0.08);
}

.solitaire__slot {
  display: grid;
  place-items: center;
  border: 1px dashed rgba(255, 255, 255, 0.28);
  background: rgba(0, 0, 0, 0.14);
  color: rgba(255, 255, 255, 0.7);
  cursor: pointer;
}

span.solitaire__slot {
  cursor: default;
}

.solitaire__suit {
  color: rgba(255, 255, 255, 0.3);
  font-size: calc(var(--card-w) * 0.46);
}

.solitaire__card {
  display: block;
  overflow: hidden;
  border: 1px solid rgba(0, 0, 0, 0.3);
  background: #fbfaf6;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
  cursor: pointer;
  touch-action: none;
}

.solitaire__column .solitaire__card {
  position: absolute;
  top: min(calc(var(--step) * var(--index, 0)), calc(var(--room) * var(--index, 0) / var(--count, 1)));
  left: 0;
}

.solitaire__back {
  border: 1px solid rgba(0, 0, 0, 0.35);
  background: repeating-linear-gradient(45deg, #2563eb 0 4px, #1e40af 4px 8px);
  box-shadow: inset 0 0 0 3px #fff, 0 1px 2px rgba(0, 0, 0, 0.4);
  cursor: pointer;
}

span.solitaire__back {
  cursor: default;
}

.solitaire__card.is-picked {
  outline: 3px solid #ffd65a;
  outline-offset: -1px;
}

.solitaire__card.is-dragged {
  opacity: 0.25;
}

.solitaire :is(button):focus-visible {
  z-index: 5;
  outline: 3px solid #fff;
  outline-offset: -1px;
}

.solitaire__face {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  color: #1c2330;
}

.solitaire__face.is-red {
  color: #c62828;
}

.solitaire__corner {
  position: absolute;
  top: 2%;
  left: 7%;
  display: flex;
  gap: 1px;
  font-size: calc(var(--card-w) * 0.24);
  font-weight: 700;
  line-height: 1.1;
}

.solitaire__pip {
  position: absolute;
  right: 6%;
  bottom: 2%;
  font-size: calc(var(--card-w) * 0.52);
  line-height: 1;
}

.solitaire__tools {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 4px;
}

.solitaire__tools button {
  display: grid;
  width: min(32px, 46%);
  aspect-ratio: 1;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.26);
  color: #fff;
  cursor: pointer;
}

.solitaire__tools button:disabled {
  opacity: 0.4;
  cursor: default;
}

.solitaire__ghost {
  position: absolute;
  z-index: 200;
  width: var(--card-w);
  margin: calc(var(--card-h) * -0.2) 0 0 calc(var(--card-w) * -0.5);
  pointer-events: none;
}

.solitaire__ghost .solitaire__card {
  position: absolute;
  top: calc(var(--step) * var(--index, 0));
  left: 0;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.45);
}

.solitaire__won {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background: #0f2c20;
  white-space: nowrap;
}

files.src/styles/spreadsheet.css:
.sheet {
  display: flex;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  background: #202124;
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 13px;
}

.sheet__toolbar {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
  padding: 4px 8px;
}

.sheet__toolbar button {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.sheet__toolbar button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.1);
}

.sheet__toolbar button:disabled {
  opacity: 0.4;
  cursor: default;
}

.sheet__toolbar button.is-on {
  background: rgba(70, 211, 154, 0.22);
  color: #8ff0c6;
}

.sheet__toolbar select {
  height: 30px;
  margin: 0 4px;
  padding: 0 6px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 4px;
  background: #2a2c31;
  color: #fff;
  font: inherit;
  font-size: 12px;
}

.sheet__rule {
  width: 1px;
  height: 20px;
  margin: 0 4px;
  background: rgba(255, 255, 255, 0.14);
}

.sheet__bar {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.sheet__name {
  flex: none;
  width: 72px;
  overflow: hidden;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.sheet__fx {
  flex: none;
  color: var(--w11-text-2);
  font-family: Georgia, serif;
  font-style: italic;
}

.sheet__formula {
  min-width: 0;
  flex: 1;
  height: 24px;
  padding: 0 6px;
  border: 0;
  border-left: 1px solid rgba(255, 255, 255, 0.12);
  outline: none;
  background: transparent;
  color: inherit;
  font: 13px "Cascadia Code", Consolas, monospace;
}

.sheet__scroll {
  position: relative;
  min-height: 0;
  flex: 1;
  overflow: auto;
  outline: none;
  background: #fff;
  cursor: cell;
  user-select: none;
}

.sheet__table {
  width: calc(40px + 26 * 96px);
  border-collapse: separate;
  border-spacing: 0;
  color: #1f2328;
  font-size: 13px;
  table-layout: fixed;
}

.sheet__table th {
  position: sticky;
  z-index: 1;
  background: #eef0f3;
  color: #535a64;
  font-size: 12px;
  font-weight: 500;
}

.sheet__table thead th {
  z-index: 2;
  top: 0;
  width: 96px;
  height: 24px;
  border-right: 1px solid #d3d7dd;
  border-bottom: 1px solid #c2c7cf;
}

.sheet__table tbody th {
  left: 0;
  width: 40px;
  min-width: 40px;
  height: 24px;
  border-right: 1px solid #c2c7cf;
  border-bottom: 1px solid #d3d7dd;
}

.sheet__table .sheet__corner {
  z-index: 3;
  left: 0;
  width: 40px;
  min-width: 40px;
}

.sheet__table th.is-lit {
  background: #d7f1e4;
  color: #0c6b43;
  font-weight: 600;
}

.sheet__cell {
  width: 96px;
  max-width: 96px;
  height: 24px;
  overflow: hidden;
  padding: 0 4px;
  border-right: 1px solid #e3e5e9;
  border-bottom: 1px solid #e3e5e9;
  text-overflow: clip;
  white-space: nowrap;
}

.sheet__cell.is-right {
  text-align: right;
}

.sheet__cell.is-center {
  text-align: center;
}

.sheet__cell.is-bold {
  font-weight: 700;
}

.sheet__cell.is-error {
  color: #c62828;
  font-weight: 600;
}

.sheet__cell.is-selected {
  background: #dff3e9;
}

.sheet__cell.is-active {
  box-shadow: inset 0 0 0 2px #107c41;
}

.sheet__scroll:focus-visible .sheet__cell.is-active {
  box-shadow: inset 0 0 0 2px #107c41, inset 0 0 0 3px #fff;
}

.sheet__status {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 4px 12px;
  color: var(--w11-text-2);
  font-size: 12px;
}

.sheet :is(button, select):focus-visible {
  outline: 2px solid #60cdff;
  outline-offset: -2px;
}

files.src/styles/task-manager.css:
.tasks {
  height: 100%;
  min-height: 0;
  background: #202124;
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 13px;
  line-height: 20px;
  container-type: inline-size;
}

.tasks__frame {
  display: grid;
  height: 100%;
  min-height: 0;
  grid-template-columns: 160px minmax(0, 1fr);
}

.tasks__tabs {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 4px;
  background: #1a1b1e;
}

.tasks__tabs button {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.tasks__tabs button:hover {
  background: var(--w11-subtle-hover);
}

.tasks__tabs button.is-active {
  background: rgba(255, 255, 255, 0.08);
  box-shadow: inset 3px 0 0 var(--w11-accent);
}

.tasks__main {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
}

.tasks__bar {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 8px 12px;
}

.tasks__bar h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  line-height: 28px;
}

.tasks__bar > span {
  display: flex;
  gap: 6px;
}

.tasks__bar button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.tasks__bar button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12);
}

.tasks__bar button:disabled {
  opacity: 0.45;
  cursor: default;
}

.tasks__scroll {
  min-height: 0;
  flex: 1;
  overflow: auto;
}

.tasks__table {
  width: 100%;
  border-collapse: collapse;
}

.tasks__table th {
  position: sticky;
  z-index: 1;
  top: 0;
  padding: 6px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: #202124;
  color: var(--w11-text-2);
  font-size: 12px;
  font-weight: 600;
  text-align: left;
}

.tasks__table td {
  padding: 6px 12px;
  white-space: nowrap;
}

.tasks__table tbody tr {
  cursor: default;
}

.tasks__table tbody tr:hover {
  background: rgba(255, 255, 255, 0.05);
}

.tasks__table tbody tr.is-selected {
  background: rgba(96, 205, 255, 0.16);
}

.tasks__table tbody tr:focus-visible {
  outline: 2px solid var(--w11-accent);
  outline-offset: -2px;
}

.tasks__name {
  display: flex;
  min-width: 0;
  max-width: 300px;
  align-items: center;
  gap: 10px;
}

.tasks__name svg {
