}

.tasks__count {
  flex: none;
  margin: 0;
  padding: 6px 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--w11-text-2);
  font-size: 12px;
}

.tasks__main--performance {
  overflow-y: auto;
  padding-bottom: 12px;
}

.tasks__chart {
  flex: none;
  margin: 0 12px;
}

.tasks__chart header,
.tasks__chart footer {
  display: flex;
  justify-content: space-between;
}

.tasks__chart header span {
  font-variant-numeric: tabular-nums;
}

.tasks__chart footer {
  color: var(--w11-text-2);
  font-size: 11px;
}

.tasks__chart svg {
  display: block;
  width: 100%;
  height: 160px;
  border: 1px solid rgba(96, 205, 255, 0.4);
  background: rgba(96, 205, 255, 0.06) linear-gradient(rgba(96, 205, 255, 0.12) 1px, transparent 1px) 0 0 / 100% 25%;
}

.tasks__chart polyline {
  fill: none;
  stroke: #60cdff;
  stroke-width: 1.5;
}

.tasks__facts {
  display: grid;
  flex: none;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 12px;
  margin: 16px 12px 0;
}

.tasks__facts dt {
  color: var(--w11-text-2);
  font-size: 12px;
}

.tasks__facts dd {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}

@container (max-width: 560px) {
  .tasks__frame {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .tasks__tabs {
    flex-direction: row;
  }

  .tasks__tabs button {
    flex: 1;
    justify-content: center;
  }

  .tasks__tabs button.is-active {
    box-shadow: inset 0 -3px 0 var(--w11-accent);
  }

  .tasks__wide {
    display: none;
  }

  .tasks__name {
    max-width: 170px;
  }

  .tasks__bar button {
    white-space: nowrap;
  }
}

files.src/styles/tv-app.css:
/* A dark room with the set on: the picture lights the walls. Amber is the signal colour. */
.tv {
  --tv-ink: #07080b;
  --tv-panel: #0e1014;
  --tv-raised: #181b21;
  --tv-line: rgba(255, 255, 255, 0.07);
  --tv-text: #f4f4f2;
  --tv-text-2: #979ca6;
  --tv-signal: #ffb224;
  --tv-mono: "IBM Plex Mono", "Cascadia Mono", Consolas, monospace;

  height: 100%;
  min-height: 0;
  outline: none;
  background: var(--tv-ink);
  color: var(--tv-text);
  font-family: var(--w11-font);
  font-size: 13px;
  line-height: 18px;
  container-type: inline-size;
}

.tv button,
.tv input {
  color: inherit;
  font: inherit;
}

.tv__frame {
  display: grid;
  height: 100%;
  min-height: 0;
  grid-template-columns: 300px minmax(0, 1fr);
}

.tv__frame.is-theatre {
  grid-template-columns: minmax(0, 1fr);
}

.tv__guide {
  display: flex;
  min-height: 0;
  flex-direction: column;
  border-right: 1px solid var(--tv-line);
  background: var(--tv-panel);
}

.tv__tabs {
  display: flex;
  flex: none;
  gap: 2px;
  margin: 10px 12px 0;
  padding: 3px;
  border-radius: 9px;
  background: var(--tv-raised);
}

.tv__tabs button {
  flex: 1;
  height: 28px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--tv-text-2);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.15s ease, background 0.15s ease;
}

.tv__tabs button:hover {
  color: var(--tv-text);
}

.tv__tabs button.is-active {
  background: var(--tv-text);
  color: #111318;
}

.tv__search {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  height: 34px;
  margin: 8px 12px;
  padding: 0 12px;
  border: 1px solid var(--tv-line);
  border-radius: 9px;
  color: var(--tv-text-2);
}

.tv__search:focus-within {
  border-color: var(--tv-signal);
}

.tv__search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: none;
  background: transparent;
}

.tv__chips {
  display: flex;
  flex: none;
  gap: 4px;
  padding: 0 12px 8px;
  overflow-x: auto;
  scrollbar-width: none;
}

.tv__chips button {
  flex: none;
  height: 24px;
  padding: 0 10px;
  border: 1px solid var(--tv-line);
  border-radius: 12px;
  background: transparent;
  color: var(--tv-text-2);
  font-size: 12px;
  cursor: pointer;
}

.tv__chips button.is-active {
  border-color: var(--tv-signal);
  background: rgba(255, 178, 36, 0.14);
  color: var(--tv-signal);
}

.tv__list {
  min-height: 0;
  flex: 1;
  margin: 0;
  padding: 0 6px 8px;
  overflow-y: auto;
  list-style: none;
  scrollbar-width: thin;
}

.tv__row {
  position: relative;
  display: flex;
  align-items: center;
  border-radius: 8px;
}

.tv__row:hover {
  background: var(--tv-raised);
}

.tv__row.is-active {
  background: linear-gradient(90deg, rgba(255, 178, 36, 0.16), var(--tv-raised) 70%);
}

.tv__row.is-down {
  opacity: 0.5;
}

.tv__tune {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 10px;
  height: 56px;
  padding: 0 4px 0 8px;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.tv__number,
.tv__eq {
  flex: none;
  width: 18px;
}

.tv__number {
  color: var(--tv-text-2);
  font-family: var(--tv-mono);
  font-size: 11px;
}

/* The row on the air keeps time with it. */
.tv__eq {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 14px;
}

.tv__eq i {
  width: 3px;
  height: 100%;
  border-radius: 1px;
  background: var(--tv-signal);
  transform-origin: bottom;
  animation: tv-level 0.9s ease-in-out infinite alternate;
}

.tv__eq i:nth-child(2) {
  animation-delay: -0.35s;
}

.tv__eq i:nth-child(3) {
  animation-delay: -0.6s;
}

@keyframes tv-level {
  from {
    transform: scaleY(0.25);
  }

  to {
    transform: scaleY(1);
  }
}

.tv__logo {
  display: grid;
  flex: none;
  place-items: center;
  width: 48px;
  height: 36px;
  overflow: hidden;
  border: 1px solid var(--tv-line);
  border-radius: 6px;
  background: linear-gradient(145deg, #262b35, #171a20);
  color: var(--tv-text);
  font-family: var(--tv-mono);
  font-size: 12px;
  font-weight: 600;
}

.tv__logo img {
  width: 100%;
  height: 100%;
  padding: 3px;
  object-fit: contain;
}

.tv__row-text {
  min-width: 0;
  flex: 1;
}

.tv__row-text strong,
.tv__row-text small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tv__row-text strong {
  font-weight: 600;
}

.tv__row-text small {
  color: var(--tv-text-2);
  font-size: 11px;
  line-height: 15px;
}

/* Scaled rather than sized, so a tick of the clock costs no layout. */
.tv__bar {
  display: block;
  height: 2px;
  margin-top: 4px;
  overflow: hidden;
  border-radius: 1px;
  background: rgba(255, 255, 255, 0.12);
}

.tv__bar i {
  display: block;
  height: 100%;
  background: var(--tv-signal);
  transform-origin: left;
}

.tv__star {
  display: grid;
  flex: none;
  width: 32px;
  height: 32px;
  margin-right: 4px;
  place-items: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--tv-text-2);
  cursor: pointer;
  opacity: 0;
}

.tv__row:hover .tv__star,
.tv__star:focus-visible,
.tv__star.is-on {
  opacity: 1;
}

.tv__star.is-on,
.tv__controls button.is-on {
  color: var(--tv-signal);
}

.tv__none {
  flex: 1;
  margin: 0;
  padding: 32px 16px;
  color: var(--tv-text-2);
  text-align: center;
}

.tv__credit {
  flex: none;
  margin: 0;
  padding: 8px 12px;
  border-top: 1px solid var(--tv-line);
  color: var(--tv-text-2);
  font-size: 11px;
  line-height: 14px;
}

.tv__stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--tv-ink);
}

/* The glow: 32 by 18 pixels of the current frame, stretched and blurred across the bars either side of the picture. */
.tv__ambient {
  position: absolute;
  inset: -12%;
  width: 124%;
  height: 124%;
  filter: blur(56px) saturate(1.5) brightness(0.8);
  opacity: 0.85;
  pointer-events: none;
}

.tv__screen {
  position: absolute;
  inset: 0;
  display: grid;
  overflow: hidden;
  place-items: center;
}

.tv__video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.tv__flash {
  position: absolute;
  inset: 0;
  background: #fff;
  opacity: 0;
  pointer-events: none;
}

.tv__tuning {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
  border-radius: 18px;
  background: rgba(0, 0, 0, 0.6);
  color: var(--tv-signal);
  font-family: var(--tv-mono);
  font-size: 12px;
  pointer-events: none;
}

.tv__tuning span {
  width: 12px;
  height: 12px;
  border: 2px solid rgba(255, 178, 36, 0.3);
  border-top-color: var(--tv-signal);
  border-radius: 50%;
  animation: tv-turn 0.8s linear infinite;
}

@keyframes tv-turn {
  to {
    transform: rotate(360deg);
  }
}

/* Sits on the picture, so the set gets the whole stage when nobody is touching it. */
.tv__controls {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 44px 14px 8px;
  background: linear-gradient(transparent, rgba(5, 6, 9, 0.72) 42%, rgba(5, 6, 9, 0.92));
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.tv__stage.is-quiet .tv__controls {
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
}

.tv__stage.is-quiet {
  cursor: none;
}

.tv__meta {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding: 0 4px;
}

.tv__meta strong {
  flex: none;
  max-width: 50%;
  overflow: hidden;
  font-size: 15px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tv__title {
  min-width: 0;
  overflow: hidden;
  color: var(--tv-text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tv__meta time {
  flex: none;
  margin-left: auto;
  color: var(--tv-text-2);
  font-family: var(--tv-mono);
  font-size: 11px;
}

.tv__controls .tv__bar {
  height: 3px;
  margin: 6px 4px 2px;
}

.tv__buttons {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 38px;
}

.tv__buttons button {
  display: grid;
  flex: none;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
}

.tv__buttons button:hover {
  background: rgba(255, 255, 255, 0.14);
}

.tv__volume {
  width: 88px;
  flex: none;
  accent-color: var(--tv-signal);
}

.tv__next {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  padding: 0 12px;
  color: var(--tv-text-2);
  font-size: 12px;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tv__live {
  flex: none;
  align-self: center;
  padding: 0 6px;
  border: 1px solid var(--tv-line);
  border-radius: 3px;
  color: var(--tv-text-2);
  font-family: var(--tv-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  line-height: 16px;
  text-transform: uppercase;
}

.tv__live.is-on {
  border-color: #e5484d;
  background: #e5484d;
  color: #fff;
}

.tv__home {
  position: relative;
  display: grid;
  width: min(100%, 620px);
  max-height: 100%;
  justify-items: start;
  gap: 8px;
  padding: 24px;
  overflow-y: auto;
  scrollbar-width: none;
}

.tv__eyebrow {
  margin: 0;
  color: var(--tv-signal);
  font-family: var(--tv-mono);
  font-size: 12px;
}

.tv__home h1 {
  margin: 0 0 8px;
  font-size: 34px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 40px;
}

.tv__resume {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  margin-bottom: 8px;
  padding: 0 18px;
  border: 0;
  border-radius: 19px;
  background: var(--tv-signal);
  color: #1a1204 !important;
  font-weight: 600 !important;
  cursor: pointer;
}

.tv__tiles {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.tv__tile {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  height: 64px;
  padding: 0 12px;
  border: 1px solid var(--tv-line);
  border-radius: 10px;
  background: var(--tv-panel);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, transform 0.15s ease;
}

.tv__tile:hover {
  border-color: var(--tv-signal);
  transform: translateY(-2px);
}

.tv__keys {
  margin: 8px 0 0;
  color: var(--tv-text-2);
  font-size: 12px;
}

.tv__keys kbd {
  padding: 0 4px;
  border: 1px solid var(--tv-line);
  border-radius: 3px;
  font-family: var(--tv-mono);
  font-size: 11px;
}

.tv__radio,
.tv__offair {
  position: relative;
  display: grid;
  max-width: 400px;
  justify-items: center;
  gap: 8px;
  padding: 24px;
  text-align: center;
}

.tv__radio strong {
  font-size: 26px;
  line-height: 32px;
}

.tv__radio small,
.tv__offair small {
  color: var(--tv-text-2);
}

.tv__dial {
  display: grid;
  width: 112px;
  height: 112px;
  place-items: center;
  border: 1px solid rgba(255, 178, 36, 0.4);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 178, 36, 0.26), transparent 70%);
  color: var(--tv-signal);
}

.tv__dial.is-on {
  animation: tv-on-air 1.8s ease-in-out infinite;
}

@keyframes tv-on-air {
  50% {
    box-shadow: 0 0 0 16px rgba(255, 178, 36, 0.1);
  }
}

.tv__wave {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 32px;
  margin-top: 8px;
  opacity: 0.25;
  transition: opacity 0.3s ease;
}

.tv__wave.is-on {
  opacity: 1;
}

.tv__wave i {
  width: 3px;
  height: 100%;
  border-radius: 2px;
  background: var(--tv-signal);
  transform: scaleY(0.15);
}

.tv__wave.is-on i {
  animation: tv-level 0.9s ease-in-out infinite alternate;
}

:root[data-reduce-motion] :is(.tv__dial.is-on, .tv__eq i, .tv__wave.is-on i, .tv__tuning span) {
  animation: none;
}

.tv__offair {
  position: absolute;
}

.tv__offair-mark {
  color: var(--tv-signal);
  font-family: var(--tv-mono);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.tv__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 4px;
}

.tv__action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  text-decoration: none;
  cursor: pointer;
}

.tv__action--primary {
  border-color: var(--tv-signal);
  background: var(--tv-signal);
  color: #1a1204 !important;
  font-weight: 600 !important;
}

.tv :is(button, a, input):focus-visible {
  outline: 2px solid var(--tv-signal);
  outline-offset: -2px;
}

@container (max-width: 760px) {
  .tv__next,
  .tv__keys {
    display: none;
  }

  .tv__buttons .tv__volume {
    flex: 1;
    width: auto;
    min-width: 0;
  }
}

@container (max-width: 680px) {
  .tv__frame {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .tv__frame.is-theatre {
    grid-template-rows: minmax(0, 1fr);
  }

  .tv__stage {
    order: -1;
    height: 56.25cqw;
    min-height: 220px;
  }

  .tv__frame.is-theatre .tv__stage {
    height: auto;
  }

  .tv__controls {
    padding: 24px 6px 2px;
  }

  .tv__meta time,
  .tv__title,
  .tv__buttons .tv__volume {
    display: none;
  }

  .tv__buttons {
    justify-content: space-between;
  }

  .tv__guide {
    border-right: 0;
    border-top: 1px solid var(--tv-line);
  }

  .tv__tile:nth-child(n + 5) {
    display: none;
  }

  .tv__tile {
    height: 52px;
    padding: 0 8px;
  }

  .tv__home {
    gap: 4px;
    padding: 8px;
  }

  .tv__home h1 {
    margin: 0;
    font-size: 18px;
    line-height: 24px;
  }

  .tv__resume {
    height: 32px;
    margin: 4px 0;
  }
}

