/* ═══════════════════════════════════════════════════════════════════
   TaanielOS Visual Redesign — drop-in CSS override
   ═══════════════════════════════════════════════════════════════════ */


/* ── 1. Tokens ──────────────────────────────────────────────────── */
:root {
  font-family: "Plus Jakarta Sans", "IBM Plex Sans", sans-serif;
  --shadow-window:  0 32px 80px rgba(0, 0, 0, 0.58), 0 2px 0 rgba(255, 255, 255, 0.065) inset;
  --shadow-ambient: 0 16px 40px rgba(0, 0, 0, 0.38);
  --desktop-glow:   rgba(255, 141, 88, 0.52);
  --icon-size:      64px;
  --icon-radius:    15px;
  --taskbar-height: 52px;
}


/* ── 2. Wallpaper — richer ambient glows + dot grid ────────────── */
.os-root__wallpaper::before {
  background:
    radial-gradient(ellipse 70% 55% at 10% 90%, var(--desktop-glow), transparent 60%),
    radial-gradient(ellipse 55% 45% at 90% 8%,  rgba(119, 199, 255, 0.22), transparent 55%),
    radial-gradient(ellipse 45% 40% at 50% 40%, rgba(90, 120, 200, 0.12), transparent 60%);
  mix-blend-mode: screen;
  filter: blur(40px);
}

.os-root__wallpaper::after {
  background-image: radial-gradient(circle, rgba(255, 255, 255, 0.18) 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: linear-gradient(to bottom, transparent 0%, black 14%, black 78%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 14%, black 78%, transparent 100%);
  opacity: 0.22;
}


/* ── 3. Desktop surface + window manager ────────────────────────── */
/* Taskbar now floats above content — no bottom inset needed */
.desktop-surface {
  inset: 0;
}

.window-manager {
  inset: 0 0 80px;
}


/* ── 4. Desktop icons — squircle style ──────────────────────────── */
.desktop-icon {
  width: clamp(78px, calc(var(--desktop-cell-width) - 8px), 96px);
  gap: 0.45rem;
  padding: 0.65rem 0.4rem;
}

.desktop-icon__glyph {
  width:  clamp(54px, calc(var(--desktop-cell-width) * 0.75), var(--icon-size));
  height: clamp(54px, calc(var(--desktop-cell-width) * 0.75), var(--icon-size));
  border-radius: 0;
  display: grid;
  place-items: center;
  transition: transform 120ms ease;
}

/* Hover lift — like Puter icons */
@media (hover: hover) and (pointer: fine) {
  .desktop-icon:hover .desktop-icon__glyph {
    transform: scale(1.04);
  }
}

.desktop-icon__label {
  font-size: 0.8rem;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.65);
}

/* Active-window dot indicator under icon */
.desktop-icon__active-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--theme-accent);
  box-shadow: 0 0 8px rgba(119, 199, 255, 0.65);
  margin-top: -2px;
  flex-shrink: 0;
}


/* ── 5. Taskbar — centered floating pill ────────────────────────── */
.taskbar {
  position: fixed;
  right: auto;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);

  width: max-content;
  max-width: calc(100vw - 32px);

  display: flex;
  grid-template-columns: unset;
  align-items: center;
  gap: 3px;
  padding: 0 8px;
  height: var(--taskbar-height);

  border-radius: 18px;
  backdrop-filter: blur(28px) saturate(1.6);
  box-shadow:
    0 18px 52px rgba(0, 0, 0, 0.55),
    0 1.5px 0 rgba(255, 255, 255, 0.08) inset;
}

.taskbar__start {
  height: 36px;
  min-height: unset;
  padding: 0 12px;
  border-radius: 10px;
  gap: 7px;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-right: 4px;
  border-right: 1px solid rgba(255, 255, 255, 0.09);
}

.taskbar__search-field {
  height: 34px;
  min-height: unset;
  min-width: 100px;
  max-width: 170px;
  flex: 0 1 150px;
  padding: 0 10px;
  padding-block: 0;
  border-radius: 10px;
  margin-right: 6px;
}

.taskbar__windows {
  overflow: visible;
}

.taskbar__window-strip {
  gap: 3px;
  overflow: visible;
}

.taskbar__item {
  height: 36px;
  min-height: unset;
  padding: 0 11px;
  padding-bottom: 0;
  border-radius: 10px;
  max-width: min(148px, 22vw);
  gap: 6px;
}

.taskbar__item-indicator {
  position: absolute;
  bottom: 3px;
  left: 50%;
  right: auto;
  width: 18px;
  height: 2.5px;
  opacity: 1;
  transform: translateX(-50%) scaleX(0);
  transform-origin: center;
  box-shadow: 0 0 6px rgba(119, 199, 255, 0.55);
  transition: transform 180ms ease, opacity 180ms ease;
}

.taskbar__item.is-active .taskbar__item-indicator {
  transform: translateX(-50%) scaleX(1);
  opacity: 1;
}

.taskbar__item.is-minimized .taskbar__item-indicator {
  transform: translateX(-50%) scaleX(0.5);
  opacity: 0.45;
}

.taskbar__tray {
  margin-left: 4px;
  padding-left: 8px;
  border-left: 1px solid rgba(255, 255, 255, 0.09);
  gap: 4px;
}

.taskbar__clock {
  min-height: unset;
  padding: 0 8px;
  border-radius: 8px;
  gap: 1px;
}

.taskbar__clock strong {
  font-family: "Plus Jakarta Sans", "IBM Plex Sans", sans-serif;
  font-size: 0.8rem;
}

.taskbar__clock small {
  font-size: 0.68rem;
}

.taskbar__desktop {
  min-height: unset;
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 8px;
  justify-content: center;
}

@media (hover: hover) and (pointer: fine) {
  /* Non-item controls get a subtle background on hover (no lift) */
  .taskbar__start:hover,
  .taskbar__clock:hover,
  .taskbar__desktop:hover,
  .taskbar__search-field:hover {
    background: rgba(255, 255, 255, 0.08);
  }
}

/* Styled tooltip for pinned-closed taskbar icons */
.taskbar__item[data-tooltip] {
  position: relative;
}

.taskbar__item[data-tooltip]::before {
  content: attr(data-tooltip);
  position: absolute;
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  white-space: nowrap;
  font-size: 0.72rem;
  font-weight: 600;
  font-family: "Plus Jakarta Sans", "IBM Plex Sans", sans-serif;
  color: rgba(255, 255, 255, 0.92);
  background: rgba(20, 20, 30, 0.88);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  padding: 3px 8px;
  backdrop-filter: blur(12px);
  pointer-events: none;
  opacity: 0;
  transition: opacity 120ms ease, transform 120ms ease;
  z-index: 200;
}

@media (hover: hover) and (pointer: fine) {
  .taskbar__item[data-tooltip]:hover::before {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}


/* ── 6. Menus & popovers — stronger glass blur ──────────────── */
.context-menu,
.calendar-popover {
  backdrop-filter: blur(24px) saturate(1.5);
}


/* ── 7. Window frames — deeper glass ────────────────────────── */
.window-frame {
  backdrop-filter: blur(22px) saturate(1.4);
  transition: box-shadow 180ms ease, opacity 180ms ease;
}

.window-frame.is-active {
  border-color: rgba(119, 199, 255, 0.26);
  box-shadow: var(--shadow-window);
}

/* Drag-lift: window feels heavy and elevated while moving */
.window-frame.is-dragging {
  box-shadow:
    0 48px 120px rgba(0, 0, 0, 0.72),
    0 8px 32px rgba(0, 0, 0, 0.48),
    0 0 0 1px rgba(255, 255, 255, 0.12);
  border-color: rgba(119, 199, 255, 0.35);
}

.window-frame__header {
  height: 38px;
  padding: 0 0.55rem;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.055) 0%,
    rgba(255, 255, 255, 0.012) 100%
  );
}

/* Title icon in header — coloured accent dot */
.window-frame__title-icon {
  width: 20px;
  height: 20px;
  border-radius: 0;
}

/* Centred title text */
.window-frame__title--centered strong {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-strong);
  letter-spacing: -0.01em;
}


/* ── 7. App interiors ───────────────────────────────────────────── */

.glass-card,
.hero-panel {
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: none;
  backdrop-filter: none;
}

.eyebrow {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--theme-accent);
  margin-bottom: 0.3rem;
}

.pill-button {
  border-radius: 8px;
  font-size: 0.78rem;
}

.token-list span {
  border: 1px solid rgba(255, 255, 255, 0.09);
  font-size: 0.78rem;
}

.about-app .bullet-stack p {
  padding-left: 0.75rem;
  border-left: 2px solid rgba(119, 199, 255, 0.22);
}

.photo-thumb {
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  overflow: hidden;
  background: rgba(255, 255, 255, 0.04);
}

.project-showcase {
  border-radius: 12px;
}

.mini-facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

.mini-facts div {
  padding: 0.6rem 0.72rem;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.mini-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.project-showcase .mini-facts {
  grid-template-columns: minmax(0, 1fr);
}

.project-showcase .mini-facts div {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.project-showcase__image img {
  object-fit: contain;
}

.contact-link-card {
  border-radius: 10px;
  padding: 0.85rem 1rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: background 140ms ease, border-color 140ms ease;
}

.contact-link-card:hover {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.14);
}

.stat-card {
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}


/* ── 8. Overlay / popover offsets for floating taskbar ──────────── */
.toast-container {
  bottom: 88px;
}

.calendar-popover {
  bottom: 80px;
}

.search-panel {
  bottom: 80px;
}


/* ── 9. Responsive — restore full-width bar on small screens ────── */
@media (max-width: 820px) {
  .taskbar {
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 12px;
    transform: none;
    width: auto;
    max-width: none;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: 44px 44px;
    height: 100px;
    padding: 4px 8px;
    border-radius: 0.72rem;
  }

  /* Keep the icon grid clear of the mobile recruiter banner pinned at the top */
  .desktop-surface {
    inset: 4.5rem 0 112px;
  }

  .window-manager {
    inset: 0 0 108px;
  }

  .taskbar__start {
    height: 44px;
    justify-content: center;
    letter-spacing: 0;
  }

  .taskbar__search-field {
    height: 44px;
    width: min(170px, 44vw);
    min-width: 0;
    max-width: none;
    margin: 0;
  }

  .taskbar__windows {
    order: 0;
    min-width: 0;
    overflow: hidden;
  }

  .taskbar__window-strip {
    overflow-x: auto;
    overflow-y: hidden;
    max-width: 100%;
  }

  .taskbar__item {
    flex: 0 0 auto;
    height: 44px;
    min-width: 44px;
    max-width: 120px;
    justify-content: center;
  }

  .taskbar__tray {
    flex-wrap: nowrap;
    justify-content: flex-end;
    margin: 0;
    padding: 0;
    border: 0;
  }

  .taskbar__clock {
    flex: 0 0 auto;
    height: 44px;
    white-space: nowrap;
  }

  .taskbar__desktop {
    flex: 0 0 44px;
    width: 44px;
    height: 44px;
  }

  .hero-panel h1, .section-headline h1 {
    font-size: 1.5rem;
    line-height: 1.25;
  }

  .window-frame__header {
    min-height: 52px;
  }

  .window-frame__actions button {
    width: 40px;
    height: 40px;
    border-radius: 6px;
  }

  .window-frame__actions button.is-close,
  .window-frame__actions button.is-minimize,
  .window-frame__actions button.is-maximize {
    background: transparent;
  }

  .window-frame__actions button::before {
    display: none;
  }

  .window-frame__actions button svg {
    width: 18px;
    height: 18px;
    opacity: 1;
    color: var(--text);
  }

  .search-panel, .calendar-panel {
    bottom: 120px;
  }

  .taskbar__item-indicator {
    left: 0.62rem;
    right: 0.62rem;
    width: auto;
    transform: scaleX(0.38);
    bottom: 0.16rem;
  }

  .taskbar__item.is-active .taskbar__item-indicator {
    transform: scaleX(1);
  }

  .taskbar__item.is-minimized .taskbar__item-indicator {
    transform: scaleX(0.62);
  }
}


/* ── 10. Puter-style desktop icon selection ────────────────────── */
.desktop-icon:hover,
.desktop-icon.is-selected {
  background: rgba(119, 199, 255, 0.1);
  border-radius: 10px;
  box-shadow: 0 0 0 1.5px rgba(119, 199, 255, 0.22);
}

.desktop-icon-button:focus-visible {
  outline: 2px solid var(--theme-accent);
  outline-offset: 3px;
  border-radius: 10px;
  background: rgba(119, 199, 255, 0.1);
  box-shadow: 0 0 0 1.5px rgba(119, 199, 255, 0.22);
}

.desktop-icon.is-selected .desktop-icon__label {
  background: rgba(77, 155, 255, 0.28);
  border-radius: 4px;
  padding: 1px 4px;
}


/* ── 11. Window frame — Puter-style improvements ───────────────── */
/* Sharper border on active window */
.window-frame.is-active {
  border-color: rgba(119, 199, 255, 0.32);
  box-shadow:
    var(--shadow-window),
    0 0 0 1px rgba(119, 199, 255, 0.14);
}

/* Inactive windows are clearly de-emphasized */
.window-frame:not(.is-active) {
  opacity: 0.92;
}

/* Header actions spacing tweak for traffic lights */
.window-frame__actions {
  gap: 0.38rem;
}

/* Header drag region cursor */
.window-header {
  cursor: default;
}

/* Action buttons get subtle scale on click */
.window-frame__actions button:active {
  transform: scale(0.88);
}


/* ── 12. Taskbar window item — icon-only pill for pinned-closed ── */
.taskbar__item--pinned-closed {
  padding: 0 8px;
  min-width: 36px;
  justify-content: center;
}

/* Active item glow */
.taskbar__item.is-active {
  background: rgba(119, 199, 255, 0.1);
}


/* ── 13. Window snap ghost polish ──────────────────────────────── */
.window-snap-ghost {
  border-radius: 14px;
}


/* ── 14. Start button Puter-style ──────────────────────────────── */
.taskbar__start {
  background: linear-gradient(
    135deg,
    rgba(119, 199, 255, 0.15) 0%,
    rgba(80, 120, 200, 0.1) 100%
  );
  border: 1px solid rgba(119, 199, 255, 0.15);
}

.taskbar__start:hover {
  background: linear-gradient(
    135deg,
    rgba(119, 199, 255, 0.22) 0%,
    rgba(80, 120, 200, 0.16) 100%
  ) !important;
  border-color: rgba(119, 199, 255, 0.25) !important;
}


/* ── 15. Taskbar item micro-lift on hover ──────────────────────── */
@media (hover: hover) and (pointer: fine) {
  .taskbar__item:hover {
    transform: translateY(-2px);
  }

  .taskbar__item:active {
    transform: translateY(0);
  }
}


/* ── 16. Global thin scrollbar ─────────────────────────────────── */
* {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.12) transparent;
}

*::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 99px;
}

*::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}


/* ── 17. Window frame header — tighter, more refined ──────────── */
.window-frame__title small {
  font-size: 0.68rem;
  opacity: 0.55;
}

/* Larger title icon badge */
.window-frame__title-icon {
  width: 22px;
  height: 22px;
  border-radius: 7px;
}


/* ── 18. Jump list (right-click taskbar menu) polish ──────────── */
.taskbar__jump-list {
  min-width: 200px;
  border-radius: 14px;
  padding: 0.35rem;
}


/* ── 19. Window preview card polish ────────────────────────────── */
.taskbar__preview {
  border-radius: 14px;
}

.taskbar__preview-frame {
  border-radius: 10px;
  overflow: hidden;
}

