files.src/styles/win11-a11y.css:
/* Accessibility layer: skip link, focus rings, contrast and Windows high contrast. */

.os-root__main {
  display: contents;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.os-skip-link {
  position: fixed;
  left: 12px;
  top: 12px;
  z-index: 13000;
  padding: 10px 14px;
  border-radius: var(--w11-radius-control);
  background: var(--w11-accent);
  color: var(--w11-on-accent);
  font: 600 14px var(--w11-font);
  transform: translateY(-200%);
}

.os-skip-link:focus {
  transform: none;
}

/* A window takes focus as a whole when it opens; only its controls show a ring. */
.window-frame:focus {
  outline: none;
}

/* Two tones, so the ring shows on any wallpaper or window colour. */
.desktop-icon:focus-visible,
.w11-taskbar button:focus-visible,
.context-menu__item:focus-visible,
.open-with-dialog button:focus-visible,
.cheatsheet button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 1px;
  box-shadow: 0 0 0 4px rgb(0 0 0 / 80%);
}

/* The default accent is only about 3.6:1 on the dark window background. */
.window-frame .eyebrow {
  color: #60cdff;
}

/* White labels need help on the light wallpaper. */
.os-root.is-light-wallpaper .desktop-icon__label {
  padding: 0 4px;
  border-radius: 4px;
  background: rgb(0 0 0 / 62%);
  text-shadow: none;
}

@media (forced-colors: active) {
  .desktop-icon.is-selected,
  .context-menu__item:focus,
  .window-frame.is-active {
    outline: 2px solid Highlight;
  }

  .w11-taskbar__app.is-active,
  .w11-taskbar__app.is-running {
    border-bottom: 2px solid CanvasText;
  }

  .w11-flyout,
  .w11-start,
  .context-menu,
  .window-frame {
    border: 1px solid CanvasText;
  }
}

/* Settings > Accessibility > Text size. */
.window-frame__body {
  zoom: var(--os-text-zoom, 1);
}

/* Settings > Accessibility > More contrast. */
:root[data-contrast="more"] {
  --w11-text-2: var(--w11-text);
  --w11-divider: currentColor;
}

:root[data-contrast="more"] :is(.w11-taskbar, .w11-start, .w11-flyout, .context-menu, .window-frame) {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  border: 1px solid currentColor;
}

:root[data-contrast="more"] :is(.w11-taskbar, .w11-start, .w11-flyout) {
  background: var(--w11-surface-solid, #1a1a1a);
}

/* Toasts share the bottom-right corner with the tray flyouts; step aside while one is open. */
body:has(.w11-quick) .toast-container,
body:has(.w11-calendar) .toast-container {
  right: 384px;
}

@media (max-width: 720px) {
  body:has(.w11-quick) .toast-container,
  body:has(.w11-calendar) .toast-container {
    display: none;
  }
}

/* Settings > Personalization > Taskbar alignment. The centre is the default; this moves apps and Start to the left edge. */
:root[data-taskbar-align="left"] .w11-taskbar__center {
  grid-column: 1;
  justify-self: start;
  padding-left: 4px;
}

:root[data-taskbar-align="left"] .w11-start {
  margin-inline: 12px auto;
}

/* Settings > Personalization > Accent colour. Each name maps to a fixed colour here, never to a value from storage. */
:root[data-accent="sky"] { --os-accent: #7fb4ff; }
:root[data-accent="mint"] { --os-accent: #5fe3b4; }
:root[data-accent="lime"] { --os-accent: #b5e35a; }
:root[data-accent="amber"] { --os-accent: #ffc95c; }
:root[data-accent="coral"] { --os-accent: #ff9a7a; }
:root[data-accent="rose"] { --os-accent: #ff8fb8; }
:root[data-accent="violet"] { --os-accent: #b99cff; }

:root[data-accent],
:root[data-accent] .w11-settings {
  --w11-accent: var(--os-accent);
  --w11-on-accent: #000000;
}

/* Settings > Personalization > Desktop icons. */
:root[data-desktop-icons="hidden"] .desktop-icon {
  display: none;
}

:root[data-icon-size="small"] { --os-icon-px: 36px; }
:root[data-icon-size="large"] { --os-icon-px: 56px; }

/* The icon components size themselves inline, so the override has to be important. */
:root[data-icon-size] .desktop-icon__glyph,
:root[data-icon-size] .desktop-icon__glyph .node-icon {
  width: var(--os-icon-px) !important;
  height: var(--os-icon-px) !important;
}

:root[data-icon-size] .desktop-icon__glyph > svg,
:root[data-icon-size] .desktop-icon__glyph .node-icon > svg:not(.node-icon__badge) {
  width: 100%;
  height: 100%;
}

:root[data-icon-size="small"] .desktop-icon__label {
  font-size: 11px;
}

/* Settings > Personalization > Wallpaper fit. Only set while a picture is the wallpaper; its dimming layer stays full size. */
:root[data-wallpaper-fit] .os-root__wallpaper {
  background-color: #000;
  background-position: center, center;
  background-repeat: no-repeat, no-repeat;
}

:root[data-wallpaper-fit="fit"] .os-root__wallpaper {
  background-size: 100% 100%, contain;
}

:root[data-wallpaper-fit="stretch"] .os-root__wallpaper {
  background-size: 100% 100%, 100% 100%;
}

:root[data-wallpaper-fit="center"] .os-root__wallpaper {
  background-size: 100% 100%, auto;
}

:root[data-wallpaper-fit="tile"] .os-root__wallpaper {
  background-size: 100% 100%, auto;
  background-repeat: no-repeat, repeat;
  background-position: 0 0, 0 0;
}

files.src/styles/win11-desktop.css:
/*
 * Windows 11 desktop and File Explorer file handling: shortcut icons, desktop
 * icons, selection, drag ghost, drop targets. Loaded after win11.css, so it
 * wins over the older desktop rules in global.css and visual-redesign.css.
 * Colours come from the --w11-* tokens, so light and dark both work.
 */

/* ------------------------------------------------------------ shortcut icon */

.node-icon {
  position: relative;
  display: inline-grid;
  flex: none;
  place-items: center;
}

.node-icon__badge {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 36%;
  height: 36%;
  pointer-events: none;
}

/* ------------------------------------------------------------ desktop icons */

/* Windows icons are flat: a label under the picture, a translucent box when selected. */
.desktop-icon {
  z-index: 2;
  width: clamp(72px, calc(var(--desktop-cell-width) - 8px), 92px);
  gap: 4px;
  padding: 6px 4px 8px;
  border: 1px solid transparent;
  border-radius: var(--w11-radius-control);
  background: transparent;
  box-shadow: none;
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: manipulation;
}

.desktop-icon:hover {
  border-color: color-mix(in srgb, #fff 14%, transparent);
  background: color-mix(in srgb, #fff 12%, transparent);
  box-shadow: none;
}

.desktop-icon.is-selected {
  z-index: 3;
  border-color: color-mix(in srgb, var(--w11-accent) 62%, transparent);
  background: color-mix(in srgb, var(--w11-accent) 30%, transparent);
  box-shadow: none;
}

.desktop-icon.is-selected:hover {
  background: color-mix(in srgb, var(--w11-accent) 38%, transparent);
}

.desktop-icon:focus {
  outline: none;
}

.desktop-icon:focus-visible {
  outline: 1px dotted #fff;
  outline-offset: -3px;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 55%, transparent);
}

@media (hover: hover) and (pointer: fine) {
  .desktop-icon:hover .desktop-icon__glyph {
    transform: none;
  }
}

.desktop-icon__glyph {
  width: 48px;
  height: 48px;
}

.desktop-icon__label {
  color: #fff;
  font-family: var(--w11-font);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.25;
  text-shadow:
    0 1px 2px rgba(0, 0, 0, 0.85),
    0 0 6px rgba(0, 0, 0, 0.55);
}

/* A selected icon shows its whole name, as in Windows. */
.desktop-icon.is-selected .desktop-icon__label {
  display: block;
  padding: 0;
  border-radius: 0;
  background: none;
  -webkit-line-clamp: unset;
  overflow: visible;
}

/* Cut icons fade until pasted; icons being dragged stay behind as a faint copy. */
.desktop-icon.is-cut .desktop-icon__glyph {
  opacity: 0.5;
}

.desktop-icon.is-drag-source {
  pointer-events: none;
  opacity: 0.45;
}

.desktop-icon.is-renaming {
  z-index: 6;
}

.desktop-icon__rename {
  width: calc(100% + 8px);
  min-height: 2.9em;
  margin: -1px -4px -4px;
  padding: 1px 3px;
  border: 1px solid var(--w11-accent);
  border-radius: 2px;
  background: var(--w11-flyout);
  box-shadow: none;
  color: var(--w11-text);
  font: 400 12px/1.25 var(--w11-font);
  text-align: center;
  text-shadow: none;
  resize: none;
  overflow: hidden;
}

.desktop-icon__rename:focus {
  outline: none;
}

/* The faint box showing the cell an icon will land on. */
.desktop-surface__cell-preview {
  border: 1px solid color-mix(in srgb, var(--w11-accent) 62%, transparent);
  border-radius: var(--w11-radius-control);
  background: color-mix(in srgb, var(--w11-accent) 20%, transparent);
  box-shadow: none;
}

/* Rubber-band selection, on the desktop and in Explorer. */
.desktop-surface__marquee,
.explorer-window__marquee {
  position: absolute;
  z-index: 1;
  border: 1px solid var(--w11-accent);
  background: color-mix(in srgb, var(--w11-accent) 24%, transparent);
  pointer-events: none;
}

/*
 * The file area is a column so its scroll area takes the height that is left
 * and scrolls; as a block the scroll area grew to fit every item and the
 * window clipped what did not fit. The items sit in a box at least as tall as
 * the view, so a rubber band can start on the empty part below them.
 */
.explorer-window__content {
  display: flex;
  flex-direction: column;
}

.explorer-window__content > .explorer-window__scroll-area {
  flex: 1 1 0%;
  min-height: 0;
}

.explorer-window__items {
  position: relative;
  min-height: 100%;
}

/* ------------------------------------------------------------ Explorer items */

.explorer-grid-item,
.explorer-list-item {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row).is-drag-source {
  pointer-events: none;
  opacity: 0.45;
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row):focus {
  outline: none;
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row):focus-visible {
  outline: 2px solid var(--w11-accent);
  outline-offset: -2px;
}

.w11-explorer .explorer-rename-input {
  min-height: 0;
  border: 1px solid var(--w11-accent);
  border-radius: 2px;
  background: var(--w11-explorer-chrome);
  box-shadow: none;
  color: var(--w11-text);
  font: 400 12px/1.25 var(--w11-font);
  resize: none;
}

.w11-explorer .explorer-grid-item .explorer-rename-input {
  min-height: 2.9em;
  overflow: hidden;
}

/* ------------------------------------------------------------ drop targets */

/* Whatever the pointer is over while dragging, when releasing there would do something. */
.desktop-icon[data-drop-active="true"] {
  border-color: var(--w11-accent);
  background: color-mix(in srgb, var(--w11-accent) 38%, transparent);
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row)[data-drop-active="true"] {
  border-color: var(--w11-accent);
  background: color-mix(in srgb, var(--w11-accent) 26%, transparent);
}

.w11-explorer .explorer-window__sidebar-item[data-drop-active="true"] {
  background: color-mix(in srgb, var(--w11-accent) 28%, transparent);
  box-shadow: inset 0 0 0 1px var(--w11-accent);
}

.w11-explorer .w11-explorer__crumb[data-drop-active="true"] {
  background: color-mix(in srgb, var(--w11-accent) 30%, transparent);
  box-shadow: inset 0 0 0 1px var(--w11-accent);
}

.w11-explorer .explorer-window__content[data-drop-active="true"] {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--w11-accent) 70%, transparent);
}

/* A window that a file dropped on it would open in, or move into. */
[data-drop-window-id][data-drop-active="true"] {
  outline: 2px solid var(--w11-accent);
  outline-offset: -2px;
}

.w11-taskbar__app[data-drop-active="true"] {
  background: var(--w11-subtle-hover);
}

/* ------------------------------------------------------------ while dragging */

body.is-file-dragging,
body.is-marquee-selecting {
  -webkit-user-select: none;
  user-select: none;
}

/* A page inside a window would swallow the pointer, so the drag could never reach what is beyond it. */
body.is-file-dragging iframe,
body.is-marquee-selecting iframe {
  pointer-events: none !important;
}

body.is-file-dragging[data-drag-effect="blocked"],
body.is-file-dragging[data-drag-effect="blocked"] * {
  cursor: not-allowed !important;
}

body.is-file-dragging[data-drag-effect="copy"],
body.is-file-dragging[data-drag-effect="copy"] * {
  cursor: copy !important;
}

body.is-file-dragging[data-drag-effect="link"],
body.is-file-dragging[data-drag-effect="link"] * {
  cursor: alias !important;
}

/* ------------------------------------------------------------ drag ghost */

.drag-ghost {
  position: fixed;
  z-index: 2147483000;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  pointer-events: none;
  will-change: transform;
}

.drag-ghost__stack {
  position: absolute;
  top: -24px;
  left: -24px;
  width: 48px;
  height: 48px;
  opacity: 0.88;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.35));
}

.drag-ghost[data-pointer="touch"] .drag-ghost__stack {
  top: -84px;
}

.drag-ghost__icon {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  transform: translate(calc(var(--ghost-index) * -6px), calc(var(--ghost-index) * -6px)) rotate(calc(var(--ghost-index) * -4deg));
}

.drag-ghost__count {
  position: absolute;
  top: -8px;
  right: -10px;
  z-index: 5;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 10px;
  background: var(--w11-accent);
  color: var(--w11-on-accent);
  font: 600 11px/20px var(--w11-font);
  text-align: center;
}

.drag-ghost__chip {
  position: absolute;
  top: 26px;
  left: 18px;
  display: flex;
  max-width: min(300px, 70vw);
  align-items: center;
  gap: 6px;
  padding: 3px 9px 3px 7px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-control);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-flyout);
  color: var(--w11-text);
  font: 400 12px/18px var(--w11-font);
  white-space: nowrap;
}

.drag-ghost__chip span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.drag-ghost[data-pointer="touch"] .drag-ghost__chip {
  top: -26px;
  left: 34px;
}

.drag-ghost[data-blocked="true"] .drag-ghost__chip {
  color: var(--w11-text-2);
}

/* Read out to screen readers; nothing to see. */
.drag-ghost__live {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ------------------------------------------------------------ Move to / Copy to */

.transfer-dialog {
  display: flex;
  width: min(420px, calc(100vw - 32px));
  max-height: min(520px, calc(100dvh - 48px));
  flex-direction: column;
  padding: 20px 20px 16px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-overlay);
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

.transfer-dialog__title {
  margin: 0 0 12px;
  overflow: hidden;
  font-size: 16px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transfer-dialog__list {
  display: flex;
  min-height: 120px;
  flex: 1;
  flex-direction: column;
  gap: 1px;
  overflow-y: auto;
  padding: 4px;
  border: 1px solid var(--w11-divider);
  border-radius: var(--w11-radius-control);
  background: var(--w11-control);
}

.transfer-dialog__folder {
  display: flex;
  min-height: 32px;
  flex: none;
  align-items: center;
  gap: 8px;
  padding-block: 0;
  padding-inline-end: 10px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}

.transfer-dialog__folder:hover:not(.is-disabled) {
  background: var(--w11-subtle-hover);
}

.transfer-dialog__folder.is-selected {
  background: color-mix(in srgb, var(--w11-accent) 24%, transparent);
}

.transfer-dialog__folder.is-disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.transfer-dialog__folder:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

.transfer-dialog__actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.transfer-dialog__actions .w11-button:disabled {
  opacity: 0.5;
  cursor: default;
}

.transfer-dialog__actions .w11-button:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 2px;
}

/* ------------------------------------------------------------ Are you sure? */

.confirm-dialog {
  width: min(380px, calc(100vw - 32px));
  padding: 20px 20px 16px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-overlay);
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

.confirm-dialog__title {
  margin: 0 0 8px;
  font-size: 16px;
  font-weight: 600;
}

.confirm-dialog__message {
  margin: 0;
  color: var(--w11-text-2);
  font-size: 13px;
  line-height: 1.45;
}

.confirm-dialog__actions {
  display: flex;
  gap: 8px;
  margin-top: 18px;
}

.confirm-dialog__actions .w11-button:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: no-preference) {
  .desktop-icon,
  .w11-explorer :is(.explorer-grid-item, .w11-details__row) {
    transition: background-color 90ms ease, border-color 90ms ease, opacity 120ms ease;
  }
}

files.src/styles/win11-retro.css:
/* The Retro theme: square corners, bevels and grey, for anyone who misses 1995. */

.os-root.is-retro {
  --w11-radius-control: 0;
  --w11-radius-overlay: 0;
  --retro-face: #c0c0c0;
  --retro-light: #fff;
  --retro-dark: #808080;
}

.os-root.is-retro .w11-taskbar {
  border-top: 2px solid var(--retro-light);
  background: var(--retro-face);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  color: #000;
}

.os-root.is-retro .window-frame {
  border-radius: 0;
  border: 2px solid;
  border-color: var(--retro-light) var(--retro-dark) var(--retro-dark) var(--retro-light);
}

.os-root.is-retro .w11-titlebar {
  background: linear-gradient(90deg, #000080, #1084d0);
  color: #fff;
}

.os-root.is-retro .w11-caption__button {
  margin: 3px 2px;
  border: 1px solid;
  border-color: var(--retro-light) #000 #000 var(--retro-light);
  border-radius: 0;
  background: var(--retro-face);
  color: #000;
}

.os-root.is-retro .w11-start,
.os-root.is-retro .w11-flyout,
.os-root.is-retro .context-menu {
  border-radius: 0;
  border: 2px solid;
  border-color: var(--retro-light) var(--retro-dark) var(--retro-dark) var(--retro-light);
  background: var(--retro-face);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  color: #000;
}

.os-root.is-retro .os-root__wallpaper {
  background: #008080;
}

files.src/styles/win11-session.css:
/* Boot animation and lock screen. Both sit over everything except the skip link. */

.os-session {
  position: fixed;
  inset: 0;
  z-index: 12500;
  color: #fff;
  font-family: var(--w11-font);
}

.os-boot {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 40px;
  height: 100%;
  background: #000;
}

.os-boot__dots {
  display: flex;
  gap: 8px;
}

.os-boot__dots span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #fff;
  opacity: 0.2;
  animation: os-boot-dot 1s ease-in-out infinite;
}

@keyframes os-boot-dot {
  40% {
    opacity: 1;
    transform: translateY(-4px);
  }
}

.os-lock {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: min(11vh, 96px) 16px 56px;
  background: var(--desktop-wallpaper, #050a18);
  cursor: default;
  text-shadow: 0 1px 12px rgb(0 0 0 / 60%);
}

.os-lock::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgb(4 8 20 / 35%);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}

.os-lock > * {
  position: relative;
}

.os-lock__clock {
  text-align: center;
}

.os-lock__clock time {
  display: block;
  font-size: clamp(64px, 12vw, 112px);
  font-weight: 600;
  line-height: 1;
}

.os-lock__clock p {
  margin: 12px 0 0;
  font-size: clamp(18px, 3vw, 24px);
}

.os-lock__account {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.os-lock__avatar {
  display: grid;
  place-items: center;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: rgb(255 255 255 / 16%);
  border: 1px solid rgb(255 255 255 / 30%);
}

.os-lock__account strong {
  font-size: 20px;
  font-weight: 600;
}

.os-lock__account small {
  font-size: 13px;
}

.os-lock__enter {
  min-width: 132px;
  padding: 8px 20px;
  border: 1px solid rgb(255 255 255 / 45%);
  border-radius: var(--w11-radius-control);
  background: rgb(255 255 255 / 16%);
  color: #fff;
  font: inherit;
  cursor: pointer;
}

.os-lock__enter:hover {
  background: rgb(255 255 255 / 26%);
}

.os-lock__portfolio {
  position: absolute;
  right: 20px;
  bottom: 18px;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: #fff;
  font: inherit;
  font-size: 13px;
  text-decoration: underline;
  cursor: pointer;
}

.os-lock button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgb(0 0 0 / 80%);
}

@media (prefers-reduced-motion: reduce) {
  .os-boot__dots span {
    animation: none;
    opacity: 0.7;
  }
}

:root[data-reduce-motion="true"] .os-boot__dots span {
  animation: none;
  opacity: 0.7;
}

:root[data-battery-saver="true"] .os-lock::before {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  background: rgb(4 8 20 / 60%);
}

@media (max-height: 460px) {
  .os-lock {
    padding-top: 20px;
    padding-bottom: 20px;
  }

  .os-lock__avatar {
    display: none;
  }
}

files.src/styles/win11-start.css:
/* Start: pins, recommended and every app in one scrolling page, with the account along the bottom. */

.w11-start {
  width: min(680px, calc(100vw - 24px));
  height: min(760px, calc(100dvh - var(--w11-start-offset) - 24px));
}

.w11-start__top {
  padding: 20px 32px 8px;
}

.w11-start__heading-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 12px 0 8px;
}

.w11-start__heading-row .w11-start__heading {
  margin: 0;
}

.w11-start__more,
.w11-start__back {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: var(--w11-control);
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.w11-start__back {
  margin-bottom: 8px;
  font-weight: 600;
}

.w11-start__more:hover,
.w11-start__back:hover,
.w11-start__row:hover,
.w11-start__account:hover,
.w11-start__folder:hover {
  background: var(--w11-subtle-hover);
}

.w11-start__view {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--w11-text);
  font-size: 12px;
}

.w11-start__view select {
  padding: 4px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.w11-start__view select:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
}

.w11-start__view option {
  background: var(--w11-flyout);
  color: var(--w11-text);
}

.w11-start__folders {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.w11-start__folder {
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--w11-control-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-control);
  cursor: pointer;
}

.w11-start__folder-icons {
  display: grid;
  grid-template-columns: repeat(2, 44px);
  gap: 4px;
}

.w11-start__folder-icons button {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  cursor: pointer;
}

.w11-start__folder-icons button:hover {
  background: var(--w11-subtle-hover);
}

.w11-start__folder-label {
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.w11-start__list {
  display: grid;
  gap: 4px;
}

.w11-start__letter {
  margin: 4px 0;
  padding: 0 8px;
  color: var(--w11-text-2);
  font-size: 12px;
  font-weight: 600;
}

.w11-start__row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 12px;
  padding: 6px 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}

.w11-start__recommended {
  margin-top: 12px;
}

.w11-start__footer {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 32px;
  border-top: 1px solid var(--w11-divider);
  background: var(--w11-subtle-press);
}

.w11-start__account {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  padding: 4px 10px 4px 4px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.w11-start__account > span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-start__footer-actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
}

.w11-start__power-menu {
  top: auto;
  bottom: calc(100% + 4px);
}

@media (max-width: 560px) {
  .w11-start__folders {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .w11-start__footer {
    padding: 8px 16px;
  }
}

files.src/styles/win11-terminal.css:
/*
 * Terminal chrome: the tab strip, new-tab menu, find box, settings and paste
 * prompt around the xterm screens. Windows Terminal's own look.
 *
 * The screens take their colours from the chosen colour scheme (set inline on
 * the app as --terminal-bg / --terminal-fg), so the active tab, which joins
 * the screen in Windows Terminal, can follow the scheme too. Everything else
 * is dark, as app windows are (see .window-frame in win11.css).
 */

.w11-terminal {
  --w11-terminal-strip: #1f1f1f;
  --w11-terminal-surface: #2c2c2c;
  --w11-terminal-field: rgba(255, 255, 255, 0.06);
  --w11-terminal-line: rgba(255, 255, 255, 0.1);
  --w11-terminal-accent: #60cdff;
  --w11-terminal-on-accent: #000000;
  --w11-terminal-danger: #ff99a4;

  position: relative;
  background: var(--w11-terminal-strip);
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 13px;
  color-scheme: dark;
}

.w11-terminal :is(button, input, select):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

/* -------------------------------------------------------------- tab strip */

.w11-terminal__chrome {
  display: flex;
  flex: none;
  align-items: flex-end;
  gap: 2px;
  min-width: 0;
  padding: 6px 8px 0;
  background: var(--w11-terminal-strip);
}

.w11-terminal__tabs {
  display: flex;
  flex: 0 1 auto;
  align-items: flex-end;
  gap: 2px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.w11-terminal__tab {
  display: flex;
  flex: 0 1 200px;
  align-items: center;
  min-width: 96px;
  max-width: 220px;
  height: 34px;
  border-radius: 8px 8px 0 0;
  color: var(--w11-text-2);
}

.w11-terminal__tab:hover {
  background: var(--w11-subtle-hover);
}

.w11-terminal__tab.is-active {
  background: var(--terminal-bg, #0c0c0c);
  color: var(--terminal-fg, #cccccc);
}

.w11-terminal__tab-button {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  height: 100%;
  padding: 0 4px 0 10px;
  border: 0;
  border-radius: 8px 0 0 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: default;
  user-select: none;
}

.w11-terminal__tab-button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: -2px;
}

.w11-terminal__tab-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 16px;
}

.w11-terminal__tab-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-terminal__tab-close,
.w11-terminal__icon-button {
  display: grid;
  flex: none;
  place-items: center;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  cursor: default;
}

.w11-terminal__tab-close {
  width: 24px;
  height: 24px;
  margin-right: 6px;
  opacity: 0.8;
}

.w11-terminal__tab-close:hover,
.w11-terminal__tab-close:focus-visible {
  background: color-mix(in srgb, currentColor 14%, transparent);
  opacity: 1;
}

.w11-terminal__icon-button {
  width: 32px;
  height: 30px;
  margin-bottom: 2px;
  color: var(--w11-text);
}

.w11-terminal__icon-button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.09);
}

.w11-terminal__icon-button[aria-pressed="true"],
.w11-terminal__icon-button[aria-expanded="true"] {
  background: rgba(255, 255, 255, 0.14);
}

.w11-terminal__icon-button:disabled {
  opacity: 0.4;
}

/* The settings button sits at the far end, as in Windows Terminal. */
.w11-terminal__chrome > .w11-terminal__icon-button:last-child {
  margin-left: auto;
}

/* ----------------------------------------------------------------- screens */

.w11-terminal__body {
  background: var(--terminal-bg, #0c0c0c);
}

.terminal-pane {
  display: none;
  min-width: 0;
  min-height: 0;
  flex: 1;
}

.terminal-pane.is-active {
  display: flex;
}

.terminal-pane__screen {
  padding: 8px 4px 4px 12px;
}

/* -------------------------------------------------------------- find box */

.w11-terminal__find {
  position: absolute;
  top: 8px;
  right: 22px;
  z-index: 15;
  display: flex;
  align-items: center;
  gap: 2px;
  max-width: calc(100% - 30px);
  padding: 4px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: 8px;
  background: var(--w11-terminal-surface);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.36);
}

.w11-terminal__find .w11-terminal__icon-button {
  height: 28px;
  margin: 0;
}

.w11-terminal__find-input {
  width: 180px;
  min-width: 0;
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: var(--w11-radius-control);
  background: var(--w11-terminal-field);
  color: inherit;
  font: inherit;
}

.w11-terminal__find-input:focus-visible {
  outline-offset: 0;
}

.w11-terminal__find-status {
  min-width: 64px;
  padding: 0 6px;
  color: var(--w11-text-2);
  font-size: 12px;
  text-align: center;
  white-space: nowrap;
}

.w11-terminal__find-status.is-empty {
  color: var(--w11-terminal-danger);
}

/* ------------------------------------------------------------- menus, notice */

.w11-terminal__menu {
  position: absolute;
  z-index: 40;
  min-width: 224px;
  max-width: calc(100% - 8px);
  padding: 4px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: 8px;
  background: var(--w11-terminal-surface);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.36);
}

.w11-terminal__menu-item {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 32px;
  padding: 0 10px 0 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: default;
}

.w11-terminal__menu-item:hover:not(:disabled),
.w11-terminal__menu-item:focus-visible {
  background: rgba(255, 255, 255, 0.09);
}

.w11-terminal__menu-item:disabled {
  opacity: 0.4;
}

.w11-terminal__menu-icon {
  display: grid;
  place-items: center;
}

.w11-terminal__menu-shortcut {
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-terminal__menu-separator {
  height: 1px;
  margin: 4px 2px;
  background: var(--w11-terminal-line);
}

.w11-terminal__notice {
  position: absolute;
  right: 8px;
  bottom: 8px;
  left: 8px;
  z-index: 10;
  padding: 8px 12px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: 8px;
  background: var(--w11-terminal-surface);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.36);
  font-size: 12px;
}

/* The message area is always in the page so that a screen reader is already watching it; empty, it shows and takes nothing. */
.w11-terminal__notice:empty {
  right: auto;
  left: 0;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: transparent;
  box-shadow: none;
}

/* -------------------------------------------------------------- settings */

.w11-terminal__settings {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  width: min(360px, 100%);
  border-left: 1px solid var(--w11-terminal-line);
  background: var(--w11-terminal-surface);
  box-shadow: -8px 0 16px rgba(0, 0, 0, 0.3);
}

.w11-terminal__settings-header {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  padding: 8px 8px 8px 16px;
  border-bottom: 1px solid var(--w11-terminal-line);
}

.w11-terminal__settings-header h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.w11-terminal__settings-header .w11-terminal__icon-button {
  margin: 0;
}

.w11-terminal__settings-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  padding: 4px 16px 16px;
  overflow-y: auto;
}

.w11-terminal__settings-group {
  margin: 12px 0 0;
  color: var(--w11-text-2);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.w11-terminal__field {
  display: grid;
  gap: 6px;
}

.w11-terminal__field-label {
  font-weight: 600;
}

.w11-terminal__field-hint {
  color: var(--w11-text-2);
  font-size: 12px;
  line-height: 1.4;
}

.w11-terminal__settings select,
.w11-terminal__settings input[type="number"] {
  min-height: 32px;
  padding: 0 8px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: var(--w11-radius-control);
  background: var(--w11-terminal-field);
  color: inherit;
  font: inherit;
}

.w11-terminal__settings select option {
  background: var(--w11-terminal-surface);
  color: var(--w11-text);
}

.w11-terminal__stepper {
  display: flex;
  align-items: center;
  gap: 4px;
}

.w11-terminal__stepper input {
  width: 72px;
  text-align: center;
}

.w11-terminal__stepper .w11-terminal__icon-button {
  width: 32px;
  height: 32px;
  margin: 0;
  background: var(--w11-terminal-field);
}

.w11-terminal__swatch {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: var(--w11-radius-control);
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: 12px;
}

.w11-terminal__swatch i {
  width: 14px;
  height: 14px;
  border-radius: 3px;
}

.w11-terminal__toggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: default;
}

.w11-terminal__toggle input {
  flex: none;
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
  accent-color: var(--w11-terminal-accent);
}

.w11-terminal__toggle-text {
  display: grid;
  gap: 2px;
}

.w11-terminal__shortcuts {
  display: grid;
  gap: 6px;
  margin: 0;
}

.w11-terminal__shortcut {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 2px;
}

.w11-terminal__shortcut dt {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
}

.w11-terminal__shortcut dd {
  margin: 0;
  color: var(--w11-text-2);
}

.w11-terminal__shortcut kbd {
  padding: 1px 6px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: 4px;
  background: var(--w11-terminal-field);
  font: inherit;
  font-size: 12px;
}

.w11-terminal__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 16px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: var(--w11-radius-control);
  background: var(--w11-terminal-field);
  color: inherit;
  font: inherit;
  cursor: default;
}

.w11-terminal__button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.1);
}

.w11-terminal__button:disabled {
  opacity: 0.4;
}

.w11-terminal__button.is-primary {
  border-color: transparent;
  background: var(--w11-terminal-accent);
  color: var(--w11-terminal-on-accent);
}

.w11-terminal__button.is-primary:hover:not(:disabled) {
  background: color-mix(in srgb, var(--w11-terminal-accent) 85%, white);
}

.w11-terminal__settings .w11-terminal__button {
  align-self: flex-start;
  margin-top: 8px;
}

/* ---------------------------------------------------------- paste prompt */

.w11-terminal__scrim {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.5);
}

.w11-terminal__dialog {
  display: grid;
  gap: 10px;
  width: min(440px, 100%);
  padding: 20px;
  border: 1px solid var(--w11-terminal-line);
  border-radius: 8px;
  background: var(--w11-terminal-surface);
  box-shadow: 0 32px 64px rgba(0, 0, 0, 0.37);
}

.w11-terminal__dialog h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
}

.w11-terminal__dialog p {
  margin: 0;
  color: var(--w11-text-2);
}

.w11-terminal__dialog-preview {
  max-height: 7.5em;
  margin: 0;
  padding: 8px 10px;
  overflow: auto;
  border: 1px solid var(--w11-terminal-line);
  border-radius: var(--w11-radius-control);
  background: rgba(0, 0, 0, 0.3);
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
}

.w11-terminal__dialog-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.w11-terminal__dialog-actions .w11-terminal__button {
  flex: 1 1 120px;
}

/* ------------------------------------------------------- touch and narrow */

@media (pointer: coarse) {
  .w11-terminal__icon-button {
    width: 40px;
    height: 36px;
  }

  .w11-terminal__tab {
    height: 38px;
  }

  .w11-terminal__tab-close {
    width: 32px;
    height: 32px;
  }

  .w11-terminal__menu-item {
    height: 42px;
  }
}

@media (max-width: 520px) {
  .w11-terminal__chrome {
    padding: 4px 4px 0;
  }

  .w11-terminal__tab {
    flex-basis: 140px;
    min-width: 80px;
  }

  .w11-terminal__find {
    right: 8px;
    left: 8px;
    max-width: none;
    flex-wrap: wrap;
  }

  .w11-terminal__find-input {
    flex: 1;
    width: auto;
  }

  .w11-terminal__settings {
    width: 100%;
    border-left: 0;
  }

  .terminal-pane__screen {
    padding: 6px 2px 2px 6px;
  }
}

/* Windows high contrast: the tab strip and flyouts lean on colour differences that are not there, so draw them. */
@media (forced-colors: active) {
  .w11-terminal__tab.is-active {
    border-bottom: 3px solid Highlight;
  }

  .w11-terminal__menu,
  .w11-terminal__find,
  .w11-terminal__settings,
  .w11-terminal__dialog,
  .w11-terminal__notice {
    border: 1px solid CanvasText;
  }

  .w11-terminal__menu-item:hover:not(:disabled),
  .w11-terminal__menu-item:focus-visible,
  .w11-terminal__icon-button[aria-pressed="true"] {
    outline: 2px solid Highlight;
  }

  .w11-terminal__button.is-primary {
    border: 2px solid ButtonText;
  }
}

@media (prefers-reduced-motion: reduce) {
  .w11-terminal * {
    scroll-behavior: auto;
    transition: none;
    animation: none;
  }
}

