/*
 * Tray layer: the taskbar's right end, Quick Settings, the clock flyout, the
 * display filters and the Settings sections. Loaded straight after win11.css
 * (see main.tsx) and built on the same --w11-* tokens, so the light and dark
 * Windows modes both work.
 */

/* ------------------------------------------------------------ window layer */

/*
 * Every focus raises a window's z-index by one and nothing ever lowers it, so
 * after enough clicks a window outranked the taskbar (60) and the flyouts (70).
 * Giving the window layer a stacking context of its own keeps all of those
 * numbers inside it: however high they climb, the whole layer stays under the
 * snap ghost (59), the taskbar and every shell flyout.
 */
.window-manager {
  z-index: 40;
}

/* ------------------------------------------------------------- tray glyphs */

.w11-tray-glyph {
  position: relative;
  display: grid;
  flex: none;
  place-items: center;
  width: 16px;
  height: 16px;
}

/* "No internet access": the Wi-Fi glyph with a small warning badge, as in Windows. */
.w11-tray-glyph[data-warning="true"]::after {
  content: "!";
  position: absolute;
  right: -5px;
  bottom: -4px;
  display: grid;
  place-items: center;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--w11-text);
  color: var(--w11-flyout);
  font-size: 8px;
  font-weight: 700;
  line-height: 1;
}

/* Phones keep the quick button; the narrowest ones keep only the network glyph. */
@media (max-width: 700px) {
  .w11-taskbar__quick {
    gap: 8px;
    padding: 0 8px;
  }
}

@media (max-width: 380px) {
  .w11-taskbar__quick .w11-tray-glyph:not([data-tray-glyph="network"]) {
    display: none;
  }
}

/* ----------------------------------------------------------------- slider */

:root {
  --w11-slider-rest: rgba(0, 0, 0, 0.447);
  --w11-slider-ring: #ffffff;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --w11-slider-rest: rgba(255, 255, 255, 0.544);
    --w11-slider-ring: #454545;
  }
}

:root[data-theme="dark"] {
  --w11-slider-rest: rgba(255, 255, 255, 0.544);
  --w11-slider-ring: #454545;
}

/* The WinUI slider: a 4px track filled to the thumb, a 20px thumb with an accent core. */
.w11-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 20px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}

.w11-slider:disabled {
  cursor: default;
  opacity: 0.45;
}

.w11-slider::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 2px;
  background: linear-gradient(
    to right,
    var(--w11-accent) var(--w11-slider-fill, 0%),
    var(--w11-slider-rest) var(--w11-slider-fill, 0%)
  );
}

.w11-slider::-moz-range-track {
  height: 4px;
  border-radius: 2px;
  background: var(--w11-slider-rest);
}

.w11-slider::-moz-range-progress {
  height: 4px;
  border-radius: 2px;
  background: var(--w11-accent);
}

.w11-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  box-sizing: border-box;
  width: 20px;
  height: 20px;
  margin-top: -8px;
  border: 5px solid var(--w11-slider-ring);
  border-radius: 50%;
  background: var(--w11-accent);
  box-shadow: 0 0 0 1px var(--w11-control-stroke-strong);
  transition: border-width 120ms var(--w11-ease-decelerate);
}

.w11-slider::-moz-range-thumb {
  box-sizing: border-box;
  width: 20px;
  height: 20px;
  border: 5px solid var(--w11-slider-ring);
  border-radius: 50%;
  background: var(--w11-accent);
  box-shadow: 0 0 0 1px var(--w11-control-stroke-strong);
}

.w11-slider:hover::-webkit-slider-thumb,
.w11-slider:active::-webkit-slider-thumb {
  border-width: 4px;
}

.w11-slider:focus-visible {
  outline: none;
}

.w11-slider:focus-visible::-webkit-slider-thumb {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 2px;
}

.w11-slider:focus-visible::-moz-range-thumb {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 2px;
}

/* ---------------------------------------------------------- Quick Settings */

.w11-flyout.w11-quick {
  position: fixed;
  z-index: 70;
  right: 12px;
  bottom: var(--w11-start-offset);
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: min(360px, calc(100vw - 24px));
  max-height: calc(100dvh - var(--w11-start-offset) - 12px);
  padding: 16px 16px 0;
  overflow-y: auto;
  font-size: 14px;
  box-shadow: var(--w11-shadow-overlay);
}

.w11-quick__tiles {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.w11-quick__tile {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 4px 8px;
  border: 1px solid var(--w11-control-stroke);
  border-radius: var(--w11-radius-control);
  background: var(--w11-control);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.w11-quick__tile:hover {
  background: var(--w11-control-hover);
}

.w11-quick__tile[aria-pressed="true"] {
  border-color: transparent;
  background: var(--w11-accent);
  color: var(--w11-on-accent);
}

.w11-quick__tile[aria-pressed="true"]:hover {
  opacity: 0.92;
}

.w11-quick__tile-icon {
  display: grid;
  flex: none;
  place-items: center;
}

.w11-quick__tile-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
  font-size: 12px;
  line-height: 16px;
}

.w11-quick__tile-status {
  overflow: hidden;
  opacity: 0.78;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-quick__sliders {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.w11-quick__slider-row {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) 32px;
  align-items: center;
  gap: 8px;
}

.w11-quick__slider-icon,
.w11-quick__slider-button {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
}

.w11-quick__slider-button {
  padding: 0;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.w11-quick__slider-button:hover {
  background: var(--w11-subtle-hover);
}

.w11-quick__slider-button:active {
  background: var(--w11-subtle-press);
}

.w11-quick__slider-value {
  color: var(--w11-text-2);
  font-size: 12px;
  text-align: center;
}

.w11-quick__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 -16px;
  padding: 12px 16px;
  border-top: 1px solid var(--w11-divider);
  background: var(--w11-subtle-hover);
}

.w11-quick__footer > .w11-quick__slider-button {
  margin-left: auto;
}

.w11-quick__battery {
  display: flex;
  align-items: center;
  gap: 10px;
  line-height: 18px;
}

.w11-quick__battery small {
  display: block;
  color: var(--w11-text-2);
  font-size: 12px;
  line-height: 16px;
}

/* ------------------------------------------------------------ clock flyout */

.w11-flyout.w11-clock {
  position: fixed;
  z-index: 70;
  right: 12px;
  bottom: var(--w11-start-offset);
  display: flex;
  flex-direction: column;
  width: min(360px, calc(100vw - 24px));
  max-height: calc(100dvh - var(--w11-start-offset) - 12px);
  padding: 0;
  overflow-y: auto;
  font-size: 14px;
  box-shadow: var(--w11-shadow-overlay);
}

.w11-clock__header {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--w11-divider);
}

.w11-clock__time {
  font-size: 34px;
  font-variant-numeric: tabular-nums;
  font-weight: 300;
  line-height: 1.15;
}

.w11-clock__date {
  color: var(--w11-text-2);
}

.w11-clock__calendar {
  padding: 12px 16px 8px;
}

.w11-clock__nav {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 0 8px 8px;
}

.w11-clock__month {
  flex: 1;
  min-width: 0;
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.w11-clock__step,
.w11-clock__today {
  display: grid;
  flex: none;
  place-items: center;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.w11-clock__step {
  width: 32px;
}

.w11-clock__today {
  padding: 0 10px;
}

.w11-clock__step:hover,
.w11-clock__today:hover {
  background: var(--w11-subtle-hover);
}

.w11-clock__step:active,
.w11-clock__today:active {
  background: var(--w11-subtle-press);
}

.w11-clock__grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  text-align: center;
}

.w11-clock__grid th {
  padding: 6px 0;
  color: var(--w11-text-2);
  font-size: 12px;
  font-weight: 400;
}

.w11-clock__grid td {
  padding: 1px;
}

.w11-clock__day {
  display: grid;
  place-items: center;
  width: min(40px, 100%);
  aspect-ratio: 1;
  margin: 0 auto;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.w11-clock__day:hover {
  background: var(--w11-subtle-hover);
}

.w11-clock__day.is-outside {
  color: var(--w11-text-2);
  opacity: 0.65;
}

.w11-clock__day.is-selected {
  border-color: var(--w11-accent);
}

.w11-clock__day.is-today {
  background: var(--w11-accent);
  color: var(--w11-on-accent);
  font-weight: 600;
  opacity: 1;
}

.w11-clock__day.is-today:hover {
  opacity: 0.92;
}

.w11-clock__footer {
  padding: 4px 8px 8px;
  border-top: 1px solid var(--w11-divider);
}

.w11-clock__settings {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}

.w11-clock__settings:hover {
  background: var(--w11-subtle-hover);
}

/* --------------------------------------------------------- display filters */

/* The layers are positioned inline; this only eases a slider drag into the change. */
.w11-display-filter {
  transition: background-color 120ms linear;
}

/* ------------------------------------------------------ reduce motion */

/*
 * Settings > Accessibility > Animation effects, or the Quick Settings tile.
 * Mirrors the prefers-reduced-motion rule in global.css for the CSS side;
 * framer-motion is switched by MotionPreferences at the app root.
 */
:root[data-reduce-motion] *,
:root[data-reduce-motion] *::before,
:root[data-reduce-motion] *::after {
  scroll-behavior: auto !important;
  animation-duration: 0.01ms !important;
  animation-delay: 0s !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  transition-delay: 0s !important;
}

/* ------------------------------------------------------------ battery saver */

/*
 * Battery saver trades looks for power, as Windows does: the screen is dimmed
 * (see display-filter), the wallpaper stops moving (desktop-shell), and the
 * blur behind every translucent surface is dropped. Surfaces turn opaque so
 * text stays readable without it.
 */
:root[data-battery-saver] *,
:root[data-transparency="off"] * {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

:root[data-battery-saver],
:root[data-transparency="off"] {
  --w11-acrylic: rgb(238, 238, 238);
  --w11-flyout: rgb(252, 252, 252);
  --w11-taskbar: rgb(238, 238, 238);
}

@media (prefers-color-scheme: dark) {
  :root[data-battery-saver]:not([data-theme="light"]),
  :root[data-transparency="off"]:not([data-theme="light"]) {
    --w11-acrylic: rgb(36, 36, 36);
    --w11-flyout: rgb(44, 44, 44);
    --w11-taskbar: rgb(28, 28, 28);
  }
}

:root[data-battery-saver][data-theme="dark"],
:root[data-transparency="off"][data-theme="dark"] {
  --w11-acrylic: rgb(36, 36, 36);
  --w11-flyout: rgb(44, 44, 44);
  --w11-taskbar: rgb(28, 28, 28);
}

/* Settings > Personalization > Transparency effects off: the same solid surfaces battery saver uses. */

/* ---------------------------------------------------------------- Settings */

/*
 * App mode is dark-only (see the .window-frame note in win11.css), so Settings
 * pins the dark control tokens instead of following the shell theme.
 */
.w11-settings {
  --w11-accent: #60cdff;
  --w11-on-accent: #000000;
  --w11-control-stroke-strong: rgba(255, 255, 255, 0.544);
  --w11-slider-rest: rgba(255, 255, 255, 0.544);
  --w11-slider-ring: #454545;
  --w11-settings-card: rgba(255, 255, 255, 0.0512);
  --w11-settings-card-hover: rgba(255, 255, 255, 0.0838);
  --w11-settings-card-stroke: rgba(255, 255, 255, 0.058);

  background: #202020;
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 14px;
}

.w11-settings :is(button, input):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

.w11-settings__layout {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

.w11-settings__nav {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: 4px;
  width: 224px;
  padding: 8px 6px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.w11-settings__profile {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 10px 14px;
}

.w11-settings__profile-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
  line-height: 1.3;
}

.w11-settings__profile-text strong {
  overflow: hidden;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-settings__profile-text small {
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-settings__nav-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.w11-settings__nav-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 40px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.w11-settings__nav-item:hover {
  background: var(--w11-subtle-hover);
}

.w11-settings__nav-item.is-active {
  background: rgba(255, 255, 255, 0.0605);
}

/* The accent pill on the current page, as in Windows. */
.w11-settings__nav-item.is-active::before {
  content: "";
  position: absolute;
  top: 11px;
  bottom: 11px;
  left: 0;
  width: 3px;
  border-radius: 2px;
  background: var(--w11-accent);
}

.w11-settings__page.app-content {
  flex: 1;
  gap: 24px;
  min-width: 0;
  padding: 8px 32px 32px 24px;
}

.w11-settings__title {
  margin: 8px 0 0;
  font-size: 28px;
  font-weight: 600;
  line-height: 1.25;
}

.w11-settings__section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.w11-settings__group-title {
  margin: 0;
  padding: 0 2px;
  font-size: 14px;
  font-weight: 600;
}

.w11-settings__group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.w11-settings__row {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  min-height: 64px;
  padding: 12px 16px;
  border: 1px solid var(--w11-settings-card-stroke);
  border-radius: var(--w11-radius-control);
  background: var(--w11-settings-card);
  color: inherit;
  font: inherit;
  text-align: left;
}

.w11-settings__row.is-nested {
  padding-left: 50px;
}

.w11-settings__row--link {
  cursor: pointer;
}

.w11-settings__row--link:hover {
  background: var(--w11-settings-card-hover);
}

.w11-settings__row-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 20px;
}

.w11-settings__row-text {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.w11-settings__row-description {
  color: var(--w11-text-2);
  font-size: 12px;
  line-height: 1.4;
}

.w11-settings__row-control {
  display: flex;
  flex: none;
  align-items: center;
  gap: 12px;
}

.w11-settings__row-chevron {
  flex: none;
  color: var(--w11-text-2);
}

.w11-settings__slider {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 240px;
}

.w11-settings__slider-value {
  min-width: 28px;
  color: var(--w11-text-2);
  font-size: 12px;
  text-align: right;
}

.w11-settings__note {
  max-width: 560px;
  margin: 0;
  color: var(--w11-text-2);
  font-size: 12px;
  line-height: 1.5;
}

/* On / off switch. */
.w11-switch-wrap {
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.w11-switch__state {
  min-width: 24px;
  text-align: right;
}

.w11-switch {
  position: relative;
  flex: none;
  width: 40px;
  height: 20px;
  padding: 0;
  border: 1px solid var(--w11-control-stroke-strong);
  border-radius: 10px;
  background: transparent;
  cursor: pointer;
  transition: background-color 167ms linear, border-color 167ms linear;
}

.w11-switch__thumb {
  position: absolute;
  top: 50%;
  left: 4px;
  width: 12px;
  height: 12px;
  margin-top: -6px;
  border-radius: 50%;
  background: var(--w11-text-2);
  transition: left 167ms var(--w11-ease-decelerate), width 167ms var(--w11-ease-decelerate),
    margin-top 167ms var(--w11-ease-decelerate);
}

.w11-switch:hover .w11-switch__thumb {
  width: 14px;
  margin-top: -7px;
}

.w11-switch[aria-checked="true"] {
  border-color: transparent;
  background: var(--w11-accent);
}

.w11-switch[aria-checked="true"] .w11-switch__thumb {
  left: 22px;
  background: var(--w11-on-accent);
}

.w11-switch:disabled {
  cursor: default;
  opacity: 0.4;
}

.w11-switch:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 2px;
}

/* Phones: the pages become a strip along the top and rows stack their controls. */
@media (max-width: 520px) {
  .w11-settings__layout {
    flex-direction: column;
  }

  .w11-settings__nav {
    width: auto;
    padding: 4px 8px;
    overflow: auto hidden;
  }

  .w11-settings__profile {
    display: none;
  }

  .w11-settings__nav-list {
    flex-direction: row;
    gap: 4px;
  }

  .w11-settings__nav-item {
    width: auto;
    height: 36px;
    white-space: nowrap;
  }

  .w11-settings__nav-item.is-active::before {
    top: auto;
    right: 12px;
    bottom: 2px;
    left: 12px;
    width: auto;
    height: 3px;
  }

  .w11-settings__page.app-content {
    gap: 16px;
    padding: 4px 16px 24px;
  }

  .w11-settings__title {
    font-size: 24px;
  }

  .w11-settings__row {
    flex-wrap: wrap;
    gap: 12px;
  }

  .w11-settings__row.is-nested {
    padding-left: 16px;
  }

  .w11-settings__row-control {
    flex: 1 1 100%;
    justify-content: flex-end;
  }

  .w11-settings__slider {
    width: 100%;
  }
}

/* Settings search, accent swatches, meters and key caps. */
.w11-settings__search {
  flex: none;
  min-width: 0;
  min-height: 32px;
  margin: 0 4px 10px;
  border-color: var(--w11-settings-card-stroke);
  border-radius: var(--w11-radius-control);
  background: var(--w11-settings-card);
}

.w11-settings__search:focus-within {
  border-color: var(--w11-accent);
}

.w11-settings .search-input__field:focus-visible {
  outline: none;
}

/* WinUI combo box: a dark control with a light border, in place of the browser's white select. */
.w11-settings select {
  min-width: 140px;
  height: 32px;
  padding: 0 8px;
  border: 1px solid var(--w11-settings-card-stroke);
  border-bottom-color: rgba(255, 255, 255, 0.4);
  border-radius: var(--w11-radius-control);
  background-color: var(--w11-settings-card-hover);
  color: #fff;
  color-scheme: dark;
  font: inherit;
  cursor: pointer;
}

.w11-settings select:hover:not(:disabled) {
  background-color: rgba(255, 255, 255, 0.11);
}

.w11-settings select:disabled {
  cursor: default;
  opacity: 0.4;
}

.w11-settings__search-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 4px 0 6px;
}

.w11-settings__search-row .search-input {
  flex: 1;
}

.w11-settings__count {
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-settings__row.is-found {
  animation: w11-settings-found 2s ease-out;
}

@keyframes w11-settings-found {
  0%,
  60% {
    box-shadow: inset 0 0 0 2px var(--w11-accent);
  }

  100% {
    box-shadow: inset 0 0 0 2px transparent;
  }
}

.w11-settings__swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.w11-settings__swatch {
  width: 24px;
  height: 24px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  cursor: pointer;
}

.w11-settings__swatch[aria-checked="true"] {
  border-color: var(--w11-text);
  box-shadow: inset 0 0 0 2px #202020;
}

.w11-settings__meter {
  display: block;
  width: 160px;
  height: 6px;
  overflow: hidden;
  border-radius: 3px;
  background: var(--w11-settings-card-hover);
}

.w11-settings__meter > span {
  display: block;
  height: 100%;
  background: var(--w11-accent);
}

.w11-settings__figure {
  color: var(--w11-text-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.w11-settings__keys {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .w11-settings__row.is-found {
    animation: none;
    box-shadow: inset 0 0 0 2px var(--w11-accent);
  }
}

@media (max-width: 520px) {
  .w11-settings__nav {
    flex-direction: row;
    align-items: center;
  }

  .w11-settings__search {
    flex: none;
    width: 150px;
    margin: 0 4px 0 0;
  }

  .w11-settings__meter {
    width: 100%;
  }
}

/* Events on the day shown in the clock flyout. */
.w11-clock__events {
  display: grid;
  gap: 4px;
  padding: 8px 16px;
  border-top: 1px solid var(--w11-divider);
  font-size: 12px;
}

.w11-clock__events ul {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.w11-clock__events li {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
  gap: 8px;
}

.w11-clock__events li span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-clock__events small {
  color: var(--w11-text-2);
  font-size: 12px;
}

