/* Snap Layouts and Task View. */

.w11-snap {
  position: fixed;
  z-index: 80;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 12px;
}

.w11-snap__layout {
  position: relative;
  aspect-ratio: 16 / 10;
}

.w11-snap__zone {
  position: absolute;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 5px;
  background-clip: padding-box;
  background-color: var(--w11-text-2);
  opacity: 0.45;
  cursor: pointer;
}

.w11-snap__zone:hover,
.w11-snap__zone:focus-visible {
  background-color: var(--w11-accent);
  opacity: 1;
}

.w11-taskview {
  position: fixed;
  bottom: var(--w11-start-offset);
  left: 50%;
  z-index: 72;
  display: flex;
  gap: 10px;
  max-width: calc(100vw - 24px);
  padding: 12px;
  overflow-x: auto;
  transform: translateX(-50%);
}

.w11-taskview__desktop {
  position: relative;
  flex: none;
  width: 168px;
}

.w11-taskview__card {
  display: grid;
  gap: 10px;
  width: 100%;
  height: 100%;
  min-height: 92px;
  padding: 10px;
  border: 2px solid var(--w11-divider);
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}

.w11-taskview__card:hover {
  border-color: var(--w11-text-2);
}

.w11-taskview__desktop.is-active .w11-taskview__card {
  border-color: var(--w11-accent);
}

.w11-taskview__windows {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
}

.w11-taskview__windows small {
  color: var(--w11-text-2);
}

.w11-taskview__remove {
  position: absolute;
  top: 6px;
  right: 6px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--w11-text);
  cursor: pointer;
}

.w11-taskview__remove:hover {
  background: var(--w11-divider);
}

.w11-taskview__add {
  display: grid;
  flex: none;
  place-items: center;
  align-content: center;
  gap: 6px;
  width: 96px;
  border: 2px dashed var(--w11-divider);
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

@media (max-width: 700px) {
  .w11-taskbar__taskview {
    display: none;
  }
}

