/*
 * Windows 11 design layer.
 *
 * Loaded last (see main.tsx), so these rules win over global.css and
 * visual-redesign.css without needing !important. Shell chrome that has been
 * rebuilt for Windows 11 uses `w11-*` class names, so none of the older
 * cascade applies to it at all.
 *
 * Theme follows the operating system (prefers-color-scheme), the way Windows
 * apps do. Setting <html data-theme="light"> or "dark" overrides it.
 */

/* ------------------------------------------------------------------ tokens */

:root {
  --w11-font: "Segoe UI Variable Text", "Segoe UI Variable", "Segoe UI", system-ui, -apple-system,
    "Helvetica Neue", Arial, sans-serif;
  --w11-radius-overlay: 8px;
  --w11-radius-control: 4px;
  --w11-ease-decelerate: cubic-bezier(0, 0, 0, 1);

  /* Start floats 12px above the taskbar, as in Windows. */
  --w11-start-offset: calc(var(--w11-taskbar-height) + 12px);

  /* Light theme (default). Values follow the WinUI 3 light resource set. */
  --w11-acrylic: rgba(238, 238, 238, 0.84);
  --w11-flyout: rgba(252, 252, 252, 0.96);
  --w11-text: rgba(0, 0, 0, 0.896);
  --w11-text-2: rgba(0, 0, 0, 0.606);
  --w11-subtle-hover: rgba(0, 0, 0, 0.037);
  --w11-subtle-press: rgba(0, 0, 0, 0.024);
  --w11-control: rgba(255, 255, 255, 0.7);
  --w11-control-hover: rgba(249, 249, 249, 0.5);
  --w11-control-stroke: rgba(0, 0, 0, 0.058);
  --w11-control-stroke-strong: rgba(0, 0, 0, 0.162);
  --w11-surface-stroke: rgba(117, 117, 117, 0.4);
  --w11-divider: rgba(0, 0, 0, 0.08);
  --w11-accent: #005fb8;
  --w11-on-accent: #ffffff;
  --w11-shadow-flyout: 0 8px 16px rgba(0, 0, 0, 0.14);
  --w11-shadow-overlay: 0 32px 64px rgba(0, 0, 0, 0.19), 0 2px 21px rgba(0, 0, 0, 0.15);
  --w11-focus-outer: rgba(0, 0, 0, 0.896);
  --w11-focus-inner: #ffffff;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --w11-acrylic: rgba(36, 36, 36, 0.86);
    --w11-flyout: rgba(44, 44, 44, 0.96);
    --w11-text: #ffffff;
    --w11-text-2: rgba(255, 255, 255, 0.786);
    --w11-subtle-hover: rgba(255, 255, 255, 0.061);
    --w11-subtle-press: rgba(255, 255, 255, 0.042);
    --w11-control: rgba(255, 255, 255, 0.061);
    --w11-control-hover: rgba(255, 255, 255, 0.084);
    --w11-control-stroke: rgba(255, 255, 255, 0.07);
    --w11-control-stroke-strong: rgba(255, 255, 255, 0.544);
    --w11-surface-stroke: rgba(0, 0, 0, 0.36);
    --w11-divider: rgba(255, 255, 255, 0.084);
    --w11-accent: #60cdff;
    --w11-on-accent: #000000;
    --w11-shadow-flyout: 0 8px 16px rgba(0, 0, 0, 0.26);
    --w11-shadow-overlay: 0 32px 64px rgba(0, 0, 0, 0.37), 0 2px 21px rgba(0, 0, 0, 0.37);
    --w11-focus-outer: #ffffff;
    --w11-focus-inner: rgba(0, 0, 0, 0.7);
  }
}

:root[data-theme="dark"] {
  --w11-acrylic: rgba(36, 36, 36, 0.86);
  --w11-flyout: rgba(44, 44, 44, 0.96);
  --w11-text: #ffffff;
  --w11-text-2: rgba(255, 255, 255, 0.786);
  --w11-subtle-hover: rgba(255, 255, 255, 0.061);
  --w11-subtle-press: rgba(255, 255, 255, 0.042);
  --w11-control: rgba(255, 255, 255, 0.061);
  --w11-control-hover: rgba(255, 255, 255, 0.084);
  --w11-control-stroke: rgba(255, 255, 255, 0.07);
  --w11-control-stroke-strong: rgba(255, 255, 255, 0.544);
  --w11-surface-stroke: rgba(0, 0, 0, 0.36);
  --w11-divider: rgba(255, 255, 255, 0.084);
  --w11-accent: #60cdff;
  --w11-on-accent: #000000;
  --w11-shadow-flyout: 0 8px 16px rgba(0, 0, 0, 0.26);
  --w11-shadow-overlay: 0 32px 64px rgba(0, 0, 0, 0.37), 0 2px 21px rgba(0, 0, 0, 0.37);
  --w11-focus-outer: #ffffff;
  --w11-focus-inner: rgba(0, 0, 0, 0.7);
}

/* -------------------------------------------------------- shared controls */

.w11-start :is(button, input):focus-visible,
.w11-flyout :is(button, input):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: 0;
  box-shadow: inset 0 0 0 1px var(--w11-focus-inner);
}

.w11-flyout {
  padding: 4px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-flyout);
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

.w11-flyout__item {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  column-gap: 12px;
  align-items: center;
  width: 100%;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}

.w11-flyout__item svg {
  grid-row: span 2;
}

.w11-flyout__item small {
  grid-column: 2;
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-flyout__item:hover {
  background: var(--w11-subtle-hover);
}

.w11-flyout__item:active {
  background: var(--w11-subtle-press);
}

.w11-flyout__text {
  margin: 8px 12px 12px;
  color: var(--w11-text-2);
  font-size: 13px;
  line-height: 1.45;
}

.w11-flyout__actions {
  display: flex;
  gap: 8px;
  padding: 0 8px 8px;
}

.w11-button {
  flex: 1;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--w11-control-stroke);
  border-radius: var(--w11-radius-control);
  background: var(--w11-control);
  color: var(--w11-text);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.w11-button:hover {
  background: var(--w11-control-hover);
}

.w11-button--accent {
  border-color: transparent;
  background: var(--w11-accent);
  color: var(--w11-on-accent);
}

.w11-button--accent:hover {
  background: var(--w11-accent);
  opacity: 0.9;
}

/* -------------------------------------------------------------- Start menu */

.w11-start {
  position: fixed;
  z-index: 70;
  right: 0;
  bottom: var(--w11-start-offset);
  left: 0;
  display: flex;
  flex-direction: column;
  width: min(640px, calc(100vw - 24px));
  max-height: calc(100dvh - var(--w11-start-offset) - 24px);
  margin-inline: auto;
  overflow: hidden;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-acrylic);
  box-shadow: var(--w11-shadow-overlay);
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 14px;
}

.w11-start__top {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 24px 32px 12px;
}

.w11-start__search {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 10px;
  min-width: 0;
  height: 36px;
  padding: 0 14px;
  border: 1px solid var(--w11-control-stroke);
  border-bottom-color: var(--w11-control-stroke-strong);
  border-radius: 18px;
  background: var(--w11-control);
  color: var(--w11-text-2);
}

.w11-start__search:focus-within {
  border-color: var(--w11-accent);
}

.w11-start__search input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 14px;
}

.w11-start__search input::placeholder {
  color: var(--w11-text-2);
}

.w11-start__search input:focus-visible {
  outline: none;
  box-shadow: none;
}

.w11-start__avatar {
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: var(--w11-accent);
  color: var(--w11-on-accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.w11-start__power-wrap {
  position: relative;
  flex: none;
}

.w11-start__icon-button {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  cursor: pointer;
}

.w11-start__icon-button:hover,
.w11-start__icon-button[aria-expanded="true"] {
  background: var(--w11-subtle-hover);
}

.w11-start__power-menu {
  position: absolute;
  z-index: 2;
  top: calc(100% + 4px);
  right: 0;
  width: 248px;
}

.w11-start__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 8px 32px 24px;
  scrollbar-width: thin;
}

.w11-start__heading {
  margin: 4px 0 8px;
  padding: 0 8px;
  color: var(--w11-text);
  font-size: 14px;
  font-weight: 600;
}

.w11-start__grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 4px;
}

.w11-start__tile {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 12px 4px 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.w11-start__tile span {
  display: -webkit-box;
  max-width: 100%;
  overflow: hidden;
  line-height: 16px;
  text-align: center;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.w11-start__tile:hover,
.w11-start__rec-item:hover {
  background: var(--w11-subtle-hover);
}

.w11-start__tile:active,
.w11-start__rec-item:active {
  background: var(--w11-subtle-press);
}

.w11-start__divider {
  height: 1px;
  margin: 12px 8px;
  border: 0;
  background: var(--w11-divider);
}

.w11-start__recommended {
  margin-top: 20px;
}

.w11-start__rec-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
}

.w11-start__rec-item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.w11-start__rec-item svg {
  flex: none;
}

.w11-start__rec-item > span {
  min-width: 0;
}

.w11-start__rec-item strong,
.w11-start__rec-item small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-start__rec-item strong {
  font-size: 13px;
  font-weight: 400;
}

.w11-start__rec-item small {
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-start__results {
  min-height: 320px;
}

@media (max-width: 560px) {
  .w11-start__top {
    padding: 16px 16px 8px;
  }

  .w11-start__body {
    padding: 8px 16px 16px;
  }

  .w11-start__grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .w11-start__rec-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ------------------------------------------------------------- app windows */

/*
 * App mode. Windows 11 lets the shell ("Windows mode") and apps ("App mode")
 * use different themes - Settings > Personalization > Colors > Custom. App
 * interiors here are dark-only, so app windows pin the dark token set while
 * Start, the taskbar and flyouts follow the OS theme.
 */
.window-frame {
  --w11-text: #ffffff;
  --w11-text-2: rgba(255, 255, 255, 0.786);
  --w11-subtle-hover: rgba(255, 255, 255, 0.061);
  --w11-subtle-press: rgba(255, 255, 255, 0.042);
  --w11-focus-outer: #ffffff;
  --w11-focus-inner: rgba(0, 0, 0, 0.7);

  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--w11-radius-overlay);
  background: #202020;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.26);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.window-frame.is-active,
.window-frame.is-dragging {
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 32px 64px rgba(0, 0, 0, 0.37), 0 2px 21px rgba(0, 0, 0, 0.37);
}

.window-frame:not(.is-active) {
  opacity: 1;
}

.window-frame.is-maximized {
  border-color: transparent;
  border-radius: 0;
  box-shadow: none;
}

.w11-titlebar.window-frame__header {
  height: 32px;
  gap: 12px;
  padding: 0 0 0 12px;
  border-bottom: 0;
  background: transparent;
  cursor: default;
}

.w11-titlebar__title {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 12px;
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 12px;
}

.w11-titlebar__title svg {
  flex: none;
}

.w11-titlebar__title strong {
  overflow: hidden;
  font-weight: 400;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-caption {
  display: flex;
  flex: none;
  align-self: stretch;
}

.w11-caption__button {
  display: grid;
  width: 46px;
  height: 100%;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--w11-text);
  cursor: default;
}

.w11-caption__button:hover {
  background: var(--w11-subtle-hover);
}

.w11-caption__button:active {
  background: var(--w11-subtle-press);
  color: var(--w11-text-2);
}

.w11-caption__button--close:hover {
  background: #c42b1c;
  color: #ffffff;
}

.w11-caption__button--close:active {
  background: rgba(196, 43, 28, 0.9);
  color: rgba(255, 255, 255, 0.7);
}

.w11-caption__button:focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

/* Inactive windows: title and glyphs dim, as in Windows. */
.window-frame:not(.is-active) .w11-titlebar__title,
.window-frame:not(.is-active) .w11-caption__button:not(:hover) {
  color: var(--w11-text-2);
}

/* ------------------------------------------------------------------ desktop */

/*
 * The desktop root must never scroll. `overflow: hidden` only hides the
 * scrollbar - focus() and scrollIntoView() can still shift it, which slides
 * every window sideways (seen after a viewport resize left scrollLeft at 24px).
 * `clip` makes it unscrollable, programmatically too.
 */
.os-root {
  overflow: clip;
}

/* ----------------------------------------------------------------- taskbar */

:root {
  --w11-taskbar-height: 48px;
  --w11-taskbar: rgba(238, 238, 238, 0.85);
  --w11-taskbar-stroke: rgba(0, 0, 0, 0.08);
  --w11-indicator-open: rgba(0, 0, 0, 0.45);
  --w11-start-logo: #0067c0;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --w11-taskbar: rgba(28, 28, 28, 0.85);
    --w11-taskbar-stroke: rgba(255, 255, 255, 0.08);
    --w11-indicator-open: rgba(255, 255, 255, 0.54);
    --w11-start-logo: #4cc2ff;
  }
}

:root[data-theme="dark"] {
  --w11-taskbar: rgba(28, 28, 28, 0.85);
  --w11-taskbar-stroke: rgba(255, 255, 255, 0.08);
  --w11-indicator-open: rgba(255, 255, 255, 0.54);
  --w11-start-logo: #4cc2ff;
}

/* Overrides the floating-pill .taskbar rules in global.css / visual-redesign.css. */
.taskbar.w11-taskbar {
  position: fixed;
  z-index: 60;
  top: auto;
  right: 0;
  bottom: 0;
  left: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-rows: none;
  align-items: center;
  gap: 0;
  width: auto;
  max-width: none;
  height: var(--w11-taskbar-height);
  margin: 0;
  padding: 0;
  transform: none;
  border: 0;
  border-top: 1px solid var(--w11-taskbar-stroke);
  border-radius: 0;
  background: var(--w11-taskbar);
  box-shadow: none;
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

.w11-taskbar__center {
  display: flex;
  min-width: 0;
  grid-column: 2;
  align-items: center;
  justify-self: center;
  gap: 4px;
  height: 100%;
}

.w11-taskbar__apps {
  display: flex;
  min-width: 0;
  max-width: 60vw;
  align-items: center;
  gap: 4px;
  overflow-x: auto;
  scrollbar-width: none;
}

.w11-taskbar__apps::-webkit-scrollbar {
  display: none;
}

.w11-taskbar__start,
.w11-taskbar__app {
  position: relative;
  display: grid;
  flex: none;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  cursor: default;
  transition: background-color 83ms linear;
}

.w11-taskbar__start svg,
.w11-taskbar__app svg {
  transition: transform 120ms var(--w11-ease-decelerate);
}

.w11-taskbar__start:hover,
.w11-taskbar__app:hover,
.w11-taskbar__tray-button:hover,
.w11-taskbar__show-desktop:hover {
  background: var(--w11-subtle-hover);
}

/* Windows shrinks a taskbar icon slightly while it is pressed. */
.w11-taskbar__start:active svg,
.w11-taskbar__app:active svg {
  transform: scale(0.86);
}

.w11-taskbar__start.is-active,
.w11-taskbar__app.is-active,
.w11-taskbar__tray-button.is-active {
  border-color: var(--w11-control-stroke);
  background: var(--w11-control);
}

/* Running-app indicator: short grey pill when open, long accent pill when focused. */
.w11-taskbar__indicator {
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 6px;
  height: 3px;
  border-radius: 2px;
  background: var(--w11-indicator-open);
  transform: translateX(-50%);
  transition: width 167ms var(--w11-ease-decelerate), background-color 167ms linear;
}

.w11-taskbar__app.is-active .w11-taskbar__indicator {
  width: 16px;
  background: var(--w11-accent);
}

/* Search pill. Overrides the generic .search-input control from app-layout. */
.w11-taskbar__search.search-input {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  width: 216px;
  min-width: 0;
  max-width: none;
  height: 32px;
  min-height: 0;
  margin: 0 4px;
  padding: 0 12px;
  border: 1px solid var(--w11-control-stroke);
  border-radius: 16px;
  background: var(--w11-control);
  box-shadow: none;
  color: var(--w11-text-2);
}

.w11-taskbar__search.search-input:hover {
  background: var(--w11-control-hover);
}

.w11-taskbar__search.search-input:focus-within {
  border-color: var(--w11-accent);
}

.w11-taskbar__search .search-input__icon {
  display: grid;
  color: inherit;
}

.w11-taskbar__search .search-input__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  color: var(--w11-text);
  font: inherit;
  font-size: 14px;
}

.w11-taskbar__search .search-input__field::placeholder {
  color: var(--w11-text-2);
}

.w11-taskbar__search .search-input__field:focus,
.w11-taskbar__search .search-input__field:focus-visible {
  outline: none;
  box-shadow: none;
}

/* System tray. */
.w11-taskbar__tray {
  display: flex;
  grid-column: 3;
  align-items: center;
  justify-self: end;
  gap: 2px;
  height: 100%;
}

.w11-taskbar__tray-button {
  display: flex;
  align-items: center;
  height: 40px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  cursor: default;
}

.w11-taskbar__quick {
  gap: 10px;
  padding: 0 10px;
}

.w11-taskbar__clock {
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  font-size: 12px;
  line-height: 16px;
  text-align: right;
  white-space: nowrap;
}

/* The sliver at the far right edge that shows the desktop. */
.w11-taskbar__show-desktop {
  align-self: stretch;
  width: 12px;
  margin-left: 4px;
  padding: 0;
  border: 0;
  border-left: 1px solid var(--w11-divider);
  background: transparent;
  cursor: default;
}

.w11-taskbar :is(button, input):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

@media (max-width: 700px) {
  .taskbar.w11-taskbar {
    grid-template-columns: 0 minmax(0, 1fr) auto;
  }

  .w11-taskbar__search.search-input {
    display: none;
  }

  /* Fill the column, so a long row of apps scrolls here instead of sliding under the tray. */
  .w11-taskbar__center {
    justify-self: stretch;
  }

  .w11-taskbar__apps {
    max-width: none;
    flex: 1;
  }
}

/* The sci-fi layers over the wallpaper (screen-blend glow, dot grid, noise)
   have no Windows equivalent: the wallpaper is shown as-is. */
.os-root__wallpaper::before,
.os-root__wallpaper::after,
.os-root__noise,
.desktop-surface__overlay {
  display: none;
}

/* ---------------------------------------------------------------- terminal */

/* The terminal's chrome, colour scheme and inset padding live in win11-terminal.css. */

/* ------------------------------------------- taskbar thumbnail + jump list */

/* Overrides the dark .taskbar__preview / .taskbar__jump-list cards in global.css. */
.taskbar__preview.w11-thumb,
.taskbar__jump-list.w11-jump {
  position: fixed;
  z-index: 75;
  padding: 4px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-flyout);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

.w11-thumb__header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px 8px;
  font-size: 12px;
}

.w11-thumb__header span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-thumb__frame {
  display: grid;
  height: 136px;
  place-items: center;
  overflow: hidden;
  border-radius: var(--w11-radius-control);
  background: var(--w11-subtle-hover);
}

.w11-thumb__frame img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.w11-jump {
  min-width: 240px;
}

.w11-jump .taskbar__jump-list-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border: 0;
  background: transparent;
}

.w11-jump .taskbar__jump-list-icon {
  display: grid;
  width: auto;
  height: auto;
  border: 0;
  background: transparent;
}

.w11-jump .taskbar__jump-list-title {
  font-size: 14px;
  font-weight: 600;
}

.w11-jump .taskbar__jump-list-item,
.w11-jump .taskbar__jump-list-item.is-danger {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 36px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 14px;
  text-align: left;
}

.w11-jump .taskbar__jump-list-item:hover {
  background: var(--w11-subtle-hover);
}

.w11-jump .taskbar__jump-list-divider {
  height: 1px;
  margin: 4px 0;
  background: var(--w11-divider);
}

/* Start carries the portfolio's own TV monogram, in the accent colour. */
.w11-taskbar__start svg {
  color: var(--w11-start-logo);
}

/* ------------------------------------------------------------ context menu */

/* Shell surface, so it follows Windows mode (light or dark), like Start. */
.context-menu {
  min-width: 220px;
  padding: 4px;
  border: 1px solid var(--w11-surface-stroke);
  border-radius: var(--w11-radius-overlay);
  background: var(--w11-flyout);
  box-shadow: var(--w11-shadow-flyout);
  -webkit-backdrop-filter: blur(30px) saturate(125%);
  backdrop-filter: blur(30px) saturate(125%);
  color: var(--w11-text);
  font-family: var(--w11-font);
}

/* Windows context menus have no heading. */
.context-menu__title {
  display: none;
}

.context-menu__actions {
  gap: 0;
}

.context-menu__item {
  gap: 12px;
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--w11-radius-control);
  color: var(--w11-text);
  font-size: 13px;
}

.context-menu__item:hover:not(:disabled) {
  background: var(--w11-subtle-hover);
}

.context-menu__item-icon,
.context-menu__item:hover .context-menu__item-icon,
.context-menu__item.is-danger,
.context-menu__item.is-danger .context-menu__item-icon {
  color: var(--w11-text);
}

.context-menu__item-shortcut {
  color: var(--w11-text-2);
  font-size: 12px;
  opacity: 1;
}

.context-menu__separator {
  margin: 4px -4px;
  background: var(--w11-divider);
}

/* ------------------------------------------------------------ File Explorer */

.w11-explorer {
  --w11-explorer-chrome: #202020;
  --w11-explorer-content: #191919;
  --w11-explorer-line: rgba(255, 255, 255, 0.06);
  --w11-explorer-field: rgba(255, 255, 255, 0.045);
  --w11-explorer-selected: rgba(255, 255, 255, 0.1);
  --w11-explorer-disabled: rgba(255, 255, 255, 0.36);

  background: var(--w11-explorer-content);
  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 13px;
}

.w11-explorer__chrome {
  display: grid;
  gap: 4px;
  padding: 6px 8px 4px;
  border-bottom: 1px solid var(--w11-explorer-line);
  background: var(--w11-explorer-chrome);
}

.w11-explorer__address-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.w11-explorer__nav {
  display: flex;
  flex: none;
  gap: 2px;
}

.w11-explorer__nav-button,
.w11-explorer__command,
.w11-explorer__status-view {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  white-space: nowrap;
  cursor: default;
}

.w11-explorer__nav-button:hover:not(:disabled),
.w11-explorer__command:hover:not(:disabled),
.w11-explorer__status-view:hover {
  background: var(--w11-subtle-hover);
}

.w11-explorer__nav-button:disabled,
.w11-explorer__command:disabled {
  color: var(--w11-explorer-disabled);
}

.w11-explorer__address,
.w11-explorer__search {
  display: flex;
  align-items: center;
  min-width: 0;
  height: 32px;
  border: 1px solid var(--w11-explorer-line);
  border-radius: var(--w11-radius-control);
  background: var(--w11-explorer-field);
}

.w11-explorer__address {
  flex: 1;
  padding: 0 4px 0 10px;
}

.w11-explorer__address.is-editing,
.w11-explorer__search:focus-within {
  border-bottom: 2px solid var(--w11-accent);
  background: #1c1c1c;
}

.w11-explorer__address-input,
.w11-explorer__search input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  outline: none;
}

.w11-explorer__address-icon {
  display: grid;
  flex: none;
}

.w11-explorer__crumbs {
  display: flex;
  min-width: 0;
  align-items: center;
  overflow: hidden;
}

.w11-explorer__crumb-group {
  display: inline-flex;
  flex: none;
  align-items: center;
}

.w11-explorer__crumb-separator {
  margin: 0 2px;
  color: var(--w11-text-2);
}

.w11-explorer__crumb {
  height: 26px;
  padding: 0 6px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  white-space: nowrap;
  cursor: default;
}

.w11-explorer__crumb:hover {
  background: var(--w11-subtle-hover);
}

.w11-explorer__address-fill {
  flex: 1;
  align-self: stretch;
  min-width: 24px;
  border: 0;
  background: transparent;
  cursor: text;
}

.w11-explorer__search {
  flex: 0 1 260px;
  gap: 8px;
  min-width: 120px;
  padding: 0 10px;
  color: var(--w11-text-2);
}

.w11-explorer__search input::placeholder {
  color: var(--w11-text-2);
}

.w11-explorer__commandbar {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: 2px;
  overflow-x: auto;
  scrollbar-width: none;
}

.w11-explorer__command-slot {
  display: inline-flex;
  align-items: center;
}

.w11-explorer__command-divider {
  width: 1px;
  height: 20px;
  margin: 0 6px;
  background: var(--w11-explorer-line);
}

.w11-explorer__command.has-label {
  padding: 0 10px;
}

.w11-explorer :is(button, input):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

/* Navigation pane */
.w11-explorer .explorer-window__layout,
.w11-explorer .explorer-window__content {
  background: var(--w11-explorer-content);
}

.w11-explorer .explorer-window__sidebar {
  width: 200px;
  padding: 6px;
  border-right: 1px solid var(--w11-explorer-line);
  background: var(--w11-explorer-chrome);
}

.w11-explorer .explorer-window__sidebar-heading {
  display: none;
}

.w11-explorer .explorer-window__sidebar-item {
  position: relative;
  justify-content: flex-start;
  gap: 10px;
  height: 32px;
  min-height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  box-shadow: none;
  color: var(--w11-text);
  font-size: 13px;
  font-weight: 400;
}

.w11-explorer .explorer-window__sidebar-item:hover {
  background: var(--w11-subtle-hover);
}

.w11-explorer .explorer-window__sidebar-item.is-active {
  background: var(--w11-explorer-selected);
}

/* The accent pill Windows draws beside the selected navigation item. */
.w11-explorer .explorer-window__sidebar-item.is-active::before {
  position: absolute;
  top: 50%;
  left: 0;
  width: 3px;
  height: 16px;
  border-radius: 2px;
  background: var(--w11-accent);
  content: "";
  transform: translateY(-50%);
}

/* Large icons */
.w11-explorer .explorer-grid-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 4px;
  border: 1px solid transparent;
  border-radius: var(--w11-radius-control);
  background: transparent;
  box-shadow: none;
  color: var(--w11-text);
}

.w11-explorer .explorer-grid-item__thumb {
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
  border: 0;
  background: none;
  box-shadow: none;
}

.w11-explorer .explorer-grid-item__thumb img {
  max-width: 64px;
  max-height: 64px;
  border-radius: 2px;
  object-fit: contain;
}

.w11-explorer .explorer-grid-item__label {
  display: -webkit-box;
  overflow: hidden;
  font-size: 12px;
  text-align: center;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row):hover {
  background: var(--w11-subtle-hover);
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row).is-selected {
  border-color: rgba(255, 255, 255, 0.08);
  background: var(--w11-explorer-selected);
}

.w11-explorer :is(.explorer-grid-item, .w11-details__row).is-drop-target {
  border-color: var(--w11-accent);
  background: rgba(96, 205, 255, 0.14);
}

/* Cut items stay faded until they are pasted. */
.w11-explorer .is-cut {
  opacity: 0.5;
}

/* Details */
.w11-details {
  --w11-details-columns: minmax(180px, 3fr) minmax(130px, 1.5fr) minmax(110px, 1.3fr) minmax(64px, 0.7fr);

  display: flex;
  min-width: 520px;
  flex-direction: column;
  font-size: 12px;
}

.w11-details__header {
  position: sticky;
  z-index: 1;
  top: 0;
  display: grid;
  grid-template-columns: var(--w11-details-columns);
  border-bottom: 1px solid var(--w11-explorer-line);
  background: var(--w11-explorer-content);
}

.w11-details__column {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-right: 1px solid var(--w11-explorer-line);
  background: transparent;
  color: var(--w11-text-2);
  font: inherit;
  text-align: left;
  cursor: default;
}

.w11-details__column:hover:not(:disabled) {
  background: var(--w11-subtle-hover);
  color: var(--w11-text);
}

.w11-explorer .w11-details__row.explorer-list-item {
  display: grid;
  grid-template-columns: var(--w11-details-columns);
  align-items: center;
  height: 30px;
  min-height: 30px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--w11-radius-control);
  background: transparent;
  box-shadow: none;
  color: var(--w11-text);
}

.w11-details__cell {
  overflow: hidden;
  padding: 0 10px;
  color: var(--w11-text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-details__name {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--w11-text);
}

.w11-details__icon {
  display: grid;
  flex: none;
}

.w11-details__label {
  overflow: hidden;
  text-overflow: ellipsis;
}

.w11-details__size {
  text-align: right;
}

/* Status bar */
.w11-explorer .w11-explorer__status {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 28px;
  min-height: 28px;
  padding: 0 8px 0 12px;
  border-top: 0;
  background: var(--w11-explorer-content);
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-explorer__status-size {
  margin-left: 12px;
}

.w11-explorer__status-spacer {
  flex: 1;
}

.w11-explorer .w11-explorer__status-view {
  min-width: 28px;
  height: 24px;
  padding: 0 6px;
}

.w11-explorer .w11-explorer__status-view.is-active {
  background: var(--w11-explorer-selected);
}

@media (max-width: 720px) {
  .w11-explorer .explorer-window__sidebar {
    display: none;
  }

  .w11-explorer__search {
    flex-basis: 140px;
  }
}

/* ----------------------------------------------------------------- Browser */

/* The tab strip can be portaled into the window title bar, so it carries the tokens too. */
.w11-browser,
.w11-browser__tabs {
  --w11-browser-strip: #202020;
  --w11-browser-surface: #2b2b2b;
  --w11-browser-field: #1c1c1c;
  --w11-browser-line: rgba(255, 255, 255, 0.07);

  color: var(--w11-text);
  font-family: var(--w11-font);
  font-size: 13px;
}

.w11-browser {
  display: flex;
  flex-direction: column;
  background: var(--w11-browser-surface);
}

.w11-browser :is(button, input):focus-visible,
.w11-browser__tabs :is([role="tab"], button):focus-visible {
  outline: 2px solid var(--w11-focus-outer);
  outline-offset: -2px;
}

/* The pill around these fields already shows focus; a second ring inside it looked broken. */
.w11-browser .w11-browser__address input:focus-visible,
.w11-browser .w11-newtab__search input:focus-visible {
  outline: none;
}

/* Tab strip */
.w11-browser__tabs {
  display: flex;
  flex: none;
  align-items: flex-end;
  gap: 2px;
  min-width: 0;
  padding: 6px 8px 0;
  overflow-x: auto;
  background: var(--w11-browser-strip);
  scrollbar-width: none;
}

/* Tabs in the title bar: the strip fills the space left of the caption buttons and the bar grows to fit. */
.w11-titlebar--tabs.window-frame__header {
  height: 40px;
  padding-left: 0;
  gap: 0;
}

.w11-titlebar__slot {
  display: flex;
  min-width: 0;
  flex: 1;
  align-self: stretch;
}

.w11-titlebar__slot .w11-browser__tabs {
  flex: 1;
  padding: 6px 8px 0;
  background: transparent;
}

.w11-titlebar__hidden-title {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.w11-browser__tab {
  display: flex;
  min-width: 72px;
  max-width: 220px;
  flex: 0 1 220px;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 6px 0 10px;
  border-radius: 8px 8px 0 0;
  color: var(--w11-text-2);
  cursor: default;
  user-select: none;
}

.w11-browser__tab:hover {
  background: rgba(255, 255, 255, 0.05);
}

.w11-browser__tab.is-active {
  background: var(--w11-browser-surface);
  color: var(--w11-text);
}

.w11-browser__tab-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 16px;
}

.w11-browser__tab-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-browser__tab-close,
.w11-browser__new-tab {
  display: grid;
  flex: none;
  place-items: center;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: inherit;
  cursor: default;
}

.w11-browser__tab-close {
  width: 22px;
  height: 22px;
}

.w11-browser__new-tab {
  width: 32px;
  height: 30px;
  margin: 0 0 2px 2px;
  color: var(--w11-text);
}

.w11-browser__tab-close:hover,
.w11-browser__new-tab:hover {
  background: rgba(255, 255, 255, 0.09);
}

/* Panels: inactive tabs stay mounted (their pages keep running) but hidden. */
.w11-browser__body {
  position: relative;
  display: flex;
  min-height: 0;
  flex: 1;
}

.w11-browser__panel {
  display: none;
  min-width: 0;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}

.w11-browser__panel.is-active {
  display: flex;
}

/* Toolbar */
.w11-browser__toolbar {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
  padding: 6px 8px;
  background: var(--w11-browser-surface);
}

.w11-browser__tool {
  display: grid;
  flex: none;
  place-items: center;
  width: 34px;
  height: 32px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  cursor: default;
}

.w11-browser__tool:hover:not(:disabled) {
  background: var(--w11-subtle-hover);
}

.w11-browser__tool:disabled {
  color: rgba(255, 255, 255, 0.32);
}

.w11-browser .is-spinning,
.w11-browser__tabs .is-spinning {
  animation: w11-spin 0.9s linear infinite;
}

@keyframes w11-spin {
  to {
    transform: rotate(360deg);
  }
}

.w11-browser__address {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 6px;
  height: 32px;
  margin: 0 4px;
  padding: 0 4px 0 10px;
  border: 1px solid transparent;
  border-radius: 16px;
  background: var(--w11-browser-field);
}

.w11-browser__address.is-editing {
  border-color: var(--w11-accent);
}

.w11-browser__address input {
  min-width: 0;
  flex: 1;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 13px;
  outline: none;
}

.w11-browser__address input::placeholder {
  color: var(--w11-text-2);
}

.w11-browser__security {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 4px;
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-browser__security.is-insecure {
  color: #ffb4a8;
}

.w11-browser__star {
  display: grid;
  flex: none;
  place-items: center;
  width: 28px;
  height: 26px;
  border: 0;
  border-radius: 13px;
  background: transparent;
  color: var(--w11-text-2);
  cursor: default;
}

.w11-browser__star:hover:not(:disabled) {
  background: var(--w11-subtle-hover);
  color: var(--w11-text);
}

.w11-browser__star.is-favorite {
  color: #60cdff;
}

.w11-browser__star.is-favorite svg {
  fill: currentColor;
}

.w11-browser__star:disabled {
  opacity: 0.35;
}

/* Favorites bar */
.w11-browser__favorites {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 0 8px 6px;
  overflow-x: auto;
  border-bottom: 1px solid var(--w11-browser-line);
  background: var(--w11-browser-surface);
  scrollbar-width: none;
}

.w11-browser__favorite {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 6px;
  max-width: 180px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: default;
}

.w11-browser__favorite span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-browser__favorite:hover {
  background: var(--w11-subtle-hover);
}

.w11-site-badge {
  display: inline-grid;
  flex: none;
  place-items: center;
  border-radius: 50%;
  color: #ffffff;
  font-family: var(--w11-font);
  font-weight: 600;
  line-height: 1;
}

.w11-browser__viewport.browser-app__viewport {
  position: relative;
  display: flex;
  min-height: 0;
  flex: 1;
  background: #ffffff;
}

/* New tab page */
.w11-newtab,
.w11-history {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: #1f1f1f;
  color: var(--w11-text);
  scrollbar-color: rgba(255, 255, 255, 0.25) transparent;
  scrollbar-width: thin;
}

.w11-newtab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  padding: 12vh 24px 32px;
}

.w11-newtab__search {
  display: flex;
  width: min(580px, 100%);
  align-items: center;
  gap: 12px;
  height: 46px;
  padding: 0 18px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 23px;
  background: #2b2b2b;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.26);
  color: var(--w11-text-2);
}

.w11-newtab__search:focus-within {
  border-color: var(--w11-accent);
}

.w11-newtab__search input {
  min-width: 0;
  flex: 1;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 15px;
  outline: none;
}

.w11-newtab__links {
  display: grid;
  width: min(640px, 100%);
  /* auto-fit keeps the six default shortcuts on one row instead of orphaning the last one. */
  grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
  gap: 8px;
}

.w11-newtab__link {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 14px 6px 10px;
  border: 0;
  border-radius: var(--w11-radius-overlay);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  font-size: 12px;
  cursor: default;
}

.w11-newtab__link span {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-newtab__link:hover,
.w11-newtab__recent-row:hover {
  background: var(--w11-subtle-hover);
}

.w11-newtab__recent {
  display: grid;
  width: min(580px, 100%);
  gap: 2px;
}

.w11-newtab__recent h2,
.w11-history__group h2 {
  margin: 0 0 6px;
  color: var(--w11-text-2);
  font-size: 13px;
  font-weight: 600;
}

.w11-newtab__recent-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  height: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  text-align: left;
  cursor: default;
}

.w11-newtab__recent-row span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-newtab__recent-row small {
  margin-left: auto;
  color: var(--w11-text-2);
}

.w11-newtab__note {
  max-width: 520px;
  margin: 0;
  color: var(--w11-text-2);
  font-size: 12px;
  text-align: center;
}

/* History page */
.w11-history {
  padding: 24px clamp(16px, 5vw, 64px);
}

.w11-history__header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.w11-history__header h1 {
  flex: 1;
  margin: 0;
  font-size: 22px;
  font-weight: 600;
}

.w11-history__header .w11-button {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 8px;
}

.w11-history__search {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 240px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--w11-radius-control);
  background: #2b2b2b;
  color: var(--w11-text-2);
}

.w11-history__search input {
  min-width: 0;
  flex: 1;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  outline: none;
}

.w11-history__group {
  display: grid;
  gap: 2px;
  margin-bottom: 18px;
}

.w11-history__row {
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--w11-radius-control);
}

.w11-history__row:hover {
  background: var(--w11-subtle-hover);
}

.w11-history__open {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 10px;
  height: 36px;
  padding: 0 10px;
  border: 0;
  background: transparent;
  color: var(--w11-text);
  font: inherit;
  text-align: left;
  cursor: default;
}

.w11-history__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-history__host,
.w11-history__row time {
  flex: none;
  color: var(--w11-text-2);
  font-size: 12px;
}

.w11-history__remove {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  margin-right: 4px;
  border: 0;
  border-radius: var(--w11-radius-control);
  background: transparent;
  color: var(--w11-text-2);
  cursor: default;
}

.w11-history__remove:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--w11-text);
}

.w11-history__empty {
  color: var(--w11-text-2);
}

/* Embed-refused page */
.w11-browser__error {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 32px;
  background: #1f1f1f;
  color: var(--w11-text);
  text-align: center;
}

.w11-browser__error h2 {
  max-width: 520px;
  margin: 8px 0 0;
  font-size: 20px;
  font-weight: 600;
}

.w11-browser__error p {
  max-width: 520px;
  margin: 0;
  color: var(--w11-text-2);
}

.w11-browser__error-details {
  font-size: 12px;
}

.w11-browser__error code {
  max-width: 100%;
  overflow: hidden;
  color: var(--w11-text-2);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.w11-browser__error-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 8px;
}

.w11-browser__error-actions .w11-button {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 8px;
}

.w11-browser .w11-button {
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

.w11-browser .w11-button--accent {
  border-color: transparent;
  background: #60cdff;
  color: #000000;
}

.w11-browser .w11-button:disabled {
  opacity: 0.45;
}

@media (prefers-reduced-motion: reduce) {
  .w11-browser .is-spinning,
  .w11-browser__tabs .is-spinning {
    animation: none;
  }
}

/* ----------------------------------------------------------------- phones */

/* The "use the quick view" tip, as a Windows notification instead of a dark pill. */
@media (max-width: 520px) {
  /* Explorer: keep Back and Up, give the address bar the room, search on its own row. */
  .w11-explorer__nav-button[aria-label^="Forward"],
  .w11-explorer__nav-button[aria-label^="Refresh"] {
    display: none;
  }

  .w11-explorer__address-row {
    flex-wrap: wrap;
  }

  .w11-explorer__search {
    flex: 1 1 100%;
  }

  /* Icon-only commands, so Sort and View fit without sideways scrolling. */
  .w11-explorer__command.has-label span {
    display: none;
  }

  /* Browser: Back and Refresh stay; Forward and Home make way for the address. */
  .w11-browser__tool[aria-label^="Forward"],
  .w11-browser__tool[aria-label^="Home"] {
    display: none;
  }
}

/* Pages fill the browser edge to edge; the old viewport padding showed as a white frame. */
.w11-browser__viewport.browser-app__viewport {
  padding: 0;
}

